a\";s:34:\"https://openchannels.fm/?p=2558504\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"https://openchannels.fm/software-lock-in-and-ai-tools-for-modern-web-businesses/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:164:\"In this episode, Bob and Adam chat about managing digital workflows, tackling challenges like email overload, CRM usage, and the benefits and downsides of AI tools.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 11 Aug 2026 12:33:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"Open Channels FM: How AI Agents Target Open Source and Why Storage Is the New AI Bottleneck\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558546\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://openchannels.fm/how-ai-agents-target-open-source-and-why-storage-is-the-new-ai-bottleneck/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:221:\"An AI experiment revealed vulnerabilities as an agent attempted to manipulate an open source maintainer into merging malware, while Nvidia highlighted storage bottlenecks in AI infrastructure. Efficiency is now paramount.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 11 Aug 2026 10:03:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"Aaron D. Campbell: My WordPress Origin Story: The One-Line Patch That Changed My Career\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://aarondcampbell.com/?p=3122\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"https://aarondcampbell.com/2026/08/wordpress-origin-story/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:430:\"<p>I started using WordPress because it was a practical tool for client work. One tiny patch turned it into a community, a career, and a lasting lesson about what open source makes possible.</p>\n<p>The post <a href=\"https://aarondcampbell.com/2026/08/wordpress-origin-story/\">My WordPress Origin Story: The One-Line Patch That Changed My Career</a> appeared first on <a href=\"https://aarondcampbell.com\">Aaron D. Campbell</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 11 Aug 2026 00:42:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Aaron D. Campbell\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:25:\"Matt: OmFest Registration\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=154020\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:42:\"https://ma.tt/2026/08/omfest-registration/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1630:\"<p class=\"wp-block-paragraph\">Thank you to everyone who expressed interest in shaping OmFest. We&#8217;re still working out some details, but <a href=\"https://luma.com/om-fest\">we&#8217;ve got a Luma registration page for the event up</a>. Please join on September 29, 2026, Om&#8217;s 60th birth anniversary, for an eclectic conference curated by his different communities to celebrate the many facets of <a href=\"https://om.co/\">Om</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re just tuning in, <a href=\"https://ma.tt/2026/06/om-forever/\">our dearest loved one Om Malik passed away in June</a>. This grieving process has been a rough one for me, but it has inspired some positive life changes. I&#8217;m traveling with a real camera again! <a href=\"https://www.kenrockwell.com/nikon/d6.htm\">A Nikon D6</a>. I&#8217;ve shot tens of thousands of frames on the D-series, so it feels like home, but it also has some nice new features like built-in GPS (I used to use an attachment for that) and USB-C. </p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;ve also become very driven to be meticulous. I miss Om&#8217;s harsh but often true feedback, but his voice in my head is a good reminder that if you do something, it&#8217;s worth doing it well. I&#8217;m kinda a hot mess (still blessed! <img alt=\"😂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f602.png\" style=\"height: 1em;\" />) so this will be a journey but the progress already has been rewarding. Excellence is a habit. We can always hold ourselves to <a href=\"https://generalanndunwoody.com/a-higher-standard/\">a higher standard</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 10 Aug 2026 21:54:47 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"Open Channels FM: How AI Is Shaping Domain Abuse Monitoring\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2557238\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://openchannels.fm/how-ai-is-shaping-domain-abuse-monitoring/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:203:\"AI is becoming crucial for monitoring domain abuse, enabling automated analysis and real-time detection. However, careful oversight is essential to avoid errors, especially as domain registrations surge.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 10 Aug 2026 12:20:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"Matt: Super-organized\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153997\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:38:\"https://ma.tt/2026/08/super-organized/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:830:\"<p class=\"wp-block-paragraph\">I have so many tools for organization and management across <a href=\"https://asana.com/\">Asana</a>, <a href=\"https://workspace.google.com/\">Google Workspace</a>, <a href=\"https://wordpress.com/p2/\">P2</a>, and <a href=\"https://linear.app/\">Linear</a>, but they&#8217;re not really connected. I&#8217;m trying to get everything in one place so there&#8217;s no data duplication, a single source of truth, and everything is always linked and accessible. It feels good, like spring cleaning, to go through everything. <a href=\"https://woocommerce.com/\">Woo</a> has an initiative they call <a href=\"https://en.wikipedia.org/wiki/Mise_en_place\">Mise en place</a> with a similar idea. Which is why you&#8217;ve also seen those bug fixes and clean-up happening. With AI, this should be easier than ever.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 09 Aug 2026 23:54:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:123:\"Gutenberg Times: WordPress 7.1 RC, 7.0.3 Security Release, Block Runner, New Playground UI and more — Weekend Edition 372\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46483\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:127:\"https://gutenbergtimes.com/wordpress-7-1-rc-7-0-3-security-release-block-runner-new-playground-ui-and-more-weekend-edition-372/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:21741:\"<p class=\"wp-block-paragraph\">Hi there, </p>\n\n\n\n<p class=\"wp-block-paragraph\">It was another busy release week: the WordPress 7.0.3 security update, WordPress 7.1 RC 1, and Gutenberg 23.7 all landed. More on each below — but before you keep reading, update all your sites to 7.0.3 now. This newsletter can wait… <img alt=\"😉\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f609.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><br />If you are traveling to Phoenix: safe travels, and pack a sweater — the AC will be cranked up high in every building! This year, I will see you on the WCUS Livestream.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Have a great weekend! </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/08/wordpress-7-0-3-release/\"><strong>WordPress 7.0.3</strong> </a>shipped as a security release fixing twelve vulnerabilities, so <strong>update your sites right away</strong> if automatic background updates aren&#8217;t already handling it for you. Release lead <strong>John Blackbourn</strong> lists the fixes, including a pre-auth XSS on the login screen that could lead to PHP code execution, several contributor-level stored XSS issues, and a multisite privilege escalation. Backports reach all supported branches down to 4.7, and 7.1 RC2 carries the fixes too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To appreciate the huge effort by the security team to get this release out, consider the numbers: until earlier this year, there were 20 to 30 reports per month; now that number has jumped to 450 per month. Both security updates, 7.0.2 and 7.0.3, were backported not only to the two officially supported versions, 6.9 and 7.0, but all the way back to version 4.7. That&#8217;s two dozen major versions that needed updating. See also <strong>Rae Morey&#8217;s</strong> story in The Repository: <a href=\"https://www.therepository.email/wordpress-7-0-3-patches-12-vulnerabilities-as-bug-bounty-reports-climb-to-450-a-month\"><strong>WordPress 7.0.3 Patches 12 Vulnerabilities as Bug Bounty Reports Climb to 450 a Month</strong></a>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">August 19 is the scheduled final release date, and <strong>Benjamin Zekavica</strong> announces <a href=\"https://wordpress.org/news/2026/08/wordpress-7-1-release-candidate-1/\"><strong>WordPress 7.1 Release Candidate 1</strong></a> ready for your test sites. Since Beta 4, more than 145 updates landed — 57 in the Editor, 88 in Core — plus new features like the Icons API, shareable revision links, and email notifications for @mentions in Notes. Plugin and theme authors: wrap up testing and bump your &#8220;Tested up to&#8221; to 7.1. WordPress Playground lets you try it straight in the browser. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Milana Cap </strong>counts more than 310 Core Trac tickets, twenty new hooks, and roughly 600 Gutenberg enhancements in <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\"><strong>the WordPress 7.1 Field Guide</strong></a>, your linked index of every dev note for the August 19 release. Highlights range from client-side media processing and the always-iframed post editor to the SVG Icon API, responsive block styles, and the persistent admin bar. A candid closing section covers what didn&#8217;t make it, from the Classic block&#8217;s reprieve to real-time collaboration and React 19.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">The post editor is always iframed in WordPress 7.1, and the escape hatch that let one apiVersion 2 block pull a whole post out of the iframe disappears. That&#8217;s the compatibility risk topping <strong><a href=\"https://www.unleash-wp.com/blog/wordpress-7-1-developer-guide/\">the developer&#8217;s audit list for WordPress 7.1</a> </strong>by release coordinator <strong>Benjamin Zekavica.</strong> He sorts each section by risk level, walks through the SVG Icon API&#8217;s strict sanitizer, responsive block styles, and the new DataViews filters, and closes with a checklist for your August 19 release.</p>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-133-gutenberg-23-6-release-and-wordpress-7-1/\">Gutenberg Changelog #133 – Gutenberg 23.6 Release and WordPress 7.1</a></p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46424\" height=\"186\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-07-31-at-13.13.07.png?resize=652%2C186&#038;ssl=1\" width=\"652\" /></figure>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div></div></div>\n\n\n\n<p class=\"wp-block-paragraph\">The Gallery block&#8217;s ambiguous &#8220;Convert to images&#8221; button becomes &#8220;Detach,&#8221; complete with a modal explaining what happens — one of many refinements <strong>Jonathan Bossenger</strong> walks through in <strong><a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">what&#8217;s new in Gutenberg 23.7</a>. </strong>You&#8217;ll also find the Global Styles inheritance UI now opt-in via the Experiments page, LaTeX errors in the Math block waiting until you leave the field, and fixes for floated blocks overlapping sticky ones and Pullquote line heights in the editor.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins and Tools for #nocode site builders</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Variable product pages load roughly 9 to 12 percent faster and large stores get snappier Order screens, <strong>Brent MacKinnon</strong> reports in <strong><a href=\"https://woocommerce.com/posts/woocommerce-11-0-update/\">what&#8217;s new in WooCommerce 11.0</a>.</strong> Analytics also grows more trustworthy: refunds now count in the period they happened, session counts exclude bots, and you can rerun incomplete historical imports. Guest customers can claim past orders when they create an account, and a Checkout Recovery beta lets you test messaging before a full rollout.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Getting Site Editor changes out of the database and into version control has frustrated agency developers for years, and <strong>Brian Coords</strong> argues agents make it urgent again. His experimental <a href=\"https://www.briancoords.com/an-agent-first-approach-to-create-block-theme/\"><strong>agent-first approach to Create Block Theme</strong></a>, wp-theme-control, wraps the upcoming WP-CLI 3.0 wp block commands in bash scripts and an agent skill: a plan command lists database changes, then you dry-run, export them into your theme, and optionally clear the database copies. He&#8217;s collecting feedback ahead of his WordCamp US talk.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Clients pinning comments straight onto your live pages — no logins, no email chains, no PDF round-trips — is the pitch of <strong>Ben Elwood</strong>&#8216;s <a href=\"https://wordpress.org/plugins/reviso-for-bricks/\"><strong>Reviso client feedback and approvals</strong> plugin</a>. Among other page builders it&#8217;s native to the block editor, with threaded replies, status tracking, and review links that work even in maintenance mode. Version 1.5.2 switches on Suggest mode by default, so reviewers propose wording changes like tracked changes and your team applies them with one click.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Bas Buis </strong>released <strong><a href=\"https://wpinsight.eu/dynamic-osm-maps-wordpres-gutenberg-plugin/\">Dynamic OSM Maps, </a></strong>a plugin<strong> </strong>that adds interactive maps without Google API keys or recurring fees. The lightweight block runs on OpenStreetMap and Leaflet: in the free version you enter addresses manually, while Pro connects your custom fields — coordinates, addresses, or repeaters — for unlimited markers and popups. That opens the door for directory and listing sites to render stored location data straight onto the map.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Emily Rapport</strong> opens with Dutch tulip mania to frame the rush of llms.txt files and AI-visibility subscriptions, then does something rarer: shares <a href=\"https://alwaysopen.design/ai-search-case-study/\"><strong>a year of her own content work with real Search Console data</strong></a>. Her rewritten maintenance page climbed from position 50 to 13 and collected exactly five clicks — yet three inquiries arrived saying &#8220;I asked ChatGPT.&#8221; Her takeaway: publishing consistently across real topics beats chasing one niche, and you still can&#8217;t reliably trace an AI recommendation to a page.</p>\n\n\n<div class=\"ng-block-a9d7cb0c9181995d wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\"><div class=\"ng-block-3f02eecb899511f1 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p></div></div></div></div>\n\n<div class=\"ng-block-25ec57649f685f55 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools </h2>\n\n\n\n<p class=\"wp-block-paragraph\">The WooCommerce Developer Blog follows up its All Products proof of concept with the why behind it. <strong>Veronica Fasulo</strong> and co-authors lay out <a href=\"https://developer.woocommerce.com/2026/08/05/the-value-of-dataviews/\"><strong>the value of DataViews and who it&#8217;s for</strong></a>: you describe a field once and it powers the list column, Quick Edit, bulk edit, and forms, instead of four hand-wired implementations. Merchants get switchable views without page reloads, extension developers get registration instead of DOM patching — and the team openly asks whether DataViews is even the right foundation.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\">What&#8217;s new in Playground? </h2>\n\n\n\n<p class=\"wp-block-paragraph\">A customizable Dock, auto-save, and live visual previews of your saved instances headline <a href=\"https://wordpress.tv/2026/08/06/new-wordpress-playground-ui/\"><strong>the new WordPress Playground UI</strong></a>, which <strong>Fellyph Cintra</strong> demos on WordPress.tv. The video walks through importing projects from GitHub or Zip files, previewing Core and Gutenberg pull requests, and the built-in file editor, database manager, and error logs — plus switching WordPress versions all the way back to 0.7. Feedback goes to the <a href=\"https://make.wordpress.org/playground/\">Make Playground blog</a> or the <a href=\"https://wordpress.slack.com/archives/C04EWKGDJ0K\">#playground</a> Slack channel.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-in-wordpress\">AI in WordPress </h2>\n\n\n\n<p class=\"wp-block-paragraph\">Vercel, a major platform shipped the <a href=\"https://wordpress.org/plugins/vercel-ai-gateway-provider/\"><strong>Vercel AI Gateway Provider</strong></a> plugin, by former Core AI team rep <strong>Felix Arntz.</strong>  One API key unlocks hundreds of models from over 40 providers. Any AI Client plugin on your site can route text, image, and video generation through the Gateway — including the Photo to Post demo from <a href=\"https://developer.wordpress.org/news/2026/07/build-your-first-ai-powered-wordpress-plugin/\">Jonathan Bossenger&#8217;s tutorial</a>. Automatic fallbacks kick in during provider outages, and you pay provider rates without platform fees.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Your AI agent designs a beautiful page, and Gutenberg freezes it into one uneditable Custom HTML blob. Human Made&#8217;s answer is <a href=\"https://github.com/humanmade/block-runner\"><strong>Block Runner, now open-sourced on GitHub</strong></a>: a deterministic Node CLI that converts generated HTML into properly nested native blocks — wp:cover, wp:columns, wp:buttons — with real attachment IDs, and validates every result against headless Gutenberg. In the team&#8217;s benchmark, raw models writing block markup score 35 to 73; paired with Block Runner, the same models hit 93 to 99.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Readers may remember <strong><a href=\"https://gutenbergtimes.com/block-format-bridge-a-practical-solution-for-ai-generated-content-in-wordpress/\">Chris Huber&#8217;s Block Format Bridge</a> </strong>from a few months back — it tackles the same gap from inside WordPress, converting Markdown and HTML server-side at insert time, while Block Runner works the pipeline side with its validation gate and CI hooks. Two open-source answers to the same question is a good sign the agentic content problem is getting real attention. </p>\n\n\n\n<p class=\"wp-block-paragraph\">A third piece of the puzzle: the official <a href=\"https://github.com/WordPress/agent-skills\"><strong>WordPress agent-skills repository</strong></a> takes the prevention route, teaching AI coding assistants to write valid block markup in the first place. For a lighter-weight approach, you can also point your AI agent straight at the updated <strong><a href=\"https://developer.wordpress.org/block-editor/reference-guides/core-blocks/\">Core Blocks Reference</a>,</strong> where each block&#8217;s page now documents its markup, attributes, supports, and allowed nesting.</p>\n\n\n<div class=\"ng-block-4518b8660403815d wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\"><div class=\"ng-block-16ec1157f4ec14f4 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p></div></div></div></div>\n\n<div class=\"ng-block-c9cb5e261ebd376a wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></div></div></div></div>\n\n<div class=\"ng-block-ea85f727703efb81 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-95ec962826aa3cc6 wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\"><div class=\"ng-block-763d27ffa852ed00 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 14px; font-family: Helvetica; line-height: 0.2; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong>Featured Image: </strong></p></div></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 08 Aug 2026 08:18:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:19:\"Matt: Toni on Verge\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153959\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://ma.tt/2026/08/toni-on-verge/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:804:\"<p class=\"wp-block-paragraph\"><a href=\"https://toni.org/\">Toni Schneider</a>, Automattic&#8217;s founding CEO, <a href=\"https://automattic.com/board/\">board member</a>, and now <a href=\"https://techcrunch.com/2026/07/10/blueskys-interim-ceo-toni-schneider-drops-the-interim/\">CEO of Bluesky</a>, has a <a href=\"https://www.theverge.com/podcast/974387/bluesky-toni-schneider-interview-ai-atproto-atmosphere\">great conversation with Nilay Patel on The Verge&#8217;s Decoder podcast</a> (<a href=\"https://www.youtube.com/watch?v=F219IizDOnQ\">YouTube</a>, <a href=\"https://pca.st/lr0t25pr\">Pocket Casts</a>). <a href=\"https://automattic.com/\">Automattic</a> invested in <a href=\"https://bsky.app/\">Bluesky</a> back in 2023, and I&#8217;m very excited to see what they figure out in open social protocols.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 07 Aug 2026 19:30:22 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"Open Channels FM: Signal – Issue 19\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558144\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://openchannels.fm/signal-issue-19/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:142:\"This week\'s recap highlights key insights on human connection in AI, marketing challenges with Google Ads, and the importance of simple tasks.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 07 Aug 2026 10:58:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"WordPress.org blog: WordPress 7.0.3 release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21327\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/08/wordpress-7-0-3-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:8123:\"<h1 class=\"wp-block-heading\">WordPress 7.0.3 is now available</h1>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0.3 is now available which features several security fixes. Because this is a security release, it is recommended that you update your sites immediately.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can update to WordPress 7.0.3 by <a href=\"https://wordpress.org/wordpress-7.0.3.zip\">downloading it from WordPress.org</a>, or visiting your site&#8217;s Dashboard → Updates and clicking <strong>Update Now</strong>. Sites that support automatic background updates will begin updating shortly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-0-3/\">WordPress 7.0.3 HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people for responsibly reporting vulnerabilities and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Pre-auth reflected cross-site scripting (XSS) on the login screen with potential to lead to PHP code execution reported by the team at <a href=\"https://pwn.ai/\">pwn.ai</a>.</li>\n\n\n\n<li>Contributor+ stored cross-site scripting (XSS) in posts via the emoji settings element reported by Asaf Mozes (<a href=\"https://hackerone.com/amosec?type=user\">amosec</a>)</li>\n\n\n\n<li>Contributor+ stored cross-site scripting (XSS) in the Post Content block reported by <a href=\"https://hackerone.com/n05ec\">N05ec@LZU</a></li>\n\n\n\n<li>Contributor+ stored cross-site scripting (XSS) in Quick Edit on sites with a large number of users reported by <a href=\"https://www.linkedin.com/in/naveens72/\">Naveen S</a> and <a href=\"https://www.linkedin.com/in/ajmalmoochingal/\">Ajmal Moochingal</a></li>\n\n\n\n<li>Contributor+ stored cross-site scripting (XSS) in the Post Date block reported by <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a> of the WordPress Security Team</li>\n\n\n\n<li>A privilege escalation issue on multisite networks with user registration enabled, allowing a user to create a new site reported by <a href=\"https://aikido.dev/\">Aikido Security</a></li>\n\n\n\n<li>An information disclosure issue in the Latest Comments block exposing comments on password-protected posts reported by <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a> of the WordPress Security Team</li>\n\n\n\n<li>Enumeration of post slugs reported by <a href=\"https://hdwsec.fr/\">HDWSec</a></li>\n\n\n\n<li>Disclosure of notes in comment feeds reported by <a href=\"https://profiles.wordpress.org/odkdn1/\">Elio Gubser</a></li>\n\n\n\n<li>Author+ CSS injection via a bypass of the safe CSS attribute filter reported by Anthropic</li>\n\n\n\n<li>Bypass of the email address confirmation flow reported by <a href=\"https://www.linkedin.com/in/omr-h/\">Omar Hasan</a></li>\n\n\n\n<li>A server-side request forgery (SSRF) issue in URL validation allowing requests to link-local ranges reported by <a href=\"https://hackerone.com/andrewmohawk?type=user\">Andrew Mohawk</a> and multiple independent reporters</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, these fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 RC2 has also been released, containing all applicable fixes.</p>\n\n\n\n<h2 class=\"wp-block-heading\">CVE and GHSA references</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Details of the login screen XSS vulnerability can be found in the advisory: <a href=\"https://github.com/WordPress/wordpress-develop/security/advisories/GHSA-52p2-r8wf-jcrf\">CVE-2026-64638 / GHSA-52p2-r8wf-jcrf</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>. In addition to the security researchers mentioned above, WordPress 7.0.3 and its backports would not have been possible without the significant contributions of the following people:<br /><a href=\"https://profiles.wordpress.org/aaroncampbell\">Aaron D. Campbell</a>, <a href=\"https://profiles.wordpress.org/jorbin\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianmoldovanwp\">adrianmoldovanwp</a>, <a href=\"https://profiles.wordpress.org/wildworks\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/xknown\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/aduth\">Andrew Duthie</a>, <a href=\"https://profiles.wordpress.org/andrewserong\">Andrew Serong</a>, <a href=\"https://profiles.wordpress.org/annezazu\">annezazu</a>, <a href=\"https://profiles.wordpress.org/barry\">Barry</a>, <a href=\"https://profiles.wordpress.org/bernhard-reiter\">Bernie Reiter</a>, <a href=\"https://profiles.wordpress.org/villanovachile\">Daniel</a>, <a href=\"https://profiles.wordpress.org/talldanwp\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/davidbinda\">David Biňovec</a>, <a href=\"https://profiles.wordpress.org/dmsnell\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/erwanlr\">Erwan Le Rousseau</a>, <a href=\"https://profiles.wordpress.org/fabiankaegy/\">Fabian Kaegy</a>, <a href=\"https://profiles.wordpress.org/fiocavallari\">fiocavallari</a>, <a href=\"https://profiles.wordpress.org/mamaduka\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/odkdn1\">gubser</a>, <a href=\"https://profiles.wordpress.org/isabel_brison\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/jsnajdr\">Jarda Snajdr</a>, <a href=\"https://profiles.wordpress.org/audrasjb\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/jeremyfelt\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/joedolson\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joehoyle\">Joe Hoyle</a>, <a href=\"https://profiles.wordpress.org/johnbillion\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/jonsurrell\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/khokansardar\">Khokan Sardar</a>, <a href=\"https://profiles.wordpress.org/lancewillett\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/lucasbustamante\">lucasbustamante</a>, <a href=\"https://profiles.wordpress.org/lucatume\">lucatume</a>, <a href=\"https://profiles.wordpress.org/mciampini/\">Marco Ciampini</a>, <a href=\"https://profiles.wordpress.org/tyxla\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/batmoo\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/mukesh27\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/paulkevan\">Paul Kevan</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/ramonopoly\">ramonopoly</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov\">SergeyBiryukov</a>, <a href=\"https://profiles.wordpress.org/vortfu\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter\">Weston Ruter</a></p>\n\n\n\n<div class=\"wp-block-group is-layout-constrained wp-block-group-is-layout-constrained\">\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://us.wordcamp.org/2026/\" rel=\" noopener\" target=\"_blank\"><img alt=\"WordCamp US: Powered by WordPress, Driven by Community, August 16-19, 2026\" class=\"wp-image-20859\" height=\"321\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/06/wcus-2026-teaser.png?resize=1024%2C321&#038;ssl=1\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Join us for the launch of WordPress 7.1 at <a href=\"https://us.wordcamp.org/2026/\">WordCamp US 2026</a>, August 16–19.</figcaption></figure>\n</div>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 06 Aug 2026 18:55:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Matt: Our Core Division\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153863\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://ma.tt/2026/08/our-core-division/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2881:\"<p class=\"wp-block-paragraph\">Inspired by Automatticians <a href=\"https://jamesckemp.com/\">James Kemp</a> and <a href=\"https://aheadcreative.co.uk/\">Dave Smith</a>, I&#8217;ve been thinking a lot about how much of our discord in the design of WordPress stems from the differences of our two big tribes: Bloggers and Builders.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Many of <a href=\"https://profiles.wordpress.org/mikelittle/\">the</a> <a href=\"https://profiles.wordpress.org/donncha/\">OG</a> <a href=\"https://profiles.wordpress.org/ryan/\">developers</a> of WordPress, including myself, tend more towards the blogging side. Writers, photographers, podcasters, journalists, the people for whom a reverse chronological stream on the homepage is the most obvious thing in the world. We link out a lot, love comments, social features and think a lot about the editor as a writing environment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Builders are the site shapers, webmasters, the agencies, the companies, the content managers that think in a more page-first rather than post-first way. Tagging? Blogroll? Date-based permalinks? Who needs them. Give me custom fields, rich templates, a site editor, to craft beautiful sturdy pages that will stand the test of time. A store with a catalog of items where what changes is the inventory and ratings, not the content.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Builders right now dominate our core development discourse, which makes sense. They hold a lot of the economic share with <a href=\"https://woocommerce.com/\">merchants</a> and <a href=\"https://wordpress.org/showcase/\">rich websites</a>. They&#8217;re also more loyal. The Bloggers love their WordPress as the place they truly own and call home, but Bloggers have an account on every channel where there&#8217;s an audience, they syndicate out with an ephemerality mindset, because that reader/listener/follower connection is the spark that keeps their flame alive. A Builder would never be a <a href=\"https://ma.tt/2025/09/wordpresser/\">digital sharecropper</a> on someone else&#8217;s <a href=\"https://wordpress.com/domains/\">domain</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.youtube.com/watch?v=e5UZ7GyTDbk\">Dave Smith has been doing some very interesting explorations of a simpler site editor</a>, and you hear his Builder bias around 3:20 in how obvious a static homepage as default seems to him.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The good news is we can coexist as we have at least since <a href=\"https://wordpress.org/news/2005/02/strayhorn/\">WordPress 1.5</a>. We just need to give a little more love to the Blogger side, there&#8217;s so much cool stuff we could do in the Fediverse with RSS, <a href=\"https://activitypub.rocks/\">ActivityPub</a>, <a href=\"https://atproto.com/\">ATProto</a>, blogrolls (link manager is still in wp-admin!), pingbacks&#8230;</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 06 Aug 2026 12:06:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:80:\"Open Channels FM: Creative Insights and Real Talk on Modern Marketing Challenges\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558404\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://openchannels.fm/creative-insights-and-real-talk-on-modern-marketing-challenges/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:153:\"Marketing\'s evolving fast. Creators and businesses must adapt as SEO and ads fade. Experimentation and multi-channel strategies are key to surviving now.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 06 Aug 2026 09:45:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Matt: AutoMattBot\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153886\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://ma.tt/2026/08/automattbot/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:483:\"<p class=\"wp-block-paragraph\">I&#8217;m trying out this thing, it&#8217;s trained on my blog posts and public talks, that you can chat with as me on Telegram. Behold: <a href=\"https://t.me/AutoMattBot\">AutoMattBot</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Update: This is powered by <a href=\"https://www.delphi.ai/\">Delphi.ai</a> and it appears very broken right now, people are sending messages and on my side it looks like it&#8217;s responding but they&#8217;re not seeing it.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 06 Aug 2026 04:11:53 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordPress.org blog: WordPress 7.1 Release Candidate 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21248\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://wordpress.org/news/2026/08/wordpress-7-1-release-candidate-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:11315:\"<p class=\"wp-block-paragraph\">The first Release Candidate (“RC1”) for WordPress 7.1 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC1 on a test server and site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 RC1 can be tested using any of the following methods:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.1-RC1.zip\">RC1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br /><code>wp core update --version=7.1-</code>RC1</td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"https://playground.wordpress.net/?php=8.0&amp;wp=beta&amp;networking=no&amp;language=&amp;multisite=no&amp;random=y4q1rn88xn\" rel=\"noopener\" target=\"_blank\">WordPress Playground instance</a> to test the software directly in your browser.  No setup required – just click and go! </td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.1 is <strong>August 19, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/07/03/wordpress-7-1-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Please continue checking the <a href=\"https://make.wordpress.org/core/\" rel=\"noopener\" target=\"_blank\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-1\" rel=\"noopener\" target=\"_blank\">7.1-related posts</a> in the coming weeks for more information.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s in WordPress 7.1 RC1?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 RC1 contains more than <strong>145 updates</strong> and fixes since the Beta 4 release, including <strong>57 in the Editor</strong> and <strong>88 in Core</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For an overview of what’s new in WordPress 7.1, read the <a href=\"https://wordpress.org/news/2026/07/wordpress-7-1-beta-1/\" rel=\"noopener\" target=\"_blank\">Beta 1 announcement</a> and the <a href=\"https://make.wordpress.org/core/tag/dev-notes+7-1/\" rel=\"noopener\" target=\"_blank\">WordPress 7.1 Dev Notes</a>. For a comprehensive summary, see the <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\" rel=\"noopener\" target=\"_blank\">WordPress 7.1 Field Guide.</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">You can also explore the technical details of all issues addressed since Beta 4 using the links below:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.1?since=2026-07-29&amp;until=2026-08-05\" rel=\"noopener\" target=\"_blank\">GitHub commits for 7.1</a> since July 29, 2026</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=07%2F29%2F2026..08%2F05%2F2026&amp;milestone=7.1&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\" rel=\"noopener\" target=\"_blank\">Closed Trac tickets for 7.1</a> since July 29, 2026</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">New Features since Beta 1</h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/changeset/62748\" rel=\"noopener\" target=\"_blank\">Icons API</a>: New APIs for registering icons and icon collections in Core, ready for plugins to extend.</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/65624\" rel=\"noopener\" target=\"_blank\">Speculative loading configuration</a>: Speculative loading defaults can now be configured via environment variables and constants.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/79606\" rel=\"noopener\" target=\"_blank\">Email notifications for @mentions:</a> Email notifications have been introduced when mentioned in a Note.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/79934\" rel=\"noopener\" target=\"_blank\">Shareable Revisions:</a> Share links to specific revisions for faster collaboration.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Want to look deeper into the details and technical notes for this release? These tickets and pull requests are just some of the latest updates:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/79839\" rel=\"noopener\" target=\"_blank\">#GB-79839</a>: Apply globally: choose which modified block styles to apply</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/80814\" rel=\"noopener\" target=\"_blank\">#GB-80814</a>: New responsiveEditingEnabled editor setting to hide responsive styles</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/80107\" rel=\"noopener\" target=\"_blank\">#GB-80107</a>: Tabs: toolbar buttons to reorder tabs</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/pull/80046\" rel=\"noopener\" target=\"_blank\">#GB-80046</a>: DataViews: shift-click range selection</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/65636\" rel=\"noopener\" target=\"_blank\">#65636</a>: Preload REST API requests fetched on editor load</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/65613\" rel=\"noopener\" target=\"_blank\">#65613</a>: Notes are excluded from comment feed queries</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/65491\" rel=\"noopener\" target=\"_blank\">#65491</a>: KSES allows the autofocus attribute on dialog elements</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/65517\" rel=\"noopener\" target=\"_blank\">#65517</a>: Multisite upload limits are enforced when sideloading media from a URL</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/ticket/62757\" rel=\"noopener\" target=\"_blank\">#62757</a>: Update the jQuery UI library to version 1.14.2</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">How you can contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is open source software made possible by a passionate community of people collaborating on and contributing to its development. The resources below outline various ways you can help the world’s most popular open source web platform, regardless of your technical expertise.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Get involved in testing</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is crucial to the development of any software. It’s also a meaningful way for anyone to contribute. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.1 RC1 version is key to ensuring that the final release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/07/15/help-test-wordpress-7-1/\" rel=\"noopener\" target=\"_blank\">detailed guide</a> will walk you through testing features in WordPress 7.1.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Update your theme or plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">For plugin and theme authors, your products play an integral role in extending the functionality and value of WordPress for all users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks for continuing to test your themes and plugins with the WordPress 7.1 beta releases. With RC1, you’ll want to conclude your testing and update the <em>“Tested up to”</em> version in your <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\" rel=\"noopener\" target=\"_blank\">plugin’s readme file</a> to 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you find compatibility issues, please post detailed information to the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">support forum</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Test on your hosting platforms</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Web hosts provide vital infrastructure for supporting WordPress and its users. Testing on hosting systems helps inform the development process while ensuring that WordPress and hosting platforms are fully compatible, free of errors, optimized for the best possible user experience, and that updates roll out to customer sites without issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to test WordPress on your hosting system? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\" rel=\"noopener\" target=\"_blank\">Get started with configuring distributed hosting tests here</a>. Thank you to all <a href=\"https://make.wordpress.org/hosting/test-results/\" rel=\"noopener\" target=\"_blank\">web hosts who help test WordPress</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\" rel=\"noopener\" target=\"_blank\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\" rel=\"noopener\" target=\"_blank\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\" rel=\"noopener\" target=\"_blank\">Making WordPress Slack</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">An RC1 haiku</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>A candidate stands</em><br /><span style=\"white-space: normal;\"><em>the desert sun tests its strength</em></span><br /><em>Arizona waits</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to </em><a class=\"mention\" href=\"https://profiles.wordpress.org/krupajnanda/\"><span class=\"mentions-prefix\">@</span>krupajnanda</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a>, <br /><a class=\"mention\" href=\"https://profiles.wordpress.org/amykamala/\"><span class=\"mentions-prefix\">@</span>amykamala</a><em>,</em> <a class=\"mention\" href=\"https://profiles.wordpress.org/wildworks/\"><span class=\"mentions-prefix\">@</span>wildworks</a> and <a class=\"mention\" href=\"https://profiles.wordpress.org/masteradhoc/\"><span class=\"mentions-prefix\">@</span>masteradhoc</a> <em>for collaboration and revie</em>w</p>\n\n\n\n<div class=\"wp-block-group is-layout-constrained wp-block-group-is-layout-constrained\">\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://us.wordcamp.org/2026/\"><img alt=\"WordCamp US: Powered by WordPress, Driven by Community, August 16-19, 2026\" class=\"wp-image-20859\" height=\"321\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/06/wcus-2026-teaser.png?resize=1024%2C321&#038;ssl=1\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Join us for the launch of WordPress 7.1 at <a href=\"https://us.wordcamp.org/2026/\">WordCamp US 2026</a>, August 16–19.</figcaption></figure>\n</div>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Aug 2026 15:37:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Benjamin Zekavica\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:83:\"WPTavern: #228 – Priscilla Collado Ramirez on Reducing WordPress Beginner Anxiety\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=206976\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://wptavern.com/podcast/228-priscilla-collado-ramirez-on-reducing-wordpress-beginner-anxiety\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:52017:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the themes, the blocks, and in this case, reducing WordPress beginner anxiety in a multitude of ways.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Priscilla Collado Ramirez. Priscilla travelled 14 hours from Costa Rica to attend WordCamp Europe, making her one of the furthest attendees at the event, and for good reason. She&#8217;s an educator, fashion designer and wellness coach, and has a unique perspective on a challenge many in the WordPress community face, how overwhelming WordPress can be for beginners.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Having once quit WordPress 17 years ago, due to information overload, and a lack of community support, Priscilla&#8217;s story comes full circle, as she now dedicates herself to helping entrepreneurs and creatives find their way in the WordPress ecosystem. Her work focuses on demystifying those first confusing moments, offering practical steps, and much needed reassurance for anyone who&#8217;s ever opened a fresh install and wondered, what on earth do I do next?</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation is focused on why newcomers often feel stuck, paralysed by too many choices, the classic it depends advice, and a fear of breaking something or everything. We get into the importance of understanding individual learning styles, whether linear or spiral, as Priscilla labels them, and meeting students where they are, sometimes with literal breathing exercises and wellness techniques to lower stress and unlock real learning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Priscilla explains how confidence in WordPress is built through action, and why celebrating small wins, like successfully installing a single plugin, is essential. She also shares her approach to bringing holistic, calm, and patient mentorship into WordPress education, something that&#8217;s as relevant for agency leads as it is for first time bloggers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;ve ever felt overwhelmed by WordPress&#8217; infinite possibilities, struggled to find your place in its community, or just want practical wisdom on making the path easier for beginners, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Priscilla Collado or Ramirez.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Priscilla Collado Ramirez. Although I know that&#8217;s not the correct way to say it, would you please say your name for me?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:44] <strong>Priscilla Collado Ramirez:</strong> It&#8217;s good, it&#8217;s good. I&#8217;m Priscilla Collado Ramirez, and I&#8217;m from Costa Rica.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:48] <strong>Nathan Wrigley:</strong> Well, I appreciate it. Thank you. You get the award without a doubt coming the furthest, I think, to WordCamp Europe this year. I don&#8217;t know how many miles it is, but you said, I think it was 13 hours.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:59] <strong>Priscilla Collado Ramirez:</strong> Yeah, 14 hours on the plane. Today is travelling. But it&#8217;s all worth it, because this country in Europe, it&#8217;s beautiful. So I can do it all the years, all the months. Yeah, I can do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:13] <strong>Nathan Wrigley:</strong> I have to ask though, why come all the way across, so many hours on a plane and what have you. Do you have a community where you are? Is there a thriving kind of Costa Rican WordPress scene? I don&#8217;t know anything about it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:28] <strong>Priscilla Collado Ramirez:</strong> Okay. Yeah, in Costa Rica is a big community. It&#8217;s the biggest community in whole Latin America, in Costa Rica. I have a friend, she works for GreenGeeks web hosting, so she empowered me to do this. And the WordCamp Europe, because being a speaker is one of my dreams come true.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I already do it in my country, but I want to get more knowledge and know more people. And when she told me about this, I said, yeah, I can do it. Yeah, I want to do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:06] <strong>Nathan Wrigley:</strong> That is remarkable. A 13 hour plane journey. That&#8217;s pretty impressive. And I confess, I didn&#8217;t know that Costa Rica was sort of the place to be if you&#8217;re in South America. But now I do. Thank you. And I know that you&#8217;ve basically just come out of the presentation room, you&#8217;ve just finished the subject that you were talking about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the subject that you were talking about is really interesting to me at least, because this casts me back. I&#8217;ve been in the WordPress space since about, I don&#8217;t know, 2015, something like that. So I&#8217;ve got a few years under my belt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I do remember at the time when I began using WordPress, turning up to events like this and feeling a bit like a fish out of water, not really knowing what to do. Not really knowing what to do with the software, either. Not really knowing what I should install, whether I should install anything, whether I was using the best thing, or the worst thing or what have you. And that kind of was the nature of your subject.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But rather than me telling everybody what you were talking about, do you just want to summarise what it was that you stood up and presented about?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:02] <strong>Priscilla Collado Ramirez:</strong> Yeah, of course. And I feel the same way that you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Well, my talk is about why WordPress feels overwhelming for beginners. I was that beginner that I don&#8217;t want to install. And WordPress, it&#8217;s great, but sometimes gives you too many options, right? So for beginners, sometimes that options feels paralysing because we need to start with one at the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I saw all the topics for this event, and I think, yeah, maybe I can share a little bit of my story with WordPress. And I talk about, I quit WordPress 17 years ago.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:47] <strong>Nathan Wrigley:</strong> You quit it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:48] <strong>Priscilla Collado Ramirez:</strong> Yeah. I&#8217;m a quitter.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:50] <strong>Nathan Wrigley:</strong> My story going back, oh, 12 years or whatever it was, that&#8217;s nothing. You got 17 years. That was when you quit. Okay, carry on. Sorry.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:58] <strong>Priscilla Collado Ramirez:</strong> Yeah, no, 17 years ago, I was at university, and I was studying advertising and web design. I saw the options, too many options, too many things, I don&#8217;t know. And I feel overwhelmed. And I said, this is not for me. I&#8217;m so dumb. I&#8217;m slow. No, no.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And 17 years later, I&#8217;m here as an educator, and I help entrepreneurs and beginners to understand the WordPress environment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:29] <strong>Nathan Wrigley:</strong> What brought you back then? After all that period of time away, what was the catalyst that brought you back? Why did you explore it again?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:36] <strong>Priscilla Collado Ramirez:</strong> Because I have a fashion school, and I saw my students deal with web designers and sometimes they charging so much money. I see it in the beginners, in my students, I saw that we have a problem with understanding that sometimes the things are not too difficult. We can learn about new tools and new WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:06] <strong>Nathan Wrigley:</strong> Okay, so this was all about your students then. So this was an idea of, I guess the world is kind of an expensive place to be, and one expense that you can get rid of is the cost of your website. There&#8217;s tools out there. You can, if you wish to, build it yourself. And then you found WordPress again. How is it the second time? Did you ever go through, I&#8217;m going to quit it for a second time, or was it better the next time you came across it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:29] <strong>Priscilla Collado Ramirez:</strong> Yeah, and my brother is an engineer and I&#8217;m in like a category of non-technical people because I&#8217;m a fashion designer. I&#8217;m an educator, and I&#8217;m a wellness coach. And I think, yeah, maybe I can study a little bit, and if I use my education tools to understand how the brains for the creative people works and try to, out of the box, that sometimes the engineers have, and the creative people. It&#8217;s like a disorder, a disorder brain. I can help to these people to understand this environment in this community. And they can do it like I do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:22] <strong>Nathan Wrigley:</strong> Yeah. So we&#8217;ll get into the bits that you think are problematic with beginning with WordPress in a minute. But just going back to your students and what have you. How&#8217;s it been for them? When you are looking at what they&#8217;re able to do, has it been a road of success, or has there been quite a lot of failure for them? Basically sum up how your students have coped.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:09:43] <strong>Priscilla Collado Ramirez:</strong> Okay. I don&#8217;t know, there&#8217;s two types of students, right? So we have the students that have a linear path learning. Some students learned like A, B, and C. Okay, you understand things easily. But some of them don&#8217;t understand the things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I try to create a platform, or we can call it like a type of education, and helps to understand, first how their brain works, and later understand the type of learning that I can teach.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:24] <strong>Nathan Wrigley:</strong> Okay, let me just make sure I understood that. So you try to figure out what their brain accepts most readily? And then once you figure that bit out, then you begin the WordPress education from there. Okay, that&#8217;s interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you say there&#8217;s kind of two types that you&#8217;ve kind of determined. And what are those two types?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:40] <strong>Priscilla Collado Ramirez:</strong> Lineal.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:41] <strong>Nathan Wrigley:</strong> Oh, so I think probably linear, like straight lines.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:46] <strong>Priscilla Collado Ramirez:</strong> Yeah, we have the straight lines and the spiral.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:49] <strong>Nathan Wrigley:</strong> Okay, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:51] <strong>Priscilla Collado Ramirez:</strong> So my mind is on the spiral. And that&#8217;s why I feel dumb in these technical environments. But I learned that if you learn some topic at the time and without the stress, you can do it and you can follow this community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:10] <strong>Nathan Wrigley:</strong> So you just used an interesting word there. You said that you have felt, maybe you don&#8217;t feel it here, I don&#8217;t know if you do or not. But you said you&#8217;ve felt dumb in the past. You know, you&#8217;ve turned up to the events and you felt like a fish out of water, we might say that. Just. What the heck am I doing here? Where do I fit into this jigsaw puzzle?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And obviously you felt it long and hard enough that, firstly you left, and then come back, given it a second shot. So what are the things that you have felt dumb about? What are the things that have perplexed you in the past? What are the things that have drawn you to making this presentation?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:47] <strong>Priscilla Collado Ramirez:</strong> I felt in that time overwhelmed for the too many options. I feel that in that time in my country, WordPress wasn&#8217;t so popular and was a men&#8217;s environment. There&#8217;s no women. So I feel like, I don&#8217;t know, I&#8217;m not from, I don&#8217;t know what to be here. And now, four years ago, I&#8217;ve been talking with the women community on WordPress and I feel like, I don&#8217;t know, confident and they believe in my knowledge.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think that, yeah, I can do it again. I can approach to the community and I can learn, and I can be like a mentor too, and help beginners to understand that it&#8217;s not the technical environment. It&#8217;s how the community engage with your goals and can be used, and how can help with your goals.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:50] <strong>Nathan Wrigley:</strong> So I&#8217;m just going to dig into something you said a moment ago, which was about the community where you are. I don&#8217;t know if it&#8217;s still the same, but you implied that it was mostly men.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Have you found female WordPressers where you are? Or have you had to get on Zoom calls or something like that in order to find that community? Or has it grown so that it&#8217;s not just men where you are now?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:14] <strong>Priscilla Collado Ramirez:</strong> Yeah. I assist to the first women speakers in 2023. And I saw like, okay, this is a WordPress group for women. And that group was for speakers from WordPress, but women. So I was like, okay, WordPress is not only men&#8217;s, WordPress is not only technical people. And, well, I can approach to that community. 17 years ago wasn&#8217;t like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All men and square men. Because I know there is a lot of spiral men, but in that age, yeah, was like square men and my brother is a little bit like a square. And I was like, no, I&#8217;m funny and I want to talk, and I want to be a speaker and what. Now I feel that I can approach to my goals with WordPress because I changed my mind and my feeling about the community and WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:20] <strong>Nathan Wrigley:</strong> So just moving away from the community side and all of that kind of stuff, just dealing with the, actual software that you download from the internet and you put on a server somewhere, and then you begin to build a website. I presume that that&#8217;s part of this as well, that it&#8217;s difficult to begin because when you install a version of WordPress, you&#8217;re kind of left to your own. You know, there&#8217;s not really much in the way of assistance. You have to find the assistance somewhere. You have to a YouTube channel or some friendly person that will stand over your shoulder and help you out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What are the sort of impediments, the problems that you think we have for people beginning with WordPress that you would like to be solved?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:14:58] <strong>Priscilla Collado Ramirez:</strong> Yeah. First of all that everybody thinks that WordPress is only a website. And I want to share this. WordPress is not only a website, right? It is a community. And you can approach and say, I wanted to learn about how to do a blog and how to do a website. But the community is more than that. I think that people don&#8217;t understand yet that what is WordPress?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:30] <strong>Nathan Wrigley:</strong> Yeah. well I went for, I probably used WordPress for four years, maybe three and a half, four years, something like that, before I knew there was any kind of community. I mean I realised that there was something because the software got made. So I realised somewhere behind the curtain, there must be people doing this. And I&#8217;m getting it for free, so they probably are not getting paid mostly to do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I didn&#8217;t attend because I didn&#8217;t know there was anything to attend. And then I showed up to an event in London, which was probably my closest larger event at that time. I was quite surprised. I was thinking, okay, so there were about 600 people there, I really wasn&#8217;t expecting that. I thought maybe there&#8217;ll be like 12 or 15 or something. Showed up, 600 people. And for me that was kind of the moment WordPress became a little bit more interesting, because I realised that, okay, it isn&#8217;t just pixels on pages, it&#8217;s not just the websites. There&#8217;s actually a whole community of people behind it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And one of the things that I discovered fairly quickly was that those people shared, there was a lot of overlap between them and me. You know, just a lot of things in their lives seemed to sync with a lot of things in my life. We had broad agreement on a lot of things. We all wanted the project to be successful. And so discovering the community, like you said, was a really important thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But nevertheless, I still think I would&#8217;ve carried on using it even if I hadn&#8217;t of discovered that community, because by that point I&#8217;d got over the problem of what plugins to install and how to actually use the software.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah. So let&#8217;s move on to that. In terms of the actual software, so we&#8217;ve got the community, we know that exists. What are some of the problems that you&#8217;ve seen, I guess with your students, or maybe personal experience? Some of the problems with the actual software. What are some of the things that you&#8217;ve encountered?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:21] <strong>Priscilla Collado Ramirez:</strong> Yeah. I encountered that there&#8217;s too many options, and the people do not know how to install. And that&#8217;s a beginner&#8217;s questions. Why should I install plugins, themes? And for technical people it is like, okay, it depends.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:39] <strong>Nathan Wrigley:</strong> Oh always it depends.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:41] <strong>Priscilla Collado Ramirez:</strong> Always, it depends. And, for beginnings, that feels paralysing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:45] <strong>Nathan Wrigley:</strong> Okay. That&#8217;s an interesting phrase, isn&#8217;t it? So when you mean paralysing? So we say it depends, meaning, oh, try everything. See what works. Where you are saying that in your experience, it depends means don&#8217;t do anything, we don&#8217;t know, not sure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:00] <strong>Priscilla Collado Ramirez:</strong> Yeah. And the beginners don&#8217;t know what to do, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:03] <strong>Nathan Wrigley:</strong> Okay, yeah, that&#8217;s not helpful, is it, it depends, really when you say it like that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so how do we overcome that? I don&#8217;t know what we do apart from keep saying, it depends. I guess we&#8217;ve got to try and encourage people to try this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, let me rewind a bit. So my parents, when I put the phone in their hand for the first time, the mobile phone, I had it all set up for them, you know everything was working, and I gave it to them and assumed that they would have the same approach as me. Which was, just play around with it and then you&#8217;ll figure it out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Oh, no. No touching anything was, will I break it? Is this going to destroy it? If I press delete here, does that mean the whole thing&#8217;s going to like be, does this app going to disappear at this point?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, I think that&#8217;s what you&#8217;re saying, is basically there&#8217;s this fear that if I install something and then I don&#8217;t need it, or I don&#8217;t like it, well then what do I do? Is it kind of that? This fear of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:59] <strong>Priscilla Collado Ramirez:</strong> Yeah, because you feel overwhelmed, and you feel paralysing. And you feel like, okay, there&#8217;s a learning path, right? So we have the excitement. So, yeah, I&#8217;m going to do WordPress. Then confusing. What is this? And then it is like, no, I don&#8217;t know, maybe this is not for me because there&#8217;s so many options.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I try with my students to go one step at a time, and understand, first, what is a plugin? Right? Do you need a plugin or not? Do you need a theme or not? Do you need SEO plugin or, I don&#8217;t know?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I am trying to, first of all, work with entrepreneurs because some entrepreneurs sometimes doesn&#8217;t get it. I don&#8217;t know, what is an email? How to send an email. They are so intelligent, and so capable to learn things, but sometimes, like as educators or mentors, we have in our minds that people learn easily. And sometimes it&#8217;s not. So you have to teach like a child. And not because the people was stupid, right? It is like because that people, the learning process is different.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:30] <strong>Nathan Wrigley:</strong> Yeah, I suppose you&#8217;ve got to just get to the point where you&#8217;re comfortable. So for some people who are, I don&#8217;t know, let&#8217;s go for the word technical. Technical people who&#8217;ve got a background in using computers, they do it all day, every day. And they experiment with new things. I suppose if you put them in front of WordPress, they&#8217;re off. They&#8217;re just going to do that kind of thing. But I totally get what you mean.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So for me, technology, I will experiment and I&#8217;ll play, because I know that nothing can basically actually break. If something goes wrong, I can just delete it. So I&#8217;m thinking about apps on my phone, on my computer, and WordPress, and plugins, and themes and all of this. I fully understand that nothing will kill it. Well, hopefully nothing will kill it, and I can just remove what I don&#8217;t understand.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then again, you pick me up and put me into a different industry, I&#8217;ll be that person. I&#8217;ll be the person that needs the baby steps, I think you said that needs the child steps, because I&#8217;m not in familiar territory. So I can&#8217;t think an example off the top of my head, but pick me up, basically put me anywhere there&#8217;s no technology, and I will feel that same anxiety. What do I do? can you check that what I&#8217;ve done is safe? Okay. Can you double check? And will you triple check just to make sure that everything is safe. And I suppose that&#8217;s what you&#8217;re saying, is just little baby steps. get people into it. And once they&#8217;ve gone through the baby steps, hopefully they can act on their own.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:54] <strong>Priscilla Collado Ramirez:</strong> This is a phrase that I been thinking too much in this talk, because it is some word that you said, and you said about confidence. And I wrote that confidence does not come before action. Confidence is built through action.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:14] <strong>Nathan Wrigley:</strong> Yeah, that&#8217;s true, isn&#8217;t it? And so everybody at some point has to go through that barrier. Some people seem to be full of confidence, regardless of what is, but there&#8217;s a lot of people who are not. And if you walk them through the baby steps I suppose, as you said, and tell them, do you need a plugin? What is a plugin? This is a plugin. How do you get a plugin to be put on your website? Can you delete a plugin? And then same thing with themes and custom code and all of those kind of things. And does that work? Do you notice that people go from like, ah, fear, to oh, this is all right.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:47] <strong>Priscilla Collado Ramirez:</strong> They think, this is not so hard that I was the, I will be. I don&#8217;t know, I have all types of students and all types of socioeconomic types. And I have students like 50 to 60 years old. And they think, no, I&#8217;m too old to think learning website, and learning design things. And I&#8217;ve been creative. The constructivist system is a strategy in education, the constructivist, and the principle idea is you learn by doing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:27] <strong>Nathan Wrigley:</strong> Confidence through action, like you said, basically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:29] <strong>Priscilla Collado Ramirez:</strong> Exactly, exactly. And so you can be on the learning path, making little mistakes and getting more confidence to feel safe in the learning environment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:42] <strong>Nathan Wrigley:</strong> Are you a patient person?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:45] <strong>Priscilla Collado Ramirez:</strong> Sometimes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:45] <strong>Nathan Wrigley:</strong> Yeah. Because when I was earlier describing my parents and the phone, there&#8217;s kind of a bit of me, which when I&#8217;ve demonstrated the same thing nine times, and every time the output of those, okay, do it this way, do it this, okay, now do this, now this. And on the 10th go, it&#8217;s still the wrong thing in the exact same way. I just wondered if there was a bit of that? If there is just some impediments which, I don&#8217;t know, some people just never get over. If WordPress is just generally too hard for some people. Or do you always pursue it and succeed? Do you always get people through, and get them to that confident stage?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:23] <strong>Priscilla Collado Ramirez:</strong> Yes. Yeah, yeah. Every day. Yeah. Like every day. And I think that the mentor and the educator has to feel love with that work, and teaching with love, first of all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then, understand that people doesn&#8217;t learn in the same way. I can say older people because I&#8217;m older, and you saw an older people, and you think, this is older than me, but it isn&#8217;t.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:55] <strong>Nathan Wrigley:</strong> Yeah. and some people are kind of, what, we would describe as kinesthetic learners. So they doing is the way. Some people are kind of auditory, and they hear the solution and they learn from hearing. And other people it&#8217;s visual. You know, they see the, watch a video and, oh, I&#8217;ve got that now. And I guess you&#8217;ve got to figure out which ones, how they fit in. If I show you once, you&#8217;re fine. If I show you once, well that&#8217;s not going to work. You&#8217;ve got to actually do it and copy me. And once you&#8217;ve figured out what kind of learners they are. You must have a lot of time for these people by the sounds of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:25] <strong>Priscilla Collado Ramirez:</strong> Yeah, of course.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:27] <strong>Nathan Wrigley:</strong> Yeah, and do you literally have an endless amount of time to educate them or do you have like a, I don&#8217;t know, you&#8217;ve got 10 hours or whatever it is and after 10 hours we&#8217;re going to get new people in? Or do you just stick with them throughout the whole journey?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:38] <strong>Priscilla Collado Ramirez:</strong> Yeah, yeah. And most beginners and most entrepreneurs isn&#8217;t that way, right? And they&#8217;re so excited to understand the process. And when I explain how the brain works, they think, oh, yeah, it&#8217;s not the system, it&#8217;s me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:59] <strong>Nathan Wrigley:</strong> But also I can do something about it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:00] <strong>Priscilla Collado Ramirez:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:01] <strong>Nathan Wrigley:</strong> Yeah, okay. That&#8217;s interesting. Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m going to give you superpowers for a minute. I&#8217;m going to say that you are in charge of WordPress entirely. It&#8217;s up to you what we do to improve this experience. What would you change? that could be the software. It could be education that you suddenly provide, you know, you would whip up many, many courses or whatever. I don&#8217;t know. I&#8217;m just curious to know what you think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So again, superhero powers. You get to decide the future of WordPress. What little changes would you make here and there?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:32] <strong>Priscilla Collado Ramirez:</strong> I&#8217;m going a little bit too far off WordPress, and I&#8217;m going to bring wellness tools first.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:41] <strong>Nathan Wrigley:</strong> Okay. So it gets bigger.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:42] <strong>Priscilla Collado Ramirez:</strong> Yeah, it&#8217;s bigger. I&#8217;m a wellness coach first of all, and first you have to try to understand the stress, and your mind. And then you can learn. I feel like my superpower will be an educator in wellness first, because we have to manage the stress of learning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:04] <strong>Nathan Wrigley:</strong> So you have to approach the computer, but calmly. You have to get there and arrive in an equanimous state. Nice and calm.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:14] <strong>Priscilla Collado Ramirez:</strong> Yeah, and understand that the delete button doesn&#8217;t exist. Because you are going to learn that, yeah, you can delete it, but you are going to breathe, and stay calm, and you won&#8217;t be delete anything because you, on the learning process of your mind understanding that everything is a process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">After that, I have an idea, I don&#8217;t know my superpower, I would like to do the mentor of the mentors first.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:49] <strong>Nathan Wrigley:</strong> Oh, teach the teachers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:51] <strong>Priscilla Collado Ramirez:</strong> Yeah, yeah. Because we have mentors in WordPress, but the mentors sometimes doesn&#8217;t study at the university education, right? Is an engineer trying to teach another engineer, or an engineer teach to entrepreneur or a beginner, so their minds works different.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:14] <strong>Nathan Wrigley:</strong> Yes. I&#8217;ve encountered this in the real world. You know the educator who gets really angry with you and tuts, sort of goes tut tut, because you&#8217;re not doing what the way they would do it. It just turns out that, if you just ask me in a different way, I&#8217;ll probably figure it out.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:29] <strong>Priscilla Collado Ramirez:</strong> Yeah, exactly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:30] <strong>Nathan Wrigley:</strong> Sorry I interrupted, carry on. So educating the educators.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:33] <strong>Priscilla Collado Ramirez:</strong> And in all the fields is the same way, because I&#8217;m a fashion designer too, but I have to learn how to be an educator, and how to try to explain some things to my students and try to get off to my mind box.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I want to make some changes too, and add some of these tools on WordPress. I don&#8217;t know, maybe this is my superpower, like be a spiral mind.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:07] <strong>Nathan Wrigley:</strong> Yeah, yeah. But I think teaching the teachers. So I think we would use the word pedagogy for that. Meaning, how to teach basically. The science, if you like, of imparting knowledge. And maybe there is nothing like that at the moment. And if there isn&#8217;t something like that, it would be interesting to explore how different people with different minds and different approaches. Maybe your first idea of everybody approach the computer in a calm way. Maybe that gets rid of some of that problem. At least we&#8217;re approaching and we&#8217;re not getting we begin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But I think you&#8217;re onto something there, in that I know that I don&#8217;t learn in the same way as my children do. I don&#8217;t learn in the same way as my parents do. And so having that in the background, and educating the educators so that they&#8217;re aware that those kind of things exist.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, you&#8217;ve still got the superpowers. Is there anything else that you would do before I take them away?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:56] <strong>Priscilla Collado Ramirez:</strong> Okay, okay. I think that understand the brain is a supercomputer. It&#8217;s also a big topic because you can programming your mind. I would love to teach that people can programming itself. I don&#8217;t know what other superpower.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:17] <strong>Nathan Wrigley:</strong> Well that&#8217;s okay. You&#8217;ve had it for probably about five minutes now. That&#8217;s more than most people get.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah. So in your experience, I know that you are obviously trying to overcome this problem, and it sounds like you get most people through it, and people manage to come out the other side and are, you know using WordPress successfully. But despite that, do you still think out there in the wider community, not where you are, do you still think that people are being turned off by the problem at the beginning of, I don&#8217;t know what to do. I think that I should be able to figure this out, but I can&#8217;t. I&#8217;m frustrated. It&#8217;s annoying me. Ah, move on, or forget the whole thing altogether.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:53] <strong>Priscilla Collado Ramirez:</strong> Okay. I give you some tools. I wrote it. Limit the choices. Yeah, because one plugin at a time. Yeah, understand one topic at a time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:05] <strong>Nathan Wrigley:</strong> When you say that, are you, meaning, let&#8217;s say for example, that we&#8217;re getting into the, oh, I don&#8217;t know, the realm of SEO, we&#8217;ve managed to get into that subject. We know that there&#8217;s like 500 SEO plugins. Just show them one, just pick one, concentrate on that one and figure out how that works. And then maybe reveal that there&#8217;s others or something like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:25] <strong>Priscilla Collado Ramirez:</strong> Yeah. But sometimes, maybe I have to understand your world first, and maybe you don&#8217;t need SEO tools? Because maybe you wanted to sell, I don&#8217;t know, plants. So do you really need a SEO plugin? Yeah, maybe not. So I have to understand your business first, or your purpose first, and then I can share you one plugin for that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:56] <strong>Nathan Wrigley:</strong> Right, so, but at the end of the day, it&#8217;s still limit it rather than the plugin overwhelm. 78,000 plugins on the repo or whatever it is. One at a time is probably for a beginner more than enough. Learn how to install it. How to uninstall it. Learn the kind of things that you can do with it, whether that&#8217;s SEO or a form plugin or whatever. Okay, it looks like you&#8217;re ready for another one, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:15] <strong>Priscilla Collado Ramirez:</strong> Yeah. I have, normalise confusion.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:19] <strong>Nathan Wrigley:</strong> Okay, so be happy with being confused and muddled up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:23] <strong>Priscilla Collado Ramirez:</strong> Yeah, because it&#8217;s a new topic for you. So you have to understand that it is fine if you feel confusion, because your brain is adapting to that learning process.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:34] <strong>Nathan Wrigley:</strong> Yeah, we&#8217;re not good at that, are we? We&#8217;re really good at being annoyed by confusion. Confusion&#8217;s the enemy in many ways, isn&#8217;t it? But it&#8217;s really not. I mean, who can expect to learn something new and immediately understand everything? No, but we don&#8217;t allow ourselves to do that, do we? We get annoyed with confusion.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s a good one. I like that. Carry on, sorry.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:54] <strong>Priscilla Collado Ramirez:</strong> And celebrate the small wins. I&#8217;m doing right now. I&#8217;m realise that I have to celebrate the small wins, because sometimes we overwhelm and have too many expectations. It is one step at a time, baby steps.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:11] <strong>Nathan Wrigley:</strong> So that one is basically when something goes right. So once you&#8217;ve got over your confusion and something&#8217;s gone right, sit back, examine it. Ah, well done. Pat on the back kind of thing. Yeah, okay. That&#8217;s nice.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:22] <strong>Priscilla Collado Ramirez:</strong> Yeah. And emotional reset tools.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:26] <strong>Nathan Wrigley:</strong> Okay. You&#8217;re going to have to explain that one.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:29] <strong>Priscilla Collado Ramirez:</strong> Okay. I&#8217;m going to explain you here, because I want to explain you pretty well, and sometimes I get I stuck in the language.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, when beginners get frustrated, we must do simple pauses, like breathing. The process of breathing is called pranayama. In pranayama is the art of the breathing. When we born, the first thing that I will do is breathe. And when you are crying, the people say, no, no, breathe, breathe, right? And when you are, I don&#8217;t know, when you swimming, and you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:09] <strong>Nathan Wrigley:</strong> Drowning maybe.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:11] <strong>Priscilla Collado Ramirez:</strong> Drowning yeah, you want to breathe. So the breathing is so important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:16] <strong>Nathan Wrigley:</strong> So this is part of the pausing thing. Just pausing, breathing, okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:20] <strong>Priscilla Collado Ramirez:</strong> Yeah. They also reduce the cognitive overload. And help beginners continuing learning with more clarity, that regulates the brain and the stress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:32] <strong>Nathan Wrigley:</strong> So I don&#8217;t think I do any of those things when I&#8217;m learning. I just sort of plough on and expect myself to do really well. And when I don&#8217;t, I get miserable and annoyed. And I don&#8217;t ever think about, okay, calm down, breathe, congratulate yourself. The thing is I mostly do learning by myself. You know, I&#8217;m in a room and I watch a video or I read something, and so there&#8217;s nobody there to tell me to breathe, calm down, relax, congratulate yourself. So I&#8217;m glad these people have got you in their lives to, make all of this happen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sorry, carry on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:03] <strong>Priscilla Collado Ramirez:</strong> No, no. And one of the phrases that I want to the people understand is the learning doesn&#8217;t happen in stress. It happens when the mind feels safe enough to explore.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:19] <strong>Nathan Wrigley:</strong> Yeah, well I can identify with that. That makes perfect sense, doesn&#8217;t it? When you&#8217;re uptight and worried about things, nothing sticks ever, does it? So back to calm, I suppose.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:30] <strong>Priscilla Collado Ramirez:</strong> Yeah yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:31] <strong>Nathan Wrigley:</strong> Yeah, that&#8217;s all good advice. Yeah I wish I could do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:36] <strong>Priscilla Collado Ramirez:</strong> Yeah. And sometimes, yeah, the people feel overwhelmed with the stress first. I have too many mentors that causing me stress and, I don&#8217;t know, they don&#8217;t give me confidence in anything of I been learning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:55] <strong>Nathan Wrigley:</strong> It sounds to me like what you are proposing. We would probably call it holistic. So it&#8217;s treating the mind, the body. They&#8217;re the first bits. If you haven&#8217;t got those intact and working for you, it doesn&#8217;t matter how many times you read that book, you&#8217;re never going to learn anything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:12] <strong>Priscilla Collado Ramirez:</strong> But sometimes the word for holistic for technical people is like you&#8217;re a hippie.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:17] <strong>Nathan Wrigley:</strong> Well, there is a bit of that, isn&#8217;t there? I think technical people often have an approach to this kind of stuff, which is fairly dismissive, sort of at arm&#8217;s length. Because it&#8217;s not science, if you know what I mean. It doesn&#8217;t sort of come under that umbrella. I wonder how much resistance actually, if I put you in, you know, had a chat with a thousand of the people out there at the moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:38] <strong>Priscilla Collado Ramirez:</strong> Oh, the people go away.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:38] <strong>Nathan Wrigley:</strong> Yeah, okay. Okay. But you know it works. And everybody knows this kind of stuff works. Because if you&#8217;re calm, I suppose the difficulty would be, you&#8217;ve got to allow yourself to accept that you need to be calm, and you need to be approaching it in this kind of way. And that&#8217;s difficult. I would find that quite difficult. You know, if I came to your educational institute, if you like, if you were teaching me WordPress, there would be a bit of me at the beginning, which would be thinking, okay, just tapping the watch, and thinking when does the WordPress begin?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you are probably saying, we need to be calm now, you know? So I guess you&#8217;re going to have to fight that fight.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:13] <strong>Priscilla Collado Ramirez:</strong> Yeah. Yeah. And last year I was a speaker in my country, and I&#8217;m talking about how manage the stress, the people that works like eight hours on the computer. You can use too many tools to release the back, the breathing. And everybody needs release the stress. Sometimes in technical environments, the people don&#8217;t engage with the holistic path because they think that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:46] <strong>Nathan Wrigley:</strong> Yeah. I confess I&#8217;ve had years of doing that kind of stuff. Just expecting my body to be able to keep pace with whatever I&#8217;m doing, and expecting that if I sit in a chair for 12 hours, that everything&#8217;s going to be fine. I&#8217;m just going to stand up and walk away. And of course, it&#8217;s not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you know, it&#8217;s really interesting, I don&#8217;t know that anybody&#8217;s doing this. Maybe you know a load of people that are carrying out this kind of a practice. But it feels like you&#8217;ve kind of, forgive me if I&#8217;ve got the wrong language here, but it feels like you&#8217;ve kind of bolted something close to meditation onto technology. Which is really curious, because I don&#8217;t know that anybody, maybe this is common where you are. I don&#8217;t know, but.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:27] <strong>Priscilla Collado Ramirez:</strong> No, it&#8217;s not. It&#8217;s not because I&#8217;m a sound therapist, and I&#8217;m a sound healer. The sound can heal you. I am trying to people understand that you can&#8217;t live like a computer. You are not a computer. You can program in your brain like a computer, but you are not a robot. And you need to stop.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:51] <strong>Nathan Wrigley:</strong> I think, we&#8217;re too attached to our devices, aren&#8217;t we? I think whenever the mobile phone came along, we finally gave up free time. And email is there 24/7. Social media&#8217;s there 24/7. Technology&#8217;s there 24/7. Yeah, breathe is basically what you&#8217;re saying.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:10] <strong>Priscilla Collado Ramirez:</strong> Yeah. And in my country, no, it is not common. It is not common and it is a little rare. And maybe in another country it is normal to finish your labour at work and meditate one minute.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:26] <strong>Nathan Wrigley:</strong> Oh no. Nobody does that where I live, no.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:30] <strong>Priscilla Collado Ramirez:</strong> I don&#8217;t know if there is any country, doesn&#8217;t do it, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:32] <strong>Nathan Wrigley:</strong> That would be nice. Yeah you&#8217;d probably feel really good after that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:35] <strong>Priscilla Collado Ramirez:</strong> Maybe in China? Maybe Japan?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:38] <strong>Nathan Wrigley:</strong> Maybe where they a different approach to living. Do you want to roll your thing out? The way that you are doing this, do you want to roll that out to other people? Do you want people to kind of approach you and, I don&#8217;t know, study what you are doing, and then go off and do that kind of thing elsewhere? Is that part of why you&#8217;ve come to an event like this? To sort of preach the gospel of this idea, this way of learning?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:01] <strong>Priscilla Collado Ramirez:</strong> Yeah, yeah. I would love to. I would love the people understanding maybe, I don&#8217;t know, create me a plugin about wellness. I don&#8217;t know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:12] <strong>Nathan Wrigley:</strong> Okay, so anybody listening to this, Priscilla wants communication with people who think they might be able to step in. I know of several people who have, let&#8217;s say things like meditation as part of their daily ritual and things. In which case, anybody who&#8217;s listening to this, where&#8217;s the best place to find you online? If people want to get in touch and talk about these wider problems, education, learning, calming down, meditation, those kind of things, where would we find you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:37] <strong>Priscilla Collado Ramirez:</strong> On Gravatar. On WordPress page, and Instagram too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:40:42] <strong>Nathan Wrigley:</strong> I think I&#8217;ve got the details of most of those, but if I don&#8217;t, I will get them from you, and I will put them on the WP Tavern website. So if you search for the episode, dear listener, with Priscilla in it, I don&#8217;t know the number of that episode just yet, but if you search for the episode with Priscilla in it, if you&#8217;ve got intuitions that you&#8217;d like to help out, go and find this episode and you can reach out. And you never know, maybe something will come of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So Priscilla, thank you for chatting to me today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:41:07] <strong>Priscilla Collado Ramirez:</strong> Oh, thank you too. And remember to breathe.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have Priscilla Collado Ramirez.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Priscilla traveled 14 hours from Costa Rica to attend WordCamp Europe, making her one of the furthest attendees at the event, and for good reason. She’s an educator, fashion designer, and wellness coach, and has a unique perspective on a challenge many in the WordPress community face: how overwhelming WordPress can be for beginners.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Having once quit WordPress 17 years ago due to information overload and lack of community support, Priscilla’s story comes full circle as she now dedicates herself to helping entrepreneurs and creatives find their way in the WordPress ecosystem. Her work focuses on demystifying those first confusing moments, offering practical steps and much-needed reassurance for anyone who’s ever opened a fresh install and wondered, “What on earth do I do next?”</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation is focused on why newcomers often feel stuck, paralysed by too many choices, the classic “it depends” advice, and a fear of breaking something (or everything). We get into the importance of understanding individual learning styles, whether linear or spiral (as Priscilla labels them), and meeting students where they are, sometimes with literal breathing exercises and wellness techniques to lower stress and unlock real learning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Priscilla explains why confidence in WordPress is built through action, and why celebrating small wins, like successfully installing a single plugin, is essential. She also shares her approach to bringing holistic, calm, and patient mentorship into WordPress education, something that’s as relevant for agency leads as it is for first-time bloggers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’ve ever felt overwhelmed by WordPress’s infinite possibilities, struggled to find your place in its community, or just want practical wisdom on making the path easier for beginners, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://europe.wordcamp.org/2026/session/why-wordpress-feels-overwhelming-for-beginners/\">Why WordPress feels overwhelming for beginners</a> &#8211; Priscilla&#8217;s presentation at WordCamp Europe 2026</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/nivrattibienestat/\">Priscilla on WordPress.org</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Aug 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"Greg Ziółkowski: The Abilities API in WordPress 7.1: Lifecycle, Schemas, and Discovery\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:26:\"https://gziolo.pl/?p=15020\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:96:\"https://gziolo.pl/2026/08/05/the-abilities-api-in-wordpress-7-1-lifecycle-schemas-and-discovery/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:384:\"The Abilities API gives WordPress plugins a common language for describing and executing units of functionality. An ability has a stable name, human-readable metadata, input and output contracts, a permission check, and an execution callback. Other PHP code can discover it without knowing which plugin registered it, while REST, WP-CLI, JavaScript, MCP, and AI integrations [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Aug 2026 12:11:55 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Greg Ziółkowski\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:140:\"HeroPress: The First 10 Years, The Next 10 Years – પહેલાંનાં ૧૦ વર્ષ, આગળનાં ૧૦ વર્ષ\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://heropress.com/?post_type=heropress-essays&p=8775\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:146:\"https://heropress.com/essays/the-first-10-years-the-next-10-years/#utm_source=rss&utm_medium=rss&utm_campaign=the-first-10-years-the-next-10-years\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:28241:\"<img alt=\"Pull Quote: Communities begin with one conversation and a willingness to show up.\" class=\"attachment-large size-large wp-post-image\" height=\"512\" src=\"https://heropress.com/wp-content/uploads/3026/08/jina-banner.webp\" width=\"1024\" /><p class=\"wp-block-paragraph\"><a href=\"https://heropress.com/feed/#gujarati\">આ નિબંધ ગુજરાતીમાં પણ ઉપલબ્ધ છે</a></p>\n\n\n\n<figure class=\"wp-block-audio\"><audio controls=\"controls\" src=\"https://heropress.com/wp-content/uploads/3026/08/jina-10-years.mp3\"></audio><figcaption class=\"wp-element-caption\">Hear Jina read her story aloud in her own voice.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Sometimes I wonder how life connects the dots.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A LinkedIn follow. A few conversations with someone I didn’t know much about at the time. And today, somehow, those small moments have led me to write my story on HeroPress. If someone had told the girl who graduated from college in 2015 that one day she would be sharing her WordPress journey here, I would never have believed them.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-diving-in\">Diving In</h2>\n\n\n\n<p class=\"wp-block-paragraph\">My first ten years in WordPress weren’t just about learning how to write code. They were about learning how to grow through uncertainty, motherhood, self-doubt, and, most importantly, community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I joined my first company in 2015, fresh out of college. I knew Core PHP, but WordPress was completely new to me. I had only heard its name before my interview. My first month was as an unpaid trainee, and by the second month I was already building websites for clients. Soon after, I was given the opportunity to work on the plugin, Oasis Workflow. Those five years became my real classroom. I learned plugin development, worked with React and Gutenberg during their early adoption, and discovered that WordPress was much more than a CMS—it was an ecosystem that never stopped evolving.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-building-a-product\">Building A Product</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Around the same time, an opportunity came my way to build a <a href=\"https://wordpress.org/plugins/cf7-google-sheets-connector/\">Google Sheets integration for Contact Form 7</a>. That small feature eventually became <a href=\"https://gsheetconnector.com/\">GSheetConnector</a>. As more users adopted it, their feedback shaped the product. Ten thousand users became twenty thousand, new requirements became new features, and in 2018 we launched the Pro version. What started as a single integration gradually grew into a family of connector plugins. Looking back, it taught me one of the biggest lessons in product development: listen to your users, because they will help build the roadmap with you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In 2019, I attended my first WordCamp in Vadodara. Until then, WordPress had mostly meant code and client work. WordCamp introduced me to the people behind the software. I made new connections, learned from contributors, and realized there was an entire community that believed in sharing knowledge instead of keeping it to themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Then came the most challenging chapter of my life.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-everything-everywhere-upside-down\">Everything Everywhere, Upside Down</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Between 2020 and 2025, I was leading our company’s Vadodara branch while the world suddenly changed because of COVID-19. Like many others, I shifted to working from home. During the same period, I became a mother. My days became a balance of meetings, deployments, household responsibilities, and raising my daughter. Working from home gave me flexibility, and I will always be grateful to <a href=\"https://profiles.wordpress.org/abdullah17/\">Mr. Abdullah</a> for trusting me with that flexibility, but it also came with responsibilities that are difficult to explain unless you’ve lived them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For five years, my focus was simple: my family and my job. I wasn’t learning new technologies. I wasn’t attending events. I wasn’t contributing to WordPress. As AI, modern development workflows, and new technologies continued to evolve, I often felt as though the industry had moved ahead while I was standing still. It was an uncomfortable feeling, and for a long time I questioned whether I had fallen behind.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-going-to-wordcamp\">Going To WordCamp</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Everything changed again in late 2025 when GSheetConnector sponsored WordCamp Surat. Meeting people from the community reignited something I had been missing. Soon after, I learned that WordCamp Asia 2026 would be held in Mumbai. I wanted to attend, but I couldn’t stop thinking about the practical challenges. Could I travel with my daughter? Could we afford it? Would everything work out?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I applied for the Zeel Thakkar Scholarship with hope more than confidence, and to my surprise, I received it. My husband took leave from work so he could travel with me and help take care of our daughter. His support made that journey possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Contribution Day at WordCamp Asia wasn’t the success I had imagined. My development environment failed at the last moment. My WordPress.org account was temporarily blocked, and to make matters worse, my phone shut down, leaving me without access to my authenticator codes. I sat there feeling completely blank, wondering if I even belonged in that room.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Instead of giving up, I walked over to the Community Team table.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That decision quietly changed my direction.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-building-community\">Building Community</h2>\n\n\n\n<p class=\"wp-block-paragraph\">There, Devin introduced me to the process of becoming a Meetup Organizer. I returned home, completed the required training over the following month, attended another meetup to learn from experienced organizers, and received constant encouragement from people like Pooja Derashri and Aditya Kane, who patiently answered every question I had.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In June 2026, we successfully restarted the Vadodara WordPress Meetup. Only a handful of people attended, but to me it represented something much bigger. It reminded me that communities don’t begin with hundreds of people. They begin with one conversation and a willingness to show up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking back, I realize that my first ten years were about building my career. I hope my next ten years will be about building people.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"h-forging-ahead\">Forging Ahead</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I want to strengthen our local WordPress community, encourage students through Campus Connect programs, and help more women—especially mothers who believe their careers have stopped—rediscover opportunities in WordPress. I want to contribute more to WordPress itself, continue learning emerging technologies like AI, build a plugin of my own, and one day attend WordCamp Asia outside India with my daughter and husband by my side. My Daughter already asks me if we’ll be there next year at Malaysia, and every time she does, I’m reminded that dreams don’t have deadlines—they just need commitment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If my journey has taught me one thing, it’s this: WordPress is not just about software. It is about people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Every meaningful opportunity in my journey began because someone answered a question, shared knowledge, offered encouragement, or simply believed in me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">To every woman in tech—and especially every mother trying to balance family, work, and her own dreams—please remember this: you are doing better than you think. Take one step at a time. Reach out to people. Ask questions without fear. Help even one other person if you can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because that’s what WordPress has taught me over the past ten years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Connect. Learn. Grow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then help someone else do the same.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<h1 class=\"wp-block-heading\" id=\"gujarati\"><strong>પહેલાંનાં ૧૦ વર્ષ, આગળનાં ૧૦ વર્ષ</strong></h1>\n\n\n\n<p class=\"wp-block-paragraph\">ક્યારેક મને લાગે છે કે જીવન કેવી રીતે એક પછી એક ઘટનાઓને એકબીજા સાથે જોડતું જાય છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">લિંક્ડઇન પર કરેલું એક <strong>ફોલો</strong>. એવી વ્યક્તિ સાથે થયેલી થોડી <strong>વાતચીત</strong> જેને હું તે સમયે ખાસ ઓળખતી પણ નહોતી. અને આજે, એ જ નાનાં-નાનાં પ્રસંગોએ મને <strong>હીરોપ્રેસ</strong> પર મારી પોતાની વાર્તા લખવા સુધી પહોંચાડી છે. જો ૨૦૧૫માં કોલેજમાંથી ગ્રેજ્યુએટ થયેલી મને કોઈએ કહ્યું હોત કે એક દિવસ હું અહીં મારી <strong>વર્ડપ્રેસ</strong> સફર શેર કરીશ, તો કદાચ હું ક્યારેય વિશ્વાસ ન કરતી.</p>\n\n\n\n<p class=\"wp-block-paragraph\">વર્ડપ્રેસ સાથેના મારા પહેલાંના દસ વર્ષ માત્ર <strong>કોડ</strong> લખવાનું શીખવામાં જ ગયા નથી. આ વર્ષોએ મને અનિશ્ચિતતા વચ્ચે આગળ વધવાનું, માતૃત્વને સ્વીકારવાનું, પોતાની જાત પર શંકા હોવા છતાં હિંમત રાખવાનું અને સૌથી મહત્વનું – <strong>સમુદાય</strong>નું સાચું મહત્વ સમજાવ્યું.</p>\n\n\n\n<p class=\"wp-block-paragraph\">૨૦૧૫માં, કોલેજ પૂર્ણ કર્યા પછી મેં મારી પ્રથમ કંપનીમાં જોડાઈ. મને <strong>કોર પી.એચ.પી.</strong> આવડતું હતું, પરંતુ વર્ડપ્રેસ મારા માટે સંપૂર્ણપણે નવું હતું. ઇન્ટરવ્યૂ પહેલાં મેં માત્ર તેનું નામ જ સાંભળ્યું હતું. પ્રથમ મહિને હું કોઈપણ પગાર વિના <strong>ટ્રેઇની</strong> તરીકે કામ કરતી હતી, અને બીજા મહિને જ હું ગ્રાહકો માટે વેબસાઇટ્સ બનાવતી થઈ ગઈ. થોડા જ સમયમાં મને કંપનીના <strong>ઓએસિસ વર્કફ્લો પ્લગિન</strong> પર કામ કરવાની તક મળી. એ પાંચ વર્ષ મારા માટે ખરેખર એક યુનિવર્સિટી સમાન રહ્યા. મેં <strong>પ્લગિન ડેવલપમેન્ટ</strong> શીખ્યું, <strong>રિએક્ટ</strong> અને <strong>ગૂટનબર્ગ</strong> સાથે તેમની શરૂઆતના સમયમાં કામ કર્યું અને સમજાયું કે વર્ડપ્રેસ માત્ર એક <strong>સી.એમ.એસ.</strong> નથી, પરંતુ સતત વિકસતું અને બદલાતું એક વિશ્વ છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">એ જ સમય દરમિયાન મને <strong>કોન્ટેક્ટ ફોર્મ ૭</strong> માટે <strong>ગુગલ શીટ્સ ઇન્ટિગ્રેશન</strong> બનાવવાની તક મળી. એ નાનું <strong>ફીચર</strong> ધીમે-ધીમે <strong>જીશીટકનેક્ટર</strong> તરીકે વિકસતું ગયું. વધુને વધુ લોકો તેનો ઉપયોગ કરવા લાગ્યા અને તેમના <strong>ફીડબેક</strong>એ જ આ <strong>પ્રોડક્ટ</strong>નું ભવિષ્ય ઘડ્યું. દસ હજાર <strong>યૂઝર્સ</strong> વીસ હજાર થયા, નવી જરૂરિયાતો નવા <strong>ફીચર્સ</strong> બની અને ૨૦૧૮માં અમે તેનું <strong>પ્રો વર્ઝન</strong> રજૂ કર્યું. એક જ ઇન્ટિગ્રેશનથી શરૂ થયેલી સફર અનેક <strong>કનેક્ટર પ્લગિન્સ</strong> સુધી પહોંચી. પાછળ વળી જોઉં ત્યારે સમજાય છે કે પ્રોડક્ટ બનાવવાનો સૌથી મોટો પાઠ મને અહીં મળ્યો—તમારા યૂઝર્સને સાંભળો, કારણ કે તેઓ જ તમારી સાથે મળીને તમારા પ્રોડક્ટનો આગળનો રસ્તો નક્કી કરે છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">૨૦૧૯માં મેં વડોદરામાં મારું પ્રથમ <strong>વર્ડકેમ્પ</strong> અટેન્ડ કર્યું. ત્યાં સુધી વર્ડપ્રેસ મારા માટે માત્ર કોડ અને ગ્રાહકોનું કામ હતું. વર્ડકેમ્પએ મને આ સોફ્ટવેર પાછળ રહેલા લોકો સાથે પરિચય કરાવ્યો. નવા સંબંધો બન્યા, <strong>કોન્ટ્રિબ્યુટર્સ</strong> પાસેથી શીખવાની તક મળી અને મને સમજાયું કે અહીં એક એવી સમુદાય છે જે જ્ઞાનને પોતાની પાસે રાખવામાં નહીં, પરંતુ બધાં સાથે વહેંચવામાં વિશ્વાસ રાખે છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">પછી મારા જીવનનો સૌથી પડકારજનક સમય શરૂ થયો.</p>\n\n\n\n<p class=\"wp-block-paragraph\">૨૦૨૦થી ૨૦૨૫ દરમિયાન હું અમારી કંપનીની વડોદરા બ્રાન્ચ સંભાળી રહી હતી અને એ જ સમયે <strong>કોવિડ-૧૯</strong>ને કારણે આખી દુનિયા બદલાઈ ગઈ. બીજા ઘણા લોકોની જેમ હું પણ <strong>વર્ક ફ્રોમ હોમ</strong> કરવા લાગી. એ જ સમયગાળામાં હું માતા પણ બની. મારા દિવસો <strong>મીટિંગ્સ</strong>, <strong>ડિપ્લોયમેન્ટ્સ</strong>, ઘરકામ અને મારી દીકરીના ઉછેર વચ્ચે સંતુલન જાળવવામાં પસાર થવા લાગ્યા. વર્ક ફ્રોમ હોમે મને લવચીકતા આપી, અને તેના માટે હું શ્રી અબ્દુલ્લાહની હંમેશાં આભારી રહીશ કે તેમણે મારા પર વિશ્વાસ રાખ્યો. પરંતુ આ લવચીકતા સાથે એવી જવાબદારીઓ પણ આવી જેને માત્ર એ વ્યક્તિ જ સમજી શકે જે આ જીવન જીવી હોય.</p>\n\n\n\n<p class=\"wp-block-paragraph\">પાંચ વર્ષ સુધી મારું સમગ્ર ધ્યાન માત્ર બે બાબતો પર હતું—મારો પરિવાર અને મારી નોકરી. હું નવી ટેક્નોલોજી શીખી શકતી નહોતી, કોઈ <strong>ઇવેન્ટ્સ</strong>માં જઈ શકતી નહોતી અને વર્ડપ્રેસમાં <strong>કોન્ટ્રિબ્યુશન</strong> પણ કરી શકતી નહોતી. <strong>આર્ટિફિશિયલ ઇન્ટેલિજન્સ (એ.આઈ.)</strong>, આધુનિક <strong>ડેવલપમેન્ટ વર્કફ્લો</strong> અને નવી ટેક્નોલોજી સતત આગળ વધી રહી હતી, અને ઘણીવાર મને એવું લાગતું કે આખી દુનિયા આગળ વધી ગઈ છે જ્યારે હું એ જ જગ્યાએ ઊભી છું. લાંબા સમય સુધી મને પોતાને જ પ્રશ્ન થતો રહ્યો કે શું હું ખરેખર પાછળ રહી ગઈ છું?</p>\n\n\n\n<p class=\"wp-block-paragraph\">૨૦૨૫ના અંતમાં બધું ફરી બદલાયું, જ્યારે જીશીટકનેક્ટરએ <strong>વર્ડકેમ્પ સુરત</strong>ને <strong>સ્પોન્સર</strong> કર્યું. ત્યાં સમુદાયના લોકો સાથે મળવાથી મારી અંદર કંઈક ફરી જીવંત થયું—એ ઉત્સાહ, જે કદાચ હું વર્ષોથી ગુમાવી બેઠી હતી. થોડા સમય પછી ખબર પડી કે <strong>વર્ડકેમ્પ એશિયા ૨૦૨૬</strong> મુંબઈમાં યોજાવાનું છે. હું જવા માગતી હતી, પરંતુ મનમાં અનેક પ્રશ્નો હતા. શું હું મારી દીકરી સાથે મુસાફરી કરી શકીશ? શું અમે આ ખર્ચ ઉઠાવી શકીશું? શું બધું સારું રહેશે?</p>\n\n\n\n<p class=\"wp-block-paragraph\">મેં <strong>ઝીલ ઠક્કર સ્કોલરશિપ</strong> માટે અરજી કરી. મારા પાસે આત્મવિશ્વાસ કરતાં આશા વધુ હતી. અને મારા આશ્ચર્ય વચ્ચે મને સ્કોલરશિપ મળી ગઈ. મારા પતિએ પણ રજા લીધી જેથી તેઓ મારી સાથે આવી શકે અને અમારી દીકરીની સંભાળ રાખી શકે. તેમના સાથ અને સહકાર વગર આ સફર શક્ય બની ન હોત.</p>\n\n\n\n<p class=\"wp-block-paragraph\">વર્ડકેમ્પ એશિયાનો <strong>કોન્ટ્રિબ્યુશન ડે</strong> મેં જે રીતે કલ્પ્યો હતો એવો રહ્યો નહીં. છેલ્લી ઘડીએ મારું <strong>ડેવલપમેન્ટ એન્વાયરમેન્ટ</strong> કામ કરવાનું બંધ થઈ ગયું. મારું <strong>વર્ડપ્રેસ.ઓર્ગ એકાઉન્ટ</strong> થોડા સમય માટે બ્લોક થઈ ગયું અને ઉપરથી મારો ફોન પણ બંધ થઈ ગયો, જેના કારણે <strong>ઓથેન્ટિકેટર કોડ્સ</strong> પણ ઉપલબ્ધ રહ્યા નહીં. હું ત્યાં એકદમ શાંત, ગભરાયેલી અને ખાલી મનથી બેઠી હતી. મનમાં માત્ર એક જ પ્રશ્ન હતો—શું ખરેખર હું અહીં હોવા લાયક છું?</p>\n\n\n\n<p class=\"wp-block-paragraph\">પણ હાર માનવાને બદલે હું <strong>કોમ્યુનિટી ટીમ</strong>ના ટેબલ તરફ ચાલી ગઈ.</p>\n\n\n\n<p class=\"wp-block-paragraph\">એ નિર્ણયે શાંતિથી મારી સફરની દિશા બદલી નાખી.</p>\n\n\n\n<p class=\"wp-block-paragraph\">ત્યાં <strong>ડેવિન</strong>એ મને <strong>મીટઅપ ઓર્ગેનાઇઝર</strong> બનવાની સમગ્ર પ્રક્રિયા સમજાવી. ઘરે પરત આવ્યા પછી મેં જરૂરી <strong>ટ્રેનિંગ</strong> પૂર્ણ કરી, અનુભવી ઓર્ગેનાઇઝર્સ પાસેથી શીખવા માટે બીજા મીટઅપમાં હાજરી આપી અને <strong>પૂજા દરશ્રી</strong> તથા <strong>આદિત્ય કાણે</strong> જેવા લોકો પાસેથી સતત પ્રોત્સાહન મળતું રહ્યું. તેમણે મારા દરેક પ્રશ્નનો ધીરજપૂર્વક જવાબ આપ્યો.</p>\n\n\n\n<p class=\"wp-block-paragraph\">જૂન ૨૦૨૬માં અમે ફરીથી <strong>વડોદરા વર્ડપ્રેસ મીટઅપ</strong> શરૂ કરવામાં સફળ રહ્યા. માત્ર થોડા લોકો હાજર હતા, પરંતુ મારા માટે તેનો અર્થ ઘણો મોટો હતો. એણે મને શીખવ્યું કે સમુદાયની શરૂઆત ક્યારેય સેંકડો લોકોથી થતી નથી. તેની શરૂઆત એક વાતચીતથી અને હાજર રહેવાની તૈયારીથી થાય છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">આજે જ્યારે હું પાછળ વળી જોઉં છું, ત્યારે સમજાય છે કે મારા પહેલાંના દસ વર્ષ મારી કારકિર્દી બનાવવામાં ગયા.</p>\n\n\n\n<p class=\"wp-block-paragraph\">હવે મારી આશા છે કે મારા આગામી દસ વર્ષ લોકો બનાવવામાં પસાર થાય.</p>\n\n\n\n<p class=\"wp-block-paragraph\">હું અમારી સ્થાનિક વર્ડપ્રેસ સમુદાયને વધુ મજબૂત બનાવવા માંગું છું. <strong>કેમ્પસ કનેક્ટ</strong> જેવા કાર્યક્રમો દ્વારા વિદ્યાર્થીઓને વર્ડપ્રેસ સાથે જોડવા માંગું છું. ખાસ કરીને એવી મહિલાઓ અને માતાઓને મદદ કરવા માંગું છું જેમને લાગે છે કે તેમની કારકિર્દી અટકી ગઈ છે. હું વર્ડપ્રેસમાં વધુ કોન્ટ્રિબ્યુશન કરવા માંગું છું, એ.આઈ. જેવી નવી ટેક્નોલોજી શીખવાનું ચાલુ રાખવા માંગું છું, એક દિવસ પોતાનું પ્લગિન બનાવવું છે અને મારી દીકરી અને પતિ સાથે ભારતની બહાર યોજાતા વર્ડકેમ્પ એશિયામાં હાજરી આપવી છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">મારી દીકરી આજે પણ મને પૂછે છે, “મમ્મી, આપણે આવતા વર્ષે મલેશિયા જઈશું ને?” અને દર વખતે મને યાદ આવે છે કે સપનાઓની કોઈ સમયમર્યાદા નથી હોતી—તેને ફક્ત સમર્પણની જરૂર હોય છે.</p>\n\n\n\n<p class=\"wp-block-paragraph\">મારી સફરે મને જો એક વાત શીખવી હોય, તો એ આ છે—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>વર્ડપ્રેસ માત્ર સોફ્ટવેર નથી. વર્ડપ્રેસ એટલે લોકો.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">મારી સફરમાં આવેલી દરેક મહત્વપૂર્ણ તક કોઈક વ્યક્તિએ મારા પ્રશ્નનો જવાબ આપ્યો, પોતાનું જ્ઞાન વહેંચ્યું, મને પ્રોત્સાહિત કર્યું અથવા માત્ર મારા પર વિશ્વાસ મૂક્યો—ત્યાંથી જ શરૂ થઈ હતી.</p>\n\n\n\n<p class=\"wp-block-paragraph\">ટેક ક્ષેત્રમાં કામ કરતી દરેક મહિલાને, અને ખાસ કરીને દરેક એવી માતાને જે પરિવાર, કામ અને પોતાના સપનાઓ વચ્ચે સંતુલન જાળવવાનો પ્રયાસ કરી રહી છે, હું માત્ર એટલું જ કહેવા માગું છું—</p>\n\n\n\n<p class=\"wp-block-paragraph\">તમે જેટલું વિચારો છો, તેના કરતાં ઘણું સારું કરી રહ્યા છો.</p>\n\n\n\n<p class=\"wp-block-paragraph\">ધીમે-ધીમે એક સમયે એક પગલું ભરો.</p>\n\n\n\n<p class=\"wp-block-paragraph\">લોકો સાથે જોડાઓ.</p>\n\n\n\n<p class=\"wp-block-paragraph\">પ્રશ્ન પૂછવામાં ક્યારેય ડરશો નહીં.</p>\n\n\n\n<p class=\"wp-block-paragraph\">અને જો શક્ય હોય, તો ઓછામાં ઓછા એક વ્યક્તિને આગળ વધવામાં જરૂર મદદ કરજો.</p>\n\n\n\n<p class=\"wp-block-paragraph\">કારણ કે છેલ્લા દસ વર્ષમાં વર્ડપ્રેસે મને આ જ શીખવ્યું છે—</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>જોડાઓ. શીખો. આગળ વધો.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">અને પછી, કોઈ બીજા માટે પણ એ જ માર્ગ સરળ બનાવો.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n<p>The post <a href=\"https://heropress.com/essays/the-first-10-years-the-next-10-years/\">The First 10 Years, The Next 10 Years &#8211; પહેલાંનાં ૧૦ વર્ષ, આગળનાં ૧૦ વર્ષ</a> appeared first on <a href=\"https://heropress.com\">HeroPress</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Aug 2026 02:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jina Parekh\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"Matt: Michel the GOAT\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153867\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://ma.tt/2026/08/michel-goat/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1912:\"<p class=\"wp-block-paragraph\">I don&#8217;t usually blog all my comments other places, but while drafting a completely different blog post I came across this great post, <a href=\"https://iterativewonders.com/2025/11/25/michel-valdrighi-the-coder-whose-code-never-went-silent/\">Michel Valdrighi: The Coder Whose Code Never Went Silent</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I had to leave a comment, because Michel&#8217;s story is not well-known.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Michel Valdrighi is the GOAT. His elegant code and impeccable aesthetic paved the path for WordPress to follow, and he did it with a prescient belief in Open Source. It seems obvious now, but in 2001, software that wasn&#8217;t just free but gave you Freedom was a radical idea that made people look at you funny. He showed me that code could be poetry, that beauty in simplicity is harder to achieve than complexity.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://mikelittle.com/\">Mike Little</a> and I met hanging out on the <a href=\"https://sourceforge.net/projects/cafelog/\">b2/cafelog Sourceforge</a> and <a href=\"https://en.wikipedia.org/wiki/Freenode\">Freenode IRC</a> channel, both drawn in by what Michel had created. It all started on a little island called <a href=\"https://en.wikipedia.org/wiki/Corsica\">Corsica</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Bonus:</strong> After publishing, <a href=\"https://jetpack.com/support/related-posts/\">Jetpack&#8217;s Related Post feature</a> led me to this <a href=\"https://ma.tt/2002/10/best-blogging-software/\">Best Blogging Software? post where Michel commented</a>, months before <a href=\"https://ma.tt/2003/01/the-blogging-software-dilemma/\">the famous Blogging Software Dilemma</a>. See, even back then people were arguing about static vs dynamic sites.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 05 Aug 2026 01:58:57 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"Open Channels FM: Open Minds Balancing AI Innovation with Authentic Human Connection\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558337\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:91:\"https://openchannels.fm/open-minds-balancing-ai-innovation-with-authentic-human-connection/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:240:\"This episode discusses the impact of artificial intelligence on human skills and connections, emphasizing concerns about overdependence on technology, authenticity in communication, and the importance of retaining essential human abilities.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 04 Aug 2026 08:29:20 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Matt: Gabriel Dawe\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153850\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://ma.tt/2026/08/gabriel-dawe/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:393:\"<p class=\"wp-block-paragraph\">New artist I&#8217;m obsessed with: <a href=\"https://www.gabrieldawe.com/\">Gabriel Dawe</a>. I love the colors and craft, very <a href=\"https://me.sh/\">Mesh</a>. If his site were on <a href=\"https://wordpress.org/\">WordPress</a>, we&#8217;d definitely commission some pieces. <cite>Hat tip: <a href=\"https://www.goodworknichols.com/\">Jason Nichols</a>.</cite></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 04 Aug 2026 04:23:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:67:\"Open Channels FM: The Evolving Landscape of Digital Identity and AI\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2557253\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://openchannels.fm/the-evolving-landscape-of-digital-identity-and-ai/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:165:\"Digital identity is rapidly evolving due to AI and new authentication methods, necessitating secure access and robust management for both users and automated agents.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 03 Aug 2026 14:27:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:58:\"Open Channels FM: Follow Open Channels News on X @OCFMNews\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2558304\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://openchannels.fm/follow-open-channels-news-on-x-ocfmnews/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:168:\"Founder Bob Dunn rebranded his @BobWP account to @OCFMNews for Open Channels News, expecting existing followers to appreciate the new focus on news and podcast content.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 03 Aug 2026 08:30:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Gutenberg Times: Gutenberg Changelog #133 – Gutenberg 23.6 Release and WordPress 7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://gutenbergtimes.com/?post_type=podcast&p=46468\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:100:\"https://gutenbergtimes.com/podcast/gutenberg-changelog-133-gutenberg-23-6-release-and-wordpress-7-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:57748:\"<p class=\"wp-block-paragraph\">In episode 133 of the Gutenberg Changelog Podcast, Birgit Pauli-Haack hosts Faith Ruth Imokol, a Ugandan web developer and longtime Gutenberg advocate, to discuss the Gutenberg 23.6 release and the upcoming WordPress 7.1 update. The episode opens with insights into the WordPress community in Uganda, highlighting their active WordCamp scene and educational initiatives such as the Campus Connect program, which introduces WordPress to students across the country.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Faith Imokol shares her experience on a recent WordCamp Kampala panel about AI in web development, noting divided perspectives: while some Ugandans are excited about AI&#8217;s possibilities, others are concerned about job security and adaptation. She describes her personal transition into using AI as a collaborative development tool, driven by the need for faster production due to heightened competition.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Discussion moves to WordPress 7.1, covering new features such as customizable viewports via theme.json, expanded notes and commenting capabilities, enhanced SVG icon registration, and improvements to blocks like playlists and tabs. Both speakers are enthusiastic about the collaborative features and the evolving editorial workflow, particularly the granular notes system for streamlined feedback.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The episode emphasizes community feedback&#8217;s role in shaping new releases and encourages listeners to help test upcoming WordPress versions to ensure quality and translatability. The episode closes with practical tips and excitement for ongoing educational outreach and future Gutenberg advancements.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-133-gutenberg-23-6-release-and-wordpress-7-1/#shownotes\">Show Notes</a> / <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-133-gutenberg-23-6-release-and-wordpress-7-1/#transcript\">Transcript</a></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Editor: <a href=\"https://www.linkedin.com/in/sandy-reed/\">Sandy Reed</a></li>\n\n\n\n<li>Logo: <a href=\"https://markuraine.com/\">Mark Uraine</a></li>\n\n\n\n<li>Production: <a href=\"https://icodeforapurpose.com\">Birgit Pauli-Haack</a></li>\n</ul>\n\n\n\n<p class=\"has-larger-font-size wp-block-paragraph\" id=\"shownotes\"><strong>Show Notes</strong></p>\n\n\n\n<h2 class=\"wp-block-heading\">Special Guest: Faith Ruth Imokol</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://profiles.wordpress.org/faithimokol\">WordPress profile</a></li>\n\n\n\n<li><a href=\"https://www.linkedin.com/in/imokol-faith-ruth/\">LinkedIN </a></li>\n\n\n\n<li><a href=\"https://wordpress.tv/2020/03/05/imokol-faith-ruth-why-how-to-create-gutenberg-blocks/\">Imokol Faith Ruth: Why &amp; How to Create Gutenberg Blocks</a> (2020)</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress Events in Uganda </h2>\n\n\n\n<p class=\"wp-block-paragraph\">Upcoming Events </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://events.wordpress.org/luweero/2026/wordpress-showcase/\">WordPress in Education Showcase 2026</a> August 7, 2026</li>\n\n\n\n<li><a href=\"https://lira.wordcamp.org/2026\">WordCamp Lira 2026</a> 29+ 30 August 2026</li>\n\n\n\n<li><a href=\"https://jinja.wordcamp.org/2026/\">WordCamp is in Jinja</a>  19th &#8211; 20th September 2026</li>\n\n\n\n<li><a href=\"https://events.wordpress.org/campusconnect/2026/central-eastern-ug/\">WordPress Campus Connect Central and Eastern Uganda Schools 2026</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Past 2026 Events</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://events.wordpress.org/uganda/2026/competition/\">Uganda Website Projects Competition | 2026</a></li>\n\n\n\n<li><a href=\"https://masaka.wordcamp.org/2026/\">WordCamp Masaka </a></li>\n\n\n\n<li><a href=\"https://events.wordpress.org/campusconnect/2026/masaka-uganda/\">Campus Connect in Masaka </a></li>\n\n\n\n<li><a href=\"https://events.wordpress.org/campusconnect/2026/Kakumiro/\">Campus Connect Kakumiro</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress 7.1 </h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/news/2026/07/wordpress-7-1-beta-4/\">WordPress 7.1 Beta 4</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/test/2026/07/15/help-test-wordpress-7-1/\">Help Test WordPress 7.1</a></li>\n\n\n\n<li><a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/\">WordPress 7.1 Source of Truth</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">More Developer Notes for WordPress 7.1 </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/07/22/client-side-media-processing-in-wordpress-7-1/\">Client-Side Media Processing</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/23/text-shadow-support-in-global-styles/\">Text shadow support in global styles</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/23/media-library-infinite-scrolling-is-now-enabled-by-default-with-a-per-user-opt-out/\">Media library infinite scroll enabled by default</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/23/editable-blocks-inside-the-custom-html-block/\">Editable blocks inside Custom HTML block</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/23/editor-components-updates-in-wordpress-7-1/\">Editor Components updates</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/24/registering-and-rendering-svg-icons-in-wordpress-7-1/\">Registering and rendering SVG icons</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-minimum-width/\">Min width block support</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-background-gradient-background-gradient/\">Background gradient block support</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://make.wordpress.org/core/?p=124627&amp;preview=1&amp;_ppp=33ada9214e\">What’s new of Gutenberg 23.6</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://gutenbergtimes.com/the-post-editor-is-going-full-iframe-what-block-developers-need-to-know-before-wordpress-7-1/\">The post editor is going full iframe: what block developers need to know before WordPress 7.1</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Video w/ Ryan Welcher: <strong><a href=\"https://www.youtube.com/watch?v=4PrD1jzfD6E\">iframed post editor canvas</a></strong></p>\n\n\n\n<p class=\"has-large-font-size wp-block-paragraph\">Stay in Touch</p>\n\n\n\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-flow wp-block-group-is-layout-flow\">\n<ul class=\"wp-block-list\">\n<li>Did you like this episode? <a href=\"https://lovethepodcast.com/gutenbergchangelog\"><strong>Please write us a review </strong></a></li>\n\n\n\n<li>Ping us on X (formerly known as Twitter) or send DMs with questions. <a href=\"https://twitter.com/gutenbergtimes\">@gutenbergtimes </a>and <a href=\"https://twitter.com/bph\">@bph</a>.</li>\n\n\n\n<li><em>If you have questions or suggestions, or news you want us to include, send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a>. </em></li>\n\n\n\n<li><em>Please write us a review on iTunes! <a href=\"https://gutenbergtimes.com/itunes/\">(Click here to learn how)</a></em></li>\n</ul>\n</div></div>\n\n\n\n<p class=\"has-large-font-size wp-block-paragraph\" id=\"transcript\"><strong>Transcript</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Welcome to our 133rd episode of the Gutenberg Changelog Podcast. In today&#8217;s episode, we will talk about Gutenberg 23.6 release and some WordPress 7.1. And that should be enough for today. I&#8217;m your host, Birgit Pauli Haag, curator at the Gutenberg Times and full-time core contributor to the WordPress Open Source Project sponsored by Automattic. And today I&#8217;m very excited that Faith Ruth Imokol joins me. She&#8217;s a web developer from Uganda, WordCamp organizer there and speaker, and a Gutenberg advocate since 2018, as long as the Gutenberg Times. And I&#8217;m glad she agreed to come on the show and talk through with this release and tell us more about the WordPress community in Uganda. Welcome to the show, Faith. How are you today?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Thank you very much, Birgit, for having me. I am okay. I&#8217;m very fine. Thank you, listeners, for having me as well. I&#8217;m excited.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Me too. Me too. It&#8217;s such wonderful to have you on the show. So, WordCamp community in Uganda is really busy this year, and it probably was last year as well because there&#8217;s a lot of experience there in doing WordCamps. So you, you were in WordCamp Kampala this year.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> And you were on a panel session titled AI and the Future of Web Development: The Good, the Bad, and the Ugly. So what were your takeaways? How are the people in Uganda kind of looking at AI and the future of the web?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Oh, well, the opinions on the future of AI in Uganda and how people view it are quite divided. Many are very hopeful, but some are also a little worried about what is going to become of them, especially when it comes to their jobs with AI. There&#8217;s a lot of talk on AI taking over. There&#8217;s a lot of talk on, okay, what do we need to do? Do we still need to continue with the way that we&#8217;ve been working or should we transition into full AI mode working with AIs? So there&#8217;s a lot of speculation around AI. And during the panel session, very many people had very many questions around that. They wanted reassurances on, especially when it comes to their jobs. Do we still have our jobs as developers? Can we still maintain the work that we are doing right now? Can we still continue using the tools that we are working with right now, or should we leave them and just take on AI and start working with AI. So it was a panel that was there to encourage people, to also highlight and offer corrections on some of the misinformation that was going, that has been spreading and going around in the community, especially in the WordPress community. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: So how, you don&#8217;t have to go into details, but how are you approaching AI for your work?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Personally, I could say that I&#8217;ve been forced in some way to use AI &#8217;cause I&#8217;m using it more as a pair working along with it in my development. And I&#8217;ve been forced to use it. Initially, I was a little hesitant. I like to do my own discoveries. I like to go through my own work and do my own troubleshooting. But with the AI coming in, it forced some of the teams that I was working in to have to increase the rate at which they produce and release applications. Why? Because the competition has now stiffened. If you&#8217;re not using AI to work faster, someone else is going to produce what you&#8217;re doing and they&#8217;re going to release it, and then you&#8217;re going to be left behind. So I kind of, at some extent, have had to take a back seat on doing my own personal investigations and leaving those to my own personal time. But when it comes to work, it&#8217;s something that I&#8217;ve fully incorporated into my day-to-day working. Yeah, still, I still apply my own knowledge as well. I don&#8217;t leave everything to AI to do it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: That&#8217;s certainly quite prudent, yeah, to see how AI can really go wrong and you don&#8217;t know which tangent they go on. Yeah. And I have found, well, I&#8217;m using AI maybe a year now for a lot of different things and I have found that there&#8217;s no taste. Yeah. It has no feelings, of course. Yeah. And it has no empathy for anything. Yeah. So, human judgment is even more needed for anything that is released that was done by AI. And I think it becomes more and more clear the longer we practice with it. First, it&#8217;s a fantastic tool. Yeah, it kind of gets you to certain things faster, but it also is very verbose in code, in reviews, in analysis, and you really need to kind of slow it down and figure out what&#8217;s really important. And that it can&#8217;t do. It doesn&#8217;t know what&#8217;s important, what&#8217;s not important. Everything is the same.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: I kind of think it&#8217;s like a very smart child who thinks they know everything, but they&#8217;ve not lived through the experience of what an adult knows.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> So they still need guidance. That&#8217;s a good analogy. Yeah. It&#8217;s like a young person who just graduated high school and knows everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah, I was that when I graduated from high school. I knew everything. But back to the Uganda community, the next WordCamp is in Jinja. Is that how you pronounce it? From the 19th to the 20th of September. It&#8217;s in the Civil Service College in Jinja. Just, just in case you dear listeners are in the region and you wanna go to a WordCamp in Uganda. But there&#8217;s also running from now to December several WordPress Campus Connect events with 25 schools, each one with at least 100 participants, 25 schools, colleges, or universities. And the program will bring practical, as it aims to, practical WordPress learning sessions to selected schools across Central and Eastern Uganda. And students will be introduced to the basics of WordPress, how websites are built, how to create and publish content and how they can use WordPress for school projects, personal portfolios, blogs, business ideas, and future technology careers. So these are the Campus Connect from the WordPress Education Program that started, I think, in the end of &#8217;24 and has now run through &#8217;25 and half of &#8217;26. So, and Uganda is really taking to it and getting a lot of students involved with WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah, we&#8217;re working hard to see that the future, the next generation that comes into the workforce is not too ill-equipped like the way we were. So these programs that we&#8217;re starting as the WordPress community are out to help the next, the coming, the young generations that are coming in, for them to know, to know the different skills that they can take on and to know that there are different tools that they can also learn that can help them. So it&#8217;s really a very amazing initiative that was started by Mr. Dumba and Moses.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. Yeah. And they are still completely involved and totally immersed in that field. Yeah. Stephen Dumba also organized a website project competition for elementary schools, high schools, and colleges. And they had, I think, 20 teams in total there. And then each team had to create a website for a community project that is local and was very important to the community and how to communicate those problems and solutions. And that was also in June. Then there was WordCamp Osaka, Campus Connect in Osaka, and then Campus Connect in Kakumiro, if I pronounce all that right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yes. Yeah, you&#8217;re trying.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: I&#8217;m trying. Yeah, I&#8217;m not succeeding. Okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Your pronunciations are very good.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Okay. Yeah. Yeah. So I&#8217;m really excited about what&#8217;s happening on the African continent in the various communities. Uganda is one. I think another very active one is Kenya. And there was one in Rwanda. I don&#8217;t know how active they are now. But yeah, I&#8217;m really excited about that. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Announcements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">So we have a few announcements. 7.1 is coming Today is July 30th. So in about 3 weeks, we will have a final release of 7.1. August 19th is the release date. And it will be released on the last day of WordCamp US. The Source of Truth, that&#8217;s the book about things, yeah, that is published on the Gutenberg Times. This time it&#8217;s about 39 minutes to read and 7,000 words. It&#8217;s really an ebook or something like that. The table of contents, it&#8217;s very detailed. So you can jump into the sections that you want. Okay. That you need. And the developer notes are coming out for those who need more technical details. And there was one from the client-side media processing, the text shadow support for global styles. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The media library infinite scroll is coming back and is enabled by default, but there is a filter to disable it for those who need it disabled. And then there are now editable blocks inside custom HTML blocks. That&#8217;s a very interesting construction. So if you&#8217;re interested in that, we share, of course, the developer links in the show notes. There are some editor component updates that are interesting for those who are using those for development in admin as well as in block editor. And then a lot of people have been waiting for that part, registering and rendering SVG icons and icon collections. The developer note is out and it will come to 7.1. And then there&#8217;s also a mid-width block support and background gradient block support. So there are some things for the global styles that are only available through the theme.json. There is no UI yet for it because it just needs to simmer a bit and kind of brew a bit before developers are thinking about the UI. Is there anything that excites you from 7.1 from, from these developer notes yet?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah, well, I really, really, really enjoy the new features that are coming in, especially the one thing that I&#8217;ve really been excited about is the collaboration tools. So I&#8217;m really looking forward to working more with those and seeing how they will help people collaborate on different WordPress projects.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yes. Yeah, yeah, yeah. Unfortunately, the real-time collaboration has been punted again. Or it was clear that it would not come to 7.1 because it has these underlying server technical approaches that depending on where the site is hosted, it needs to have a different approach. Or in enterprise, yeah, it&#8217;s a different approach and all that. And they haven&#8217;t narrowed down what the default value could be. But what I really like are the e-syncer. So it&#8217;s very rare that I&#8217;m sitting there and somebody else is sitting on their computer and we&#8217;re on the post or on the site at the same time. Mostly it&#8217;s because, yeah, I work remotely in Europe time zone with a lot of people in the United States that&#8217;s 6 hours behind. It&#8217;s more asynchronous. And I think the notes section is really getting some great love there that came in 6.9 and 7.0 and now has additional features. Yeah, I really like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah. I see it growing. I see it growing into something much bigger. So I&#8217;m looking forward to whatever is coming ahead.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah, yeah, I could actually see that. But the current publishing flow at the official developer blog is that the writers do a draft in Google Docs, and then 2 reviewers come in and help edit that or streamline it or shorten it or whatever, comment on it. And then the writer has to make all the changes after those feedbacks and then take the whole Google Doc and put it into a blog. So with the notes feature, we can cut out the Google section part because we can now comment on the, on writing on the blocks. Yeah, we can mention people and we can resolve issues from the notes. So it&#8217;s coming really close to streamlining that, our process. All right. </p>\n\n\n\n<h3 class=\"wp-block-heading\">What’s Released -WordPress 7.1</h3>\n\n\n\n<p class=\"wp-block-paragraph\">What&#8217;s released? WordPress 7.1 Beta 4 came out. That&#8217;s the last release before the release candidate next week on August 5th. August 5th is also the deadline for the rest of the dev notes, the developer notes for that, and the Field Guide will come around that as well. And that&#8217;s also the time where string freeze happens. Release candidate is still 14 days away. The translators need to get into it. So string freeze means there are no new strings that come in that need to be translated. Because the WordPress ecosystem has a huge army of translators. And by the time the release comes out, it will be translated into about 70 languages, almost 100% from the new release. And that&#8217;s huge. But we need to give those translators a time on the polyglots teams to actually get it all in. And this is not a small release, although it wasn&#8217;t a long pipeline there. Yeah. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And if you want to test it, this is now the time to go to the Make/Test team and follow the Help Test WordPress 7.1. It&#8217;s also linked from the release post from the news section because it gives you an opportunity to not only dive into the new features, but it also gives you instructions and a video and you learn quite a bit about it. And if you find things that are not right, you surface that. And that is not only surfaced for yourself, but it&#8217;s also surfaced for millions of other people who are going to get this new version. And if you are fast enough and the problems are small enough, they might get the fixes in before the final release. So if you wanna help and contribute quite impactful, help test WordPress 7.1. It&#8217;s my call for action for this show. Did you get a chance to dive into some of the features yet?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yes, I did. I did try testing them as well locally. And yeah, it&#8217;s really impressive. The work that is being put into this is very, very impressive.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Gutenberg 23.6</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: All right. So this brings us to the Gutenberg plugin release 23.6. And 23.6 is also the last feature release for 7.1. So everything that made it into the 23.6, almost all of it will come to 7.1. Everything that&#8217;s enhancements in the next release will not make it because we are past the beta site. But all the bug fixes that you find in your testing and you report them as issues or on the support forums have a chance to get in. Yeah. So let&#8217;s start with that. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Features</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The first item that I want to point out is that you can now set the viewport for tablet and mobile values in theme.json. What does that mean? So the Gutenberg plugin editor had hardcoded viewports for what&#8217;s considered desktop, what&#8217;s considered tablet, and what&#8217;s considered mobile. And everybody had to work around those if you had a different idea about those viewports.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: But now you can just set the setting in your theme.json for your theme and then everything will fall into place.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: I think this gives us much more flexibility because initially with the default viewpoints that are set by WordPress, all sites end up having the same, could I say breakpoints?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> I think personally I prefer to, I refer to them as breakpoints. for different screens that is in mobile responsiveness. And this is going to allow us to be able to customize this to our own liking so that our themes can be uniform with, uh, can have settings that have been preset by us than having the default ones that WordPress has added. And I think as I was going through the changelog, I came through the discussion because the viewports allow you to set the tablet and the mobile view. And there was a discussion of what could happen if someone set the tab view to have a smaller, should I say, breakpoint than the mobile screen. What could happen by that? And it was quite interesting that at that point we reverted back to the defaults.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yeah. So it&#8217;s a good thing to have in the background, as I don&#8217;t think everyone will abide by the rules, but As you&#8217;re working with this and anyone who gets to work with this, I think you have to keep that in mind that you, you&#8217;re setting different breakpoints for different devices and tablets are larger than mobile devices.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. Yeah. That&#8217;s the assumption that tablets are larger than mobile devices. So if someone puts a mobile breakpoint in that&#8217;s bigger than the tablet, that can probably just be a mistake or something like that. Yeah. So having a fallback to not ruin the whole site just because of a wrong value in the theme.json is probably a good measure, yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: I&#8217;m thinking we now have these new Samsung phones that have come out, the flip phones. Does it become a tablet? I&#8217;m still trying to understand.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah, it&#8217;s a good question. So I saw a discussion, an issue that you can— that on Gutenberg to think through the consequences if you have more than 3 breakpoints. Yeah. Can we have multiple sizes? I mean, at one point it really becomes a usability issue. How would an editor or a user, keep in mind that, yes, I saw plugins that have 6 breakpoints and it&#8217;s really hard to control those because you never know where you have all the changes made. Yeah, and come back to it when you, when you start out, it&#8217;s probably easier to kind of think through it. But once you have a site and you need to make some changes, it&#8217;s very hard to figure out where all those changes have to be made. So it doesn&#8217;t become better with more breakpoints. I think that was a point why the Gutenberg developers started out with really honing in on the intrinsic designs, that there&#8217;s actually a seamless adaption to the screen sizes. And that&#8217;s where the Samsung folding phone probably will come in.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: That you&#8217;re not fixed on a breakpoint to just say, okay, yeah, it takes the space it has. Yeah. And rather do content queries rather than media queries. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> I hope we see how, what else will be added to this, cuz I think more is going to come up and shall have more settings being added to this.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: For sure. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: So, uh, notes, this is, features that I&#8217;m really excited about. It shows you how powerful Gutenberg has gotten. Being able to add notes. So the upcoming features, one of the features that we have will be auto-completing mentions. This is you&#8217;ll be able to tag an individual, a user, onto the post, and when you tag them, the prompt will be able to— will allow you to select from— it will pop up a list of the available users and you&#8217;ll be able to select the ones that you want to tag. And when they are tagged on the front end, you&#8217;ll be able to see that they are highlighted, that the tag name is— their display name is highlighted. So this is a feature that I&#8217;m really, really impressed by and hope to see how far it grows more because I&#8217;m seeing all the different possibilities that it can be used in, things like notifications. And I think this is one of the features that is being incorporated for the collaboration right. Later, even as we&#8217;re collaborating, because you can tag someone within the notes, but now you&#8217;re also doing inline, you know, you&#8217;re able to tag people within, within the context of the content that you&#8217;re creating. Yeah. So this is something that I&#8217;m really impressed by and looking forward to see how far that can be taken.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. And now what a lot of people were waiting for, that you can actually highlight partial text and have those notes in the sidebar about a certain portion of a text and not just a whole paragraph block. And now you can also have multiple notes per block as well. So if you have here, the paragraph is, I don&#8217;t know, 10 lines long and you have something you want to note about the first line or the first 6 words or so, and then in the middle is something, and you could have notes for each one of them that then show up in the section. So it makes it much easier to streamline the conversation and to be really granular in what the notes are about or the comments are about. Yeah. And it now has a resolved divider. And so when you check a note that is resolved, it pushes it further down and has a little divider in the sidebar. So yeah, it really comes well together, this note section. Yeah. It really starts growing up.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yeah, I&#8217;m seeing lots and lots of ways that this is going to, because I&#8217;m thinking with the resolver, adding the resolved divider, I&#8217;m seeing this going into something like project management and we&#8217;re able to add even more other statuses possibly besides just the resolved divider. Very impressive.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: I can see some plugin opportunities there to kind of collect all those and have a separate kind of setup for a whole editorial workflow where the main editor just kind of looks through what are the posts and what are the comments. And you can see, okay, or you come in as an editor and see, oh, I need to go through all the comments where I&#8217;m tagged. Yeah. So these kinds of things, I think that would be an interesting feature set to add to it. Not sure that core is actually gonna aim for it. So that might be plugin territory because, territory, because it&#8217;s a very finite use case for that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: The next item is by default, the admin bar is now shown for post and site editor as well. Once you&#8217;re logged in, you see a black bar on your website on top of it with some links where you can jump in different places, and that is coming to 7.1 as well. And now that admin bar has been streamlined and kind of combines the site editor navigation as well with the admin bar. And it&#8217;s really, it&#8217;s a nice feeling. It kind of feels now a little bit more consistent, and you can access the things that you could access before. Yeah, you have your site icon. You also have the big W, and that was in there before, but the header of the site editor is now smaller or the block editor. And it&#8217;s all coming together quite nicely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yes. Coming in version 7.1, we are having, I could say there&#8217;s a kind of more a mix of both dynamic and static content blocks, block content, where we are going to be able to have what WordPress offers. I don&#8217;t know if this is the right way to present this, but currently WordPress offers you a way of providing or creating content that is you&#8217;re either working with blocks or you&#8217;re working with your default static HTML. And this new feature of adding inner content is going to allow us to be able to add dynamic content within static content. So you&#8217;ll be able to work with your HTML and still add editable content within your static content. that is your normal HTML, but within it you have an editable, let me say, paragraph block within there. So the other content remains static, but within it you have your inner content. And we&#8217;ve been provided a new feature called inner content that we can use to set this up.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Mm-hmm.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: That is, if you&#8217;re working with if you&#8217;re creating your own code, you&#8217;ll be able to add this inner content feature and we&#8217;ll be able to allow you to create static content that has HTML blocks within it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah. No, very well described. Yeah, I can see how that is really helpful, especially for patterns that you have editable sections and you say static, I say hardcoded. Yeah, don&#8217;t touch things as an editor. You&#8217;re right. This comes to 7.1 as well. And there are developer notes out. So it will be in the show notes so you can see the technical implementations for that in 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah, it&#8217;s, it&#8217;s, it&#8217;s, it&#8217;s quite a powerful tool, I think, because it&#8217;s— I see it becoming also— it&#8217;s some— one of those features that I feel can be added onto in different ways because you&#8217;re now not just building something that is strict, but you can modify it to appeal to different scenarios and different use cases. As current cases, either you have one block that is doing one particular thing, but now here you&#8217;re able to work with blocks and also normal HTML. So it gives, as a developer, I feel it gives me some power. I&#8217;m not just leaving everything to the blocks to be doing everything, but it gives me some power to be able to add different content styles. Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Nice.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yeah. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: The next one is part of the Icons API. Now 23.6 Gutenberg plugin now has PHP methods To render inline SVG icons from the registry. So that can also be used in PHP-only blocks or in other templates and all that. So that also comes in 7.1, is a new API for registering icons in WordPress, SVG icons and icons collections that came in with 23.6.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> I can take the next one.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Mm-hmm.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Enhancements</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Coming in 7.1. So we had some issues with the backgrounds in some of the blocks, that is the accordion, the post content block, the quotes block, the verse block. And in this, there were issues with the way the images were being handled, that is in the CSS, in the blocks, in the block CSS, which ended up blocking the gradient. It ended up breaking the gradient. So kind of could say that there was a conflict. In how the background images and the gradients were being handled. So it was causing a bug with our gradients. So this has been fixed in how the background images and the gradients are handled. And so you&#8217;ll not be able to see conflicts when you apply a gradient onto any of your blocks, especially the blocks that we have stated, that is the block quotes accordion, the pull quotes, the verses and post content blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. And actually, this fix also gives you a totally new feature. Now you can overlay the gradient onto the background image, and that gives a whole new way of designing things. And if you look at some of the PRs that are coming through and with a screen share there, it&#8217;s actually quite nice that the image kind of feels a little bit more lively when there&#8217;s a gradient on top of them. So it&#8217;s really good. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, the latest post block received layout and block spacing support. The latest post block was historically just a re-rendering as a block from the widget section of WordPress prior to that, and hasn&#8217;t gotten a whole lot of love after that because the query block is kind of also a latest block kind of thing. But it now has layout and block spacing support so you can fit it in other places quite nicely. Speaking of the query block, it now has an option to exclude the current post from the query block, from the list of blocks, so to speak. So this gives a better feel for your single post template where you can say, okay, so this is the post with the post content, but then underneath you can add a list of blocks from either the same category or for the same taxonomy and exclude the current block. Up until now, it would always also render the current block if it had the same taxonomy. So I think that&#8217;s a feature that a lot of people actually were waiting for. It sounds so minuscule. Yeah, but it&#8217;s actually pretty powerful.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: So we have a new feature that has been added to the cover block. And this will allow users to restrict the kind of videos that they want to be added to their cover blocks. Initially, currently what we have is that WordPress has a variety of different video providers that you can embed into your cover block, but this will allow you to restrict. So if you only want to display only YouTube videos, you can add a restriction that we only need YouTube videos being uploaded in our cover block. While you can switch this up to any that you want, as opposed to just allowing it to have any video embedded provider adding the videos. So this is one of those features. I think it gives us more control over what you want. Could I say, when it comes to different service providers, they provide a whole different interface and layout for how their videos play out, and this will allow something like uniformity. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Because I think it can be a little strange when you have your website on— some videos are playing like YouTube content and then it switches into another format and it&#8217;s maybe Vimeo and it all looks so different. I see this creating a better display, a better feel, but it also gives you more control on what kind of content is acceptable.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Absolutely. So from the history, this comes after 7.0 allowed to actually use a video URL as a background for a cover. And after that was installed, there was quite some feedback from the community, especially the agency community and the enterprise level where they say, okay, I don&#8217;t want people just have video embeds from outside of, especially those that are in restricted industries, they&#8217;re regulated industries, they cannot just have willy-nilly URLs playing on their website. So they needed a way to restrict the video providers or even restrict that feature altogether. So this is a reaction of all the community feedback that came in to provide that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Speaking of video, the new client-side processing now also has a way to convert the GIF, an uploaded animated GIF. We know them from the &#8217;90s, right? But some of the Screen recording features also do animated GIFs. And when they have one problem. It&#8217;s nice for smaller things, yeah, for 1 second or something like that. But if you have a longer GIF, you cannot control it. You cannot stop it. You cannot do anything. So some people want to convert that to a video. And now that feature is coming to 7.1, but it&#8217;s also made opt-in. So people have to say, okay, I wanna do this. And then it shows up in the block transform dropdown from a block toolbar. And then you can automatically have the GIFs converted to a video. It really depends on the video and the frame size and a lot of other things to get this right. But it&#8217;s a really nice feature.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yeah, it&#8217;s a very nice feature in that I think now we have still, one has the ability to choose what they want, if they want to maintain the image GIF or to have it as a video. Whereby if it was a video, it could be lightweight and loads much faster than when it&#8217;s a normal GIF. GIFs tend to be quite heavy.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> On websites. Yeah. Just a funny scenario. I went on a website that had— was literally littered with GIFs everywhere. And I&#8217;m just imagining having to work with that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: How resource intensive that can be and how the performance of the website. So I think this resolves a problem that was there previously that they had tried to resolve previously. That is by allowing the conversion of the GIF into a video. So now one can choose, they can either maintain using the GIF or they can choose to go with the video.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack:</em> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> We had 2 blocks that were initially still, should I say, in production. That is the playlist block and the tab block. And these are coming out in version 7.1. The playlist block will allow you to add a playlist. If you&#8217;ve worked with any podcasting and different— if you&#8217;re doing any music playlists on your website, this block will allow you to be able to add a list of music that you want and you&#8217;re able to play it as well in one after the other. So it&#8217;s a very powerful block coming out in version 7.1. And I&#8217;m also talking about the tab— the tabs block. This will allow you to be able to organize content into tabs on your website. So it will allow you to group, literally to group different content onto your website. It&#8217;s also a very, very powerful block that I think will make a whole sense on how different content can be added onto our site. So maybe you can add on to that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah, there were right from the beginning when Gutenberg came out, there were quite a few block collections that had tabs blocks in there. So finally it comes into core. I have a question for a developer. I don&#8217;t know how you feel about that, but doesn&#8217;t it seem that the details block, the accordion block, and the tabs block, they all kind of have the same metaphor kind of thing? Yeah, kind of. Yeah, you check something and something opens, and then you have a collection of check something and the tabs are there, or accordions kind of I mean, they behave a little bit differently, but aren&#8217;t they just a variation of the same idea?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: I think it&#8217;s kind of a similar idea, especially when you see how accordions work. But they— I think it comes down to what kind of display is someone looking forward to. They may all be doing the same kind of similar thing, but someone wants their content to work differently. The tabs block, I think, gives us kind of more— I find it to be superior, should I say superior, to the accordion block in the sense that it allows you to actually group content that you&#8217;re displaying. </p>\n\n\n\n<p class=\"wp-block-paragraph\">So an accordion can be used for things— I could say the most common example that I&#8217;ve seen where they&#8217;re mostly applied is something like FAQs, right, where you group questions and answers. But now looking at a tab, imagine you have something like a WooCommerce site and you have all this different content that is in line with that product. You have the details, then you have the, uh, should I say specifications, then you have the pricing. So all these things can be grouped into different tabs and it can allow someone to navigate through them while providing more concrete details within them. You can do the same with accordions. But I find that this provides a better way of navigating, you know, of navigating through content. Accordions, if the content is quite a lot, they may become, I think, kind of very bulky and they create a lot. You have a lot within one thing while tabs allow you to break down that thing. And I think also, I don&#8217;t know right now, I don&#8217;t know how far this this feature is, but I think tabs can also allow you to also add different other blocks, should allow you to add different blocks within it. So you can do a lot more within, within it.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: So, and I feel it&#8217;s a little bit of a— the metaphor that tabs do is kind of more like in an office setting where you have files, folders, and then files in them that are kind of— you pull them out of the register and then you have the writers on top that are your tabs and then you can— that metaphor is kind of in a website now. And I think people can navigate that better than figuring out how an accordion works.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. I think you&#8217;re right there. Yeah. Well, that was actually kind of a tricky question because that question should go to the WC3 body that does the standards for HTML because that&#8217;s what these 3 blocks do, details, accordion, and tabs. They put the HTML that&#8217;s available into a block setting and then offer that as a tool to design pages and lay out the pages. So the question is actually for the WC3 standards body. Why did you come up with these different standards there and HTML tags for that? </p>\n\n\n\n<p class=\"wp-block-paragraph\">So I think, yeah, we have a few, 2 more updates on the visual revisions page. There is now a label for autosaves. Because the revisions historically only saved what you did, what was there when you hit the save button. And now it also adds the autosaves as separate line items to the revisions timeline. It might get a little crowded now, but you can collapse them quite a bit. And so when you leave a post that was autosaved and then come back to it again, you get a notification on top of the screen that says there is a newer version in autosave. And when you clicked on the link there, you were going back to the old revisions screen, and that has been solved too. So now this screen also goes to the new block-based visual revision screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> I think this is one of the things— revisions is one of the things that I&#8217;m actually impressed by and excited about. I don&#8217;t know how many times I just could come back to my site trying to look through my content and going through the revisions, I&#8217;ll just give up and be like, you know, no need to go back. But I think this helps us to be able to track and actually know where in time we ended, what changed, and also being able to go through what the different revisions are. </p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: And it&#8217;s quite also funny that the person who reported this was a first-time contributor.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: The person who caught this. Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: So with the new settings that we have for the viewpoints, this is a buildup on what we had, we had talked about previously. That is being able to remember what we have, we now have a new feature that allows us to add our own custom viewpoints. in our theme that is in the theme.json.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: With the new states being for either the viewport states or the pseudo states, which is kind of hover and action on that and active, what didn&#8217;t work was that when you changed the color, you didn&#8217;t get a notification that your color choices didn&#8217;t adhere to the contrast for accessible websites. So, and normally when you change the color for the background and for the text, you get a little warning that this is not contrast-rich. You better check your color settings. This feature wasn&#8217;t working for the viewports for the mobile or tablet or for the pseudo-states. So when you change the styling for those states, you didn&#8217;t get the warning. So, and that has been rectified with 23.6 Gutenberg. And it is actually a nice, I would say bug fix, but it&#8217;s an enhancement because it was something that wasn&#8217;t there before. And I think the next one, we already talked about the inner blocks and the custom HTML block. I think we&#8217;re gonna skip through that.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: </p>\n\n\n\n<p class=\"wp-block-paragraph\">This is just, I think, adding up to what we had previously.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Right.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Because now you can add this as when you&#8217;re developing, writing your own blocks, you can add the inner blocks feature in your blocks as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yeah. Yeah. And feedback was for the block visibility. Now you actually have a setting in the theme.json to opt out so your editors wouldn&#8217;t be able to change the block visibility on any of your blocks. There&#8217;s a new theme.json property there. I think some people wanted to kind of look at that and have that available.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> The next issue we have, enabling text alignment to be set by viewpoint state. So this will allow you in your, when you&#8217;re setting up your text and you&#8217;re aligning it, you can have different alignments based on different viewpoints. You can choose to, let me say, left align on the desktop and then right align on your mobile or on your tablet. So this new feature will allow you to be able to set up different alignments for different viewpoints.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Yes, I really like that because sometimes you have a text that&#8217;s in— oh, I&#8217;m— that might be nice centered on a mobile, but it&#8217;s on this, on the big screen, you just can&#8217;t read it. Yeah. So you want it left aligned or something like that. The next one is an enhancement to the grid block. Sometimes we use the same terminology for different things. I just need to make sure that I&#8217;m looking at the same thing here, that it&#8217;s actually— it&#8217;s about the grid block. So there&#8217;s now an option to stretch the columns with an autofit for better layout flexibility. So it&#8217;s adapting to the screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you wanted to, or you can say I have a fixed column width or fixed relationship to the other columns, but now there&#8217;s also that option to stretch the column with autofit.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> So with the new icons feature, we now can group, should I say, we can group the different icons into different collections. WordPress is offering us a way of doing this and they&#8217;ve given us new tools, developers especially, to be able to create different groups for icons. So you can group your icons, maybe these are WordPress icons, these are Font Awesome icons, these are whatsoever different, uh, places where you&#8217;re picking your icons from. So you can group your icons. This is a very nice feature, I think, to be able to allow you to streamline so you can pick from one collection over the other. But this is one of the features that is coming in together with the updates that are being done to the icons.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Exactly. Yeah. In the same vein now, developers are really happy about that, that they can now use digits and underscores in icon slugs. That was part of— it&#8217;s part of the registry API. And in 23.6, those things were added to the API for coming into 7.1.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: So I think when I go through the rest of the changelog, I think we are through with that, what we talked about. But 23.6 again had about 400 PRs in there. And I&#8217;m really happy that the show is not more than an hour or so because we could kind of go on and on about a lot of things in there. </p>\n\n\n\n<p class=\"wp-block-paragraph\">For listeners, when we do the rundown, it has 38 pages and we&#8217;re kind of skipping over over 30 of those. So there&#8217;s a lot of work getting into WordPress 7.1, especially because the 3.6 release of Gutenberg was the last one. So everybody wanted to kind of get stuff in. That&#8217;s why it&#8217;s so exploded. But it&#8217;s mostly bug fixes from things that were in before. So we are not talking about those here. But make sure that you read the release notes that are on the Make blog and then, yeah, there&#8217;s a lot of information coming at you for 7.1. So carve out the time to study some of those that are really important for you. </p>\n\n\n\n<h3 class=\"wp-block-heading\">Tools</h3>\n\n\n\n<p class=\"wp-block-paragraph\">One of them I wanted to highlight is on the Gutenberg Times. There is a blog post about how to approach the iframe editor for the post editor. So the iframe that every block editor is now going to be loaded in an iframe. That has the advantages that other designs and artifacts from the admin page do not creep into the editor. And that has been done in the site editor, template editor, and the pattern editor since 2021. Only the post editor, who was— that was the first one that was a block editor, was still loaded in an admin page. And now with 7.1, the post editor will also go into an iframe. But with the history of older blocks and older block collections, there might be some quirks there. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The rule of thumb is if you load your block in the site editor in a template or something like that and it works, then it will also work in the post editor with no problem with the post editor iframe. If you see quirks, you probably— and the article is for developers and it goes through, okay, what were other people doing with the post editor that might not work with the iframe. And it goes through all the different scenarios and how to fix them or how to alleviate them. But there&#8217;s a lot of anxiety, but I have yet to see blocks that break in the iframe. But I only have a certain viewpoint there. I only use certain things. I&#8217;m gonna put the livestream YouTube video as well as the link to the article on the Gutenberg Times into the show notes so you can all follow up on it. </p>\n\n\n\n<p class=\"wp-block-paragraph\">All right, so you made it, Faith! Yay, congratulations!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Thank you.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: All right, dear listeners, as always, the show notes will be published on <a href=\"http://gutenbergtimes.com/podcast\">gutenbergtimes.com/podcast</a>. This is the 133rd episode; 133 is the episode number. And if you have questions, suggestions, or news, just send them to us in the <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a>. That&#8217;s <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a>. And thank you, Faith, for joining me for the first time. You did an awesome job. Thank you so much. And I hope you come back. I didn&#8217;t scare you away.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol</em>: Thank you too. Thank you too. Thank you for having me.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: Oh, absolutely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Faith Imokol:</em> Absolutely.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Birgit Pauli-Haack</em>: We have fun. Yeah. Thank you for listening, dear listeners, and goodbye and to the next time. Bye-bye.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 02 Aug 2026 08:21:46 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:19:\"Gutenberg Changelog\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:19:\"Matt: Tesla Spyware\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153813\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:36:\"https://ma.tt/2026/07/tesla-spyware/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:823:\"<p class=\"wp-block-paragraph\">I noticed my Model X was uploading ~2.6gb of something to Tesla when it parked and connected to WiFi.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-153816\" height=\"411\" src=\"https://i0.wp.com/ma.tt/files/2026/07/tesla-data-sharing-recreation-1024x696.png?resize=604%2C411&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Hopefully turning all these settings off stops it; otherwise, I <a href=\"https://www.nbcnews.com/business/business-news/tesla-workers-shared-sensitive-images-recorded-by-customer-cars-rcna78502\">might need a new car</a>. <a href=\"https://www.mozillafoundation.org/en/privacynotincluded/articles/its-official-cars-are-the-worst-product-category-we-have-ever-reviewed-for-privacy/\">But are any good</a>?</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 01 Aug 2026 05:27:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:137:\"Gutenberg Times: WordPress 7.1 is afoot, Gutenberg 23.6, iframed post editor, Abilities API, Studio Code and more — Weekend Edition 371\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46286\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:141:\"https://gutenbergtimes.com/wordpress-7-1-is-a-foot-gutenberg-23-6-iframed-post-editor-abilities-api-studio-code-and-more-weekend-edition-371/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:26556:\"<p class=\"wp-block-paragraph\">Hi there, </p>\n\n\n\n<p class=\"wp-block-paragraph\">This week I realized, I have been building websites for 30 years. from Notepad and hand-coded HTML to HomeSiteX over Coldfusion to WordPress, Nodejs and ReactJS to Python and Claude. It&#8217;s been a fantastic journey. It never gets old. I still learn new things every single day. I cherish most the friends I made along the way. I also found my notes about the WordCamps I attended, spoke at and organized. The first one was WordCamp Tampa in 2014. In 2026, I will probably attended my 30th WordCamp as well, Athens in December 2026.  It&#8217;s a bit out, so let&#8217;s see if it works out. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Back to the here  and now: It&#8217;s finally here the <a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/\">WordPress 7.1 Source of Truth</a> with all the big and small changes coming to a WordPress instance near you. It&#8217;s again more like a book. Digest in small dosis. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Have a fabulous weekend! </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n\n\n\n<h2 class=\"wp-block-heading\" id=\"wordpress-7-1-updates\">WordPress 7.1 updates </h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/news/2026/07/wordpress-7-1-beta-4/\"><strong>WordPress 7.1 Beta 4</strong></a> was release this week. </li>\n\n\n\n<li>It&#8217;s still time to <a href=\"https://make.wordpress.org/test/2026/07/15/help-test-wordpress-7-1/\">Help Test WordPress 7.1</a></li>\n\n\n\n<li>The <a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/\"><strong>WordPress 7.1 Source of Truth</strong></a> is out. </li>\n</ul>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">On the <a href=\"https://wpbuilds.com/2026/07/30/478-inside-wordpress-7-1-responsive-styling-new-blocks-media-modal-and-behind-the-scenes-changes/\"><strong>WPBuilds podcast series At the Core</strong>, </a><strong>Anne McCarthy</strong> and I talked with <strong>Nathan Wrigley</strong> about WordPress 7.1. We cover responsive styling, the persistent admin bar, and richer inline notes, plus why the new image crop modal and customisable viewports change your day-to-day editing. You&#8217;ll also hear how community feedback saved the Classic Block, where the collaborative editing outreach stands, and which developer changes to test now.</p>\n\n\n\n<figure class=\"wp-block-image size-full is-style-no-vertical-margin\"><img alt=\"Birgit Pauli-Haack, Anne McCarthy and Nathan Wrigley recording the podcast episode. \" class=\"wp-image-46400\" height=\"215\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-07-31-at-11.29.00.png?resize=652%2C215&#038;ssl=1\" width=\"652\" /></figure>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Responsive styling finally lands in the block editor, and The WP Minute+ <a href=\"https://thewpminute.com/why-wordpress-7-1-will-improve-your-workflow/\">podcast has release lead Anne McCarthy demoing it</a> with Eric Karkovack. You&#8217;ll also get the reasoning behind what didn&#8217;t make 7.1, including collaborative editing, plus how Classic Block deprecation is being paced. Anne talks about her first turn as release lead and points out hidden gems like the &#8216;On This Day&#8217; widget and custom icon registration for the Icon block. The episode<a href=\"https://www.youtube.com/watch?v=lR17090NeGA&amp;t=6s\"> <strong>Why WordPress 7.1 Will Improve Your Workflow</strong></a> is also available as video.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\"><strong>More Devnotes: </strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/07/31/filtering-site-editor-screens-in-wordpress-7-1/\">Filtering Site Editor Screens in WordPress 7.1</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-minimum-width/\">New Block Support</a>: <a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-minimum-width/\">Minimum Width</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-background-gradient-background-gradient/\">New Block Support: Background Gradient (background.gradient)</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/31/design-system-theming-in-wordpress-7-1/\">Design System Theming in WordPress 7.1</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/31/json-schema-preparation-for-client-compatibility-in-wordpress-7-1/\">JSON Schema preparation for client compatibility in WordPress 7.1</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">There are still more to come and they will be published next week, together with the WordPress 7.1 Field Guide. </p>\n\n\n\n<p class=\"wp-block-paragraph\"> A list of <a href=\"https://make.wordpress.org/core/tag/dev-notes+7-1/\">all the dev notes can be reviewed from the Make Core blog</a></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Anne McCarthy</strong> gives a candid account of <a href=\"https://nomad.blog/2026/07/28/behind-the-scenes-of-a-punted-feature-of-7-1/\">the punted inherited styles indicator </a>and its design dead ends. If you&#8217;ve ever watched someone style a template expecting it to apply site-wide, that&#8217;s the problem she&#8217;s chased since the FSE Outreach Program. Blue dots, diamonds, tooltips versus infotips, two competing reset paths — none settled, and summer holidays thinned the reviewer pool. She&#8217;s aiming at 7.2.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"gutenberg-23-6-released\">Gutenberg 23.6 released</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Last week, Gutenberg 23.6 was already released. The WordPress 7.1 tech co-lead. Aki Hamano highlighted in his post <a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/\">What’s new in Gutenberg 23.6? (July 22, 2026)</a></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/#the-playlist-and-tabs-blocks-are-now-stable\">The Playlist and Tabs blocks are now stable</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/#enhancements-to-notes\">Enhancements to Notes</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/#a-dynamic-mode-for-the-gallery-block\">A dynamic mode for the Gallery block</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/#icon-collections-and-a-custom-icon-registration-api\">Icon collections and a custom icon registration API</a></li>\n</ul>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">This week on the Gutenberg Changelog podcast, my guest was <strong>Faith Imokol</strong> from Uganda. We began with the wonderful work of the WordPress community there, who have put together a series of events — WordCamps, Campus Connect, and a website competition — bringing WordPress to schools, colleges, and universities, and to thousands of students and users. Then we turned to the latest release and had a great time going through the details. As always, the episode drops in your favorite podcast app over the weekend.</p>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-133-gutenberg-23-6-release-and-wordpress-7-1/\">Gutenberg Changelog #133 – Gutenberg 23.6 Release and WordPress 7.1</a></p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46424\" height=\"186\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/08/Screenshot-2026-07-31-at-13.13.07.png?resize=652%2C186&#038;ssl=1\" width=\"652\" /></figure>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div></div></div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">No PHP template, no shortcode, no custom block — Meta Box fields can now feed core blocks directly through <a href=\"https://metabox.io/introducing-block-bindings/\"><strong>block bindings for custom fields</strong></a>. <strong>Lua Nguyen</strong> shows the setup: select a Paragraph, Heading, Image, or Button, open Attributes in the sidebar, pick a Meta Box source, choose your field. Sources cover post, term, author, and settings-page fields, and an image field binds URL, alt, title, and caption separately. WordPress 6.5+, though the Attributes panel needs 6.9.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Coming to the Site Editor from Elementor or Divi means learning new vocabulary, and Ollie&#8217;s ground-up <a href=\"https://olliewp.com/wordpress-site-editor/\"><strong>guide to the WordPress Site Editor</strong></a> by <strong>Gina Lucia </strong>covers it: templates, template parts, patterns, global styles, navigation, the Font Library, and each toolbar button, starting at <code>Appearance → Editor</code>. A comparison table weighs both approaches on performance, flexibility, and portability. Ollie-specific tips sit alongside the core explanations, so you can read past them if you use another theme. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">A typical Elementor page ships 200–400 KB of extra frontend assets, three to five times a native block build — the number behind <strong>Bikash Pun Magar</strong>&#8216;s case for <a href=\"https://envitetech.com/how-we-use-custom-gutenberg-blocks-instead-of-page-builders/\"><strong>custom Gutenberg blocks over page builders on client sites</strong></a>. You get conditional per-block asset loading, HTML you control line by line, and content stored in native block grammar rather than a proprietary format. He&#8217;s fair about where Elementor still fits: prototypes and solo builders wanting pixel control without code.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">The theme.json schema resolves to more than 40MB across hundreds of nested properties, which is why <strong>Sérgio Santos</strong> built <a href=\"https://s3rgiosan.com/editing-theme-json-should-not-feel-like-editing-json/\"><strong>a form-driven visual editor for theme.json</strong></a> as a VS Code extension. Fields come from the official schema rather than hand-written forms, and a weekly scan of core and Gutenberg adds experimental properties with honest badges. The feature Santos says changed his workflow: every preset shows the CSS variable name it will generate as you type the slug.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s also a companion WordPress plugin that mounts the same editor under <code>Appearance</code>. There will be dragons though: <img alt=\"🐲\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f432.png\" style=\"height: 1em;\" /> Santos flags it as an experiment as it overwrites theme.json in place with no revisions or backups.</p>\n\n\n<div class=\"ng-block-91df1aa6c6a4fb5a wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\"><div class=\"ng-block-690cda8fcc31145c wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p></div></div></div></div>\n\n<div class=\"ng-block-7bea813287cd09c9 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2025/\">2025</a></strong></p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">If your custom blocks touch the global <code>window</code> or <code>document</code>, WordPress 7.1 will break them. <strong>Ryan Welcher </strong>walks through the<strong> </strong>forced <strong><a href=\"https://www.youtube.com/watch?v=4PrD1jzfD6E\">iframed post editor canvas</a>,</strong> landing August 19th with no flag to check and no opt-out. Five demos cover viewport detection, click-outside handlers, editor styles, admin body-class CSS, and unmaintained third-party libraries, with fixes using ownerDocument, defaultView, useRefEffect, editorStyle in block.json, and patch-package. His demo plugin ships broken and fixed versions of each.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Welcher also published a detailed tutorial: <a href=\"https://gutenbergtimes.com/the-post-editor-is-going-full-iframe-what-block-developers-need-to-know-before-wordpress-7-1/\"><strong>The post editor is going full iframe: what block developers need to know before WordPress 7.1</strong></a></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"what-s-new-in-playground\">What&#8217;s new in Playground?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Some people still assumed every Playground was temporary. Persistence, multiple sites, Blueprints, file editing — all already there, just easy to miss, which is what <a href=\"https://make.wordpress.org/playground/2026/07/31/meet-the-new-wordpress-playground-interface/\"><strong>the new WordPress Playground interface</strong></a> sets out to fix. A customizable Dock gathers those tools into one bottom toolbar: New, Playgrounds, Blueprint, Site Settings, Database, Files, Logs, Export. It&#8217;s navigation, not new capability. The design came out of the Playground table at WordCamp Europe Contributor Day, after Adam Zieliński used AI to explore 400+ variations.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Point a coding agent at WordPress Playground and it reads an instruction file first. <a href=\"https://make.wordpress.org/playground/2026/07/28/one-playground-three-workflows-consistent-agent-guidance-across-surfaces/\"><strong>The wp-playground agent skill</strong></a> now splits that file into a 52-line router plus focused references, so your agent loads the CLI details only for a local run and the sharing rules only for a share link — encoding, CORS, public hosting. <strong>Fellyph Cintra</strong>&#8216;s four-scenario benchmark scored 24/24 against 22/24 for the old version, one run per prompt. All this is explain in more details in the post <a href=\"https://make.wordpress.org/playground/2026/07/28/one-playground-three-workflows-consistent-agent-guidance-across-surfaces/\"><strong>One Playground, three workflows: Consistent agent guidance across surfaces</strong></a> in the team&#8217;s Make Blog. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">In a third post, <strong>Fellyph Cintra</strong> walks you through <a href=\"https://make.wordpress.org/playground/2026/07/22/manage-wordpress-playground-sites-programmatically/\"><strong>programmatic site management in WordPress Playground</strong></a>: from DevTools you can list, create, save, rename, and switch sites, change PHP or networking, and run PHP inside a site to check active plugins. Order matters — temporary sites must be saved before you can rename or reconfigure them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One caveat worth knowing if it runs alongside the other Playground item: this API belongs to playground.wordpress.net only. It isn&#8217;t in the <code>@wp-playground/client</code> package, the CLI, or embedded Playgrounds via <code>/remote.html</code> — those need the JavaScript API instead.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-and-wordpress\">AI and WordPress </h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Carlo Daniele</strong>&#8216;s guide to <a href=\"https://kinsta.com/blog/wordpress-abilities-api/\">the Abilities API for plugin developers</a> stays on fundamentals: the input schema, output schema, callback, and permission check that together form an ability&#8217;s contract, and the WP-CLI commands that let you inspect one. A fresh install ships three — site info, user info, environment info. His example registers an audio-to-blocks process from an existing plugin and triggers it over the wp-abilities/v1 REST route.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">Where Carlo Daniele registers a single ability, <strong>Jonathan Bossenger </strong>composes three into <strong><a href=\"https://developer.wordpress.org/news/2026/07/build-your-first-ai-powered-wordpress-plugin/\">your first AI-powered WordPress plugin</a>.</strong> Two call the AI Client, a third orchestrates them via <code>wp_get_ability()</code> and <code>execute()</code>, turning an image URL into a draft post. The same ability then answers over curl, from a React settings page, and from Claude Desktop through the MCP Adapter. Gotchas included: base64 data URIs for vision providers, stray markdown fences, and request timeouts.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">One rule for this stream: no hand-written code. <strong>Ryan Welcher</strong> takes <a href=\"https://www.youtube.com/watch?v=hrR77NyQzYs\"><strong>a full WordPress site build with Studio Code</strong></a> end to end for his son&#8217;s hockey team, and you watch a custom post type, a teams taxonomy, an Advanced Query Loop roster, and junior/intermediate/senior tabs come together by direction alone. The highlight is the agent reaching for block bindings unprompted. The lowlight: rogue PHP metaboxes, and a PHP-first answer where he wanted a SlotFill.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n<div class=\"ng-block-6b42e837d3e6105f wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\"><div class=\"ng-block-f88ebf0b9baa0c1f wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p></div></div></div></div>\n\n<div class=\"ng-block-1aae85a84cd56754 wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></div></div></div></div>\n\n<div class=\"ng-block-09c405bcb92c3c3d wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-612c62e788c8964f wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\"><div class=\"ng-block-e21208084dbaef24 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 14px; font-family: Helvetica; line-height: 0.2; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong>Featured Image: </strong></p></div></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 01 Aug 2026 01:17:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"Matt: Possible Futures of Happiness\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=153785\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"https://ma.tt/2026/07/possible-futures-of-happiness/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3610:\"<p class=\"wp-block-paragraph\">At <a href=\"https://automattic.com/\">Automattic</a>, we don&#8217;t have customer service or support, we have <a href=\"https://happinessengineer.blog/\">Happiness Engineers</a>. <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s also a #ceo <a href=\"https://slack.com/\">Slack</a> channel where anyone can drop in and request a meeting, which my esteemed colleague <a href=\"https://www.dpresident.net/\">Damianne President</a> did, and this morning we had an interesting chat that set my mind racing about how we might engineer happiness in the future.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>One overriding assumption:</strong> Personal agents will trounce company agents in most cases. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your personal agent can — or soon will — know all your history, your calendar, your email, your preferences, and your photos, and it speaks your language. So much time is wasted in traditional support trying to see through the customer&#8217;s eyes, or authenticate them. That goes away, but watch your thinking! It&#8217;s so easy to fall into the mental model trap of legacy chatbots and data models.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As a company, your website, your <a href=\"https://wordpress.org/\">WordPress</a>, documentation, tutorials, menus, manuals need to be amazing and up to date. That&#8217;s the source of truth, and an agent will read all of it!</p>\n\n\n\n<p class=\"wp-block-paragraph\">The interface and APIs remain because that&#8217;s useful to both human visitors and the agents.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Whenever possible, make support public. More blogs and <a href=\"https://bbpress.org/\">bbPress</a>. I actually weep a little when I think of how many beautiful words are written by our Happiness Engineers that are only ever seen once in a chat box or email thread.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My goal with our products is that support is radically available, and you almost never have to use it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re in a support role, I think you can pick a lane based on where you get energy. </p>\n\n\n\n<p class=\"wp-block-paragraph\">If you love looking at screens, I think there&#8217;s a future where customer service wizards are watching over an Iron Man-like interface, armies of chat bots talking to people, where they can see how they&#8217;re going and intervene or nudge them as needed. There&#8217;s a ton of work in tuning agents and interactions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If people recharge you, I actually think this will be the greatest era. All of the basic, mechanical stuff will be automated, but I think human connection will be what economists call a <a href=\"https://en.wikipedia.org/wiki/Veblen_good\">Veblen good</a>, more in demand even as it is more expensive. </p>\n\n\n\n<p class=\"wp-block-paragraph\">I think Happiness Engineering in the future will look a lot more like community building. A bot can&#8217;t host a meetup or a <a href=\"https://central.wordcamp.org/\">WordCamp</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I <a href=\"https://ma.tt/2023/10/wowza/\">was the biggest Waymo fanboy</a>, but this year with lots of trips to and from hospitals with Om I found myself craving human connection and used Uber more than ever. (It also gave me a chance to practice the one repeatable way that money <em>can</em> buy happiness, which is keeping a couple Benjamins in your back pocket and surprising people with them.)</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 30 Jul 2026 16:54:41 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:46:\"Gutenberg Times: WordPress 7.1 Source of Truth\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=46291\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:131322:\"<p class=\"wp-block-paragraph\">Welcome to the Source of Truth for WordPress 7.1!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Before you dive headfirst into all the big and small changes and pick your favorites, make sure to read these preliminary thoughts about this post and how to use it. If you have any questions, leave a comment or email me at <a href=\"mailto:pauli@gutenbergtimes.com\">pauli@gutenbergtimes.com</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A huge &#8220;Thank you&#8221; to Anne McCarthy, Justin Tadlock, Isabel Brison, Adam Silverstein, Ramon Dodd, Andrew Serong, Hans-Gerd Gerhards, Marin Atanasov, Krupa Nanda, Aaron Robertshaw, Ben Dwyer, Brent MacKinnon, Ashar Fuadi, and a lot more. It still takes a village. Also huge respect to the whole release squad on getting WordPress 7.1 over the finish line.</p>\n\n\n\n<div class=\"wp-block-group is-content-justification-left is-nowrap is-layout-flex wp-container-core-group-is-layout-fbe4aca3 wp-block-group-is-layout-flex\" style=\"font-style: italic; font-weight: 400;\">\n<p class=\"wp-block-paragraph\">Estimated reading time </p>\n\n\n<div class=\"wp-block-post-time-to-read\">37–55 minutes</div>\n\n\n<p class=\"wp-block-paragraph\">at </p>\n\n\n<div class=\"wp-block-post-time-to-read\">8,723 words</div></div>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><strong>Table of Contents</strong></p>\n\n\n<nav class=\"wp-block-table-of-contents\"><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#changelog\">Changelog</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#important-note-guidelines\">Important note/guidelines</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#overview\">Overview</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Resources</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#assets\">Assets </a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#tags\">Tags</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Priority Items for WordPress 7.1</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#responsive-styles-for-blocks\">Responsive styles for blocks</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#viewport-breakpoint-customization\">Viewport breakpoint customization</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#interactive-states-styling-hover-focus\">Interactive states styling (hover, focus)</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#media-editor-modal-and-free-form-image-cropper\">Media editor modal and free-form image cropper</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#client-side-media-processing-improvements\">Client-side media processing improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#icons-now-inherit-color-and-the-icons-api-takes-shape\">Icons now inherit color, and the Icons API takes shape</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#for-developers-registering-more-collections\">For developers: Registering more collections</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#admin-bar-everywhere\">Admin Bar everywhere </a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#new-blocks\">New Blocks</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#playlist-block\">Playlist block</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#tabs-block\">Tabs block</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#improved-blocks-and-block-handling\">Improved Blocks and Block handling</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-transforms-preview-first-convert-faster\">Block transforms: preview first, convert faster</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#combine-gradient-and-image-backgrounds\">Combine gradient and image backgrounds</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#cover-block-control-video-embed-providers\">Cover Block: control video embed providers</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#gallery-attached\">Gallery and the attached images workflow in the Media Library</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#image-block\">Image Block: Mark as decorative toggle</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#login-out-block-improvements\">Login/out Block Improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#navigation-block-and-link-creation\">Navigation Block and Link Creation</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#search-block-styling-theme-builder-site-admin-end-user\">Search block Styling</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#query-block\">Query block</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#general-quality-of-life-improvements\">General quality of life improvements. </a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#pattern-editing-experience-improvements\">Pattern editing experience improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-width-and-layout-controls\"> Block Width and Layout Controls</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#link-control-and-preview-enhancements\">Link Control and Preview Enhancements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#additional-css-validation\">Additional CSS Validation</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-editor-attribute-handling\">Block Editor Attribute Handling</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#image-handling-improved\">Image handling improved</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#post-template-layout-improvements\">Post Template Layout Improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#post-title-block-enhancements\">Post Title Block Enhancements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-inserter-enhancements\">Block Inserter Enhancements</a></li></ol></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#editor-enhancements\">Editor enhancements</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#notes-move-toward-a-full-commenting-workflow\">Notes move toward a full commenting workflow</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#dedicated-identity-section\">Dedicated Identity section</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#visual-revisions-improvement\">Visual revisions improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#apply-globally-now-with-review-panel\">Apply Globally now with review panel</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#admin-workflow-updates\">Admin / Workflow updates</a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#organized-command-palette\">Organized command palette</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#change-a-comment-s-parent-from-the-edit-comment-screen\">Change a comment&#039;s parent from the Edit Comment screen</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#see-an-excerpt-of-posts-without-titles\">See an excerpt of posts without titles</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#media-library-infinite-scrolling-is-back-on-by-default-with-a-per-user-opt-out\">Media Library: infinite scrolling is back on by default, with a per-user opt-out</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#hosts-can-now-tune-speculative-loading-defaults\">Hosts can now tune speculative loading defaults</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#developer-goodies\">Developer Goodies </a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#post-editor-iframe-now-always-on\">Post editor iframe now always on</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#abilities-api-opens-up-its-execution-pipeline\">Abilities API opens up its execution pipeline</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#global-styles-and-theme-json\">Global Styles and theme.json </a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#text-shadow-support-for-theme-json\">Text Shadow support for theme.json</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#text-align-block-support-migration\">Text-Align Block Support Migration</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-visibility\">Block Visibility</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-supports-css-variables-by-feature-selector\">Block Supports: CSS variables by feature selector</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#a-minimum-width-option-for-block-dimensions\">A minimum-width option for block dimensions</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#design-system-theme-provider\">Design System Theme Provider </a><ol><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#admin-color-schemes-in-site-editor\">Admin color schemes in Site Editor</a></li></ol></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#mix-static-html-with-editable-blocks\">Mix static HTML with editable blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#block-bindings-for-list-items-and-inner-blocks\">Block Bindings for list-items and inner blocks</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#connectors-authentication-improvements\">Connectors authentication improvements</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#blocks-package-stabilizes-two-experimental-functions\">Blocks package stabilizes two experimental functions</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#post-author-notifications-the-filter-decides\">Post author notifications: the filter decides</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#accessible-tooltips-and-toggle-tips-api\">Accessible tooltips and toggle tips API</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#filtering-site-editor-screens\">Filtering Site Editor screens</a></li><li><a class=\"wp-block-table-of-contents__entry\" href=\"https://gutenbergtimes.com/feed/#post-list-table-markup-changed-for-accessibility\">Post list table markup changed for accessibility</a></li></ol></li></ol></nav></div></div>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"changelog\">Changelog </h2>\n\n\n\n<p class=\"wp-block-paragraph\">Any changes are cataloged here as the release goes on.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>July 30, 2026 </strong>&#8211; First edition.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>July 31, 2026</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Added <a href=\"https://gutenbergtimes.com/feed/#apply-globally-now-with-review-panel\">Apply Globally now with review panel</a> </li>\n\n\n\n<li>Added <a href=\"https://gutenbergtimes.com/feed/#filtering-site-editor-screens\">Filtering Site Editor screens</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>August 3, 2026</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Added info on <code><a href=\"https://gutenbergtimes.com/feed/#opt-out\">responsiveEditingEnabled</a></code> editor setting</li>\n\n\n\n<li>Added link to <a href=\"https://make.wordpress.org/core/2026/08/03/iframed-editor-changes-in-wordpress-7-1/\">Iframed Editor Changes in WordPress 7.1</a> </li>\n\n\n\n<li>Added <a href=\"https://gutenbergtimes.com/feed/#abilities-api-opens-up-its-execution-pipeline\">updates to the Abitilites API</a></li>\n\n\n\n<li>Removed Tags from the headlines as they borked the TOC</li>\n\n\n\n<li>Added link to the  dev note for the <a href=\"https://gutenbergtimes.com/feed/#accessible-tooltips-and-toggle-tips-api\">Accessible tooltips</a> </li>\n\n\n\n<li>Added <a href=\"https://gutenbergtimes.com/feed/#post-list-table-markup-changed-for-accessibility\">Post list table markup changed for accessibility</a> section</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>August 4, 2026</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Removed <strong>On This Day widget </strong>information <a href=\"https://core.trac.wordpress.org/ticket/65801\">per this ticket</a>.  Punted to 7.2 pending more design input. </li>\n\n\n\n<li class=\"has-small-font-size\">Corrected the  <code>\"-current\": { \"color\": { \"text\": \"pink\" }</code>&#8221; code example. </li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>August 5, 2026</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Removed the &#8220;On This Day&#8221; from the  Overview </li>\n\n\n\n<li>Added <code>wp_get_abilities()</code> filtering to <a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/#abilities-api-opens-up-its-execution-pipeline\">the Abilities API section</a> </li>\n\n\n\n<li>Added the <a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/#post-author-notifications-the-filter-decides\"><code>notify_post_author</code> filter behavior change</a>.</li>\n\n\n\n<li>Added the Navigation font-size propagation change to the <a href=\"https://gutenbergtimes.com/wordpress-7-1-source-of-truth/#navigation-block-and-link-creation\">Navigation Block section</a></li>\n\n\n\n<li>Added section <a href=\"https://gutenbergtimes.com/feed/#hosts-can-now-tune-speculative-loading-defaults\">Host can now tune speculative loading defaults</a></li>\n\n\n\n<li>Updated dev note links from draft previews to published versions (Responsive styles, Filtering Site Editor screens)</li>\n\n\n\n<li>Updated the Resources section: linked the published <a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">WordPress 7.1 Field Guide</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>August 11, 2026</strong></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Updated the Highlight grid with latest iteration</li>\n\n\n\n<li>Updated the Featured image with the 7.1 color schema</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"important-note-guidelines\">Important note/guidelines</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Try not to just copy and paste what’s in this post since it’s going to be shared with plenty of folks. Use this as inspiration for your own stuff and to get the best info about this release. If you do copy and paste, just remember that others might do the same, and it could lead to some awkward moments with duplicate content floating around online.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Each item has been tagged using best guesses with different high-level labels so that you can more readily see at a glance who is likely to be most impacted.<br />Each item has a high-level description, visuals (if relevant), and key resources if you would like to learn more.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"overview\">Overview</h2>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46684\" height=\"367\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Highlight-grid-7.1.png?resize=652%2C367&#038;ssl=1\" width=\"652\" /><figcaption class=\"wp-element-caption\"><em>WordPress 7.1 Highlight grid <a href=\"https://github.com/WordPress/gutenberg/issues/79297#issuecomment-5223798027\">draft August 10, 2026</a></em></figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 rounds out the block editor&#8217;s styling controls and makes working with media noticeably smoother. Long-requested features let you style how blocks look across three screen sizes and in interactive states like hover and focus — all without writing custom CSS. The admin experience becomes more personal, too, following you with your own color scheme and toolbar across every screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Handling images gets a considerable upgrade, too. The new media editor modal brings free-form cropping, rotation, and metadata editing into one workflow, and client-side media processing makes uploads faster and more resilient, with broader format support and better-optimized files. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The new Playlist and Tabs blocks enrich the layout options available out of the box and make for more creative information presentation. In the same realm fall the expanded Icon API with custom icon collections, dynamic galleries, and background gradients for more blocks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The unification of WP Admin and the block editors progresses as well: the editors now respect your admin color scheme, and the admin bar stays with you on every screen — including the editors and the front end. </p>\n\n\n\n<p class=\"wp-block-paragraph\">While real-time collaboration has been punted to a future WordPress version, the asynchronous collaboration in Notes took real steps forward with inline notes on partial text selections, @mentions, rich text formatting, and multiple notes per block.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Beyond the headliners, core blocks receive many quality-of-life improvements and bug fixes to make editing content in WordPress streamlined, consistent, and fast — and developers get an expanding set of APIs to build on.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\"><strong>Resources</strong></h3>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/test/2026/07/15/help-test-wordpress-7-1/\">Help Test WordPress 7.1 </a></li>\n\n\n\n<li>Follow along with <a href=\"https://make.wordpress.org/core/tag/dev-notes+7-1/\">Dev Notes published</a>. </li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/05/wordpress-7-1-field-guide/\">WordPress 7.1 Field Guide</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/06/19/roadmap-to-7-1/\">Roadmap to 7.1</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">This release consists of features from the Gutenberg plugin version 22.7 – 23.6. Here are the release posts of those plugin releases:  <a href=\"https://make.wordpress.org/core/2026/03/11/whats-new-in-gutenberg-22-7-11-march/\">22.7</a> | <a href=\"https://make.wordpress.org/core/2026/03/25/whats-new-in-gutenberg-22-8-25-march/\">22.8</a> | <a href=\"https://make.wordpress.org/core/2026/04/09/whats-new-in-gutenberg-22-9-8-april/\">22.9</a> | <a href=\"https://make.wordpress.org/core/2026/04/22/whats-new-in-gutenberg-23-0-22-april/\">23.0</a>  | <a href=\"https://make.wordpress.org/core/2026/05/07/whats-new-in-gutenberg-23-1-07-may/\">23.1</a> | <a href=\"https://make.wordpress.org/core/2026/05/21/whats-new-in-gutenberg-23-2-21-may/\">23.2</a> | <a href=\"https://make.wordpress.org/core/2026/06/03/whats-new-in-gutenberg-23-3-03-jun/\">23.3</a> | <a href=\"https://make.wordpress.org/core/2026/06/17/whats-new-in-gutenberg-23-3-03-jun-2/\">23.4</a> |  <a href=\"https://make.wordpress.org/core/2026/07/01/whats-new-in-gutenberg-23-5-july-1-2026/\">23.5</a> | <a href=\"https://make.wordpress.org/core/2026/07/22/whats-new-in-gutenberg-23-6-july-22-2026/\">23.6</a>  Later Gutenberg releases contain bug fixes, backported to WordPress 7.1. release branches.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"assets\">Assets </h3>\n\n\n\n<p class=\"wp-block-paragraph\">In this <a href=\"https://drive.google.com/drive/u/0/folders/1acZ_1UbQNat4VlRGoAwkCH3qygliC0vb\">Google Drive folder</a> you can view all assets in this document.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"tags\">Tags</h2>\n\n\n\n<p class=\"wp-block-paragraph\">To make this document easier to navigate based on specific audiences, the following tags are used liberally: </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>[end user]</strong>: end user focus. </li>\n\n\n\n<li><strong>[theme builder]</strong>: block or classic theme author. </li>\n\n\n\n<li><strong>[plugin author]</strong>: plugin author, whether block or otherwise.</li>\n\n\n\n<li><strong>[developer]</strong>: catch-all term for more technical folks. </li>\n\n\n\n<li><strong>[site admin]</strong>: this includes a “builder” type. </li>\n\n\n\n<li><strong>[enterprise]</strong>: specific items that would be of interest to or particularly impact enterprise-level folks</li>\n\n\n\n<li><strong>[all]</strong>: broad impact to every kind of WordPress user. </li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">How can you use these? Use your browser&#8217;s <strong>Find</strong> capability and search for the string including the brackets. Then use the arrows to navigate through the post from one result to the next.</p>\n\n\n\n<details class=\"wp-block-details is-layout-flow wp-block-details-is-layout-flow\">Short video on how to use the tags to navigate the post. \n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		</details>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Priority Items for WordPress 7.1</h2>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">WordPress 7.1 introduces significant enhancements to block-based design and editing. These priority features focus on responsive controls, interactive states, media management, and modernized Admin bar navigation.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"responsive-styles-for-blocks\">Responsive styles for blocks </h3>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">[theme builders] [site admin][end user]</p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Probably the most requested improvement of the block editor: after years of pushing intrinsic design for fonts and spacing, WordPress 7.1 makes responsive design a built-in, first-class part of the editing experience. The feature builds on earlier steps in this direction — the ability to show or hide blocks by screen size and the Navigation block&#8217;s customizable mobile overlay — and extends the idea to styling itself.</p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"alignright size-full is-resized\"><img alt=\"\" class=\"wp-image-46364\" height=\"760\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Responsive-Styles-in-Preview-dropdown.png?resize=518%2C760&#038;ssl=1\" style=\"width: 236px; height: auto;\" width=\"518\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">The feature is available across all block editors for Posts, Pages, Templates, Patterns,template parts and Navigation. Responsive styling follows a desktop-first model, letting styles cascade to smaller screens until you customize them for specific devices.</p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Viewport-specific values are currently limited to block sidebar settings (like typography, spacing, and colors). The controls work in Global Styles (affecting all instances of a block) and on individual block instances, across all block editors — Posts, Pages, Templates, Patterns, template parts, and Navigation. </p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Any controls from the toolbar that can&#8217;t be set by viewport will be hidden when a viewport state is enabled. Among the most significant controls: viewport-level aspect ratio presets for Image, Featured Image, and Cover blocks, so each can be optimized per device (<a href=\"https://github.com/WordPress/gutenberg/pull/78543\">#78543</a>). Alongside this work, the Layout controls moved from the Settings tab to the Styles tab, keeping all styling decisions together. </p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"opt-out\">Community feedback from the Call for Testing made sure this feature ships with an off switch via a new <code>responsiveEditingEnabled</code> editor setting: turned off, both the <strong>Responsive styles</strong> option in the <strong>View</strong> menu and the viewport selector in <strong>Global Styles</strong> disappear. It gates the editing interface only. Responsive styles already saved keep rendering as before. (<a href=\"https://github.com/WordPress/gutenberg/pull/80814\">#80814</a>). See code examples are in the responsive styles dev note. </p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">Follow the <a href=\"https://make.wordpress.org/test/2026/07/03/call-for-testing-responsive-styling/\">Call for Testing: Responsive Styling</a> to learn how to invoke the feature and what to look out for, and find the technical details in the Dev Note: Responsive block styles and configurable viewports in WordPress 7.1. </p>\n\n\n\n<p class=\"wp-block-paragraph\" id=\"resources-help-test-wordpress-7-1-fieldguide-dev-notes-are-scheduled-to-be-published-around-rc-august-5-links-in-this-document-are-to-the-draft-versions-roadmap-to-7-1of-note-this-release-consists-of-features-from-the-gutenberg-plugin-version-22-7-23-6-here-are-the-release-posts-of-those-plugin-releases-22-7-22-8-22-9-23-0-23-1-23-2-23-3-23-4-23-5-23-6-later-gutenberg-releases-contain-bug-fixes-backported-to-wordpress-7-1-release-branches\">You can find more technical details in the Dev Note: <a href=\"https://make.wordpress.org/core/2026/08/05/responsive-block-styles-and-configurable-viewports-in-wordpress-7-1/\">Responsive block styles and configurable viewports in WordPress 7.1</a>.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h4 class=\"wp-block-heading\" id=\"viewport-breakpoint-customization\">Viewport breakpoint customization</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Themes can now define custom breakpoints in theme.json, so both responsive styling and per-viewport block visibility work from your design system&#8217;s breakpoints instead of WordPress&#8217;s defaults. For theme developers and designers, this provides fine-grained, device-agnostic control over responsive behavior. (<a href=\"https://github.com/WordPress/gutenberg/pull/79104\">79104)</a>.</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">\"settings\": {\n		\"viewport\": {\n			\"mobile\": \"30rem\",\n			\"tablet\": \"45rem\"\n		}\n	}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #2AA198;\">&quot;settings&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;viewport&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;mobile&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;30rem&quot;</span><span style=\"color: #657B83;\">,</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;tablet&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;45rem&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	}</span></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/75707\">WordPress 7.1: Block visibility configurable breakpoints and theme.json integration</a> (#75707)</p>\n\n\n\n<p class=\"wp-block-paragraph\">This makes interactive design accessible to non-coders and theme builders. It eliminates the need to add custom CSS snippets for common interactions. </p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"interactive-states-styling-hover-focus\">Interactive states styling (hover, focus)</h4>\n\n\n\n<p class=\"wp-block-paragraph\">You can now style interactive pseudo-states (:hover:, :focus: or :active) for two blocks: Button and Navigation Link. The styling can be applied globally and per-instance without writing any CSS. For example, Users can change a button&#8217;s color on hover directly in the editor. (<a href=\"https://github.com/WordPress/gutenberg/pull/76491\">76491</a>) </p>\n\n\n\n<figure class=\"wp-block-image size-full is-resized\"><img alt=\"\" class=\"wp-image-46324\" height=\"377\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Interactive-states.png?resize=652%2C377&#038;ssl=1\" style=\"width: 569px; height: auto;\" width=\"652\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The underlying mechanism allows for the styling of the current menu item in a navigation block via theme.json (<a href=\"https://github.com/WordPress/gutenberg/pull/75736\">75736</a>).</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">\"core/navigation-link\": {\n  \"-current\": {\n    \"color\": { \"text\": \"#ff0000\" },\n    \"typography\": { \"fontWeight\": \"700\" },\n    \":hover\": {\n      \"color\": { \"text\": \"#0000ff\" }\n    },\n    \":focus\": {\n      \"color\": { \"text\": \"#00aa00\" }\n    },\n    \":active\": {\n      \"color\": { \"text\": \"#ff6600\" }\n    }\n  }\n}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #2AA198;\">&quot;core/navigation-link&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">  </span><span style=\"color: #859900;\">&quot;-current&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;color&quot;</span><span style=\"color: #657B83;\">: { </span><span style=\"color: #859900;\">&quot;text&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;#ff0000&quot;</span><span style=\"color: #657B83;\"> },</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;typography&quot;</span><span style=\"color: #657B83;\">: { </span><span style=\"color: #859900;\">&quot;fontWeight&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;700&quot;</span><span style=\"color: #657B83;\"> },</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;:hover&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">      </span><span style=\"color: #859900;\">&quot;color&quot;</span><span style=\"color: #657B83;\">: { </span><span style=\"color: #859900;\">&quot;text&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;#0000ff&quot;</span><span style=\"color: #657B83;\"> }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    },</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;:focus&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">      </span><span style=\"color: #859900;\">&quot;color&quot;</span><span style=\"color: #657B83;\">: { </span><span style=\"color: #859900;\">&quot;text&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;#00aa00&quot;</span><span style=\"color: #657B83;\"> }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    },</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;:active&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">      </span><span style=\"color: #859900;\">&quot;color&quot;</span><span style=\"color: #657B83;\">: { </span><span style=\"color: #859900;\">&quot;text&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;#ff6600&quot;</span><span style=\"color: #657B83;\"> }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">  }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">The Dev Note give you more details <a href=\"https://make.wordpress.org/core/2026/08/05/pseudo-and-custom-style-states-in-wordpress-7-1/\">Pseudo and custom style states in WordPress 7.1</a> and more code examples</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"media-editor-modal-and-free-form-image-cropper\">Media editor modal and free-form image cropper </h3>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"media-editor-modal-and-free-form-image-cropper-end-user-site-admin\">[end user][site admin]</p>\n\n\n\n<p class=\"wp-block-paragraph\">The new media editor modal replaces the inline cropping tool, accessed via the familiar <strong>Crop</strong> button, and brings together free-form and aspect-ratio cropping, flip, fine-grained rotation with snap guides, and metadata editing in one unified workflow. (<a href=\"https://github.com/WordPress/gutenberg/pull/78653\">78653</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78935\">78935</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78792\">78792</a>) </p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46325\" height=\"434\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Media-editor-modal.png?resize=652%2C434&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">This considerably improves the editing experience in WordPress Block editor. The goal was to eliminate the need for external tools for basic image editing. You can now exercise faster, more precise control over your images—fine-tuning framing, fixing orientation, or mirroring an image to better fit your layout in just a few clicks, all without breaking your editing flow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For the Cover Block, this new media editor modal is hooked up to the <strong>Crop background image</strong> button. The option appears whenever the Cover block uses an editable image, and the block automatically recalculates its overlay color and contrast after an edit, so text stays readable even if the crop removes the image&#8217;s brightest or darkest areas (<a href=\"https://github.com/WordPress/gutenberg/pull/79258\">79258</a> )<br /><br />Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/73771\">Media Editor Modal task tracking</a> (#73771)</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h3 class=\"wp-block-heading\" id=\"client-side-media-processing-improvements\">Client-side media processing improvements </h3>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"client-side-media-processing-improvements-developer-site-admin-enterprise\"><strong>[developer][site admin][enterprise]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">When you upload an image in the block editor, your browser — not your server — will now handle the creation of all sub-sized images using a WebAssembly (WASM) version of libvips (wasm-vips), a high-performance image processing library. The result stored on your server is improved over what server-side processing produced until today: smaller files generated directly on your device. Server-side image processing CPU usage could decline by more than 80% on capable devices (<a href=\"https://github.com/WordPress/gutenberg/pull/79188\">79188</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">The update also comes with broader modern image  format support that includes HEIC (the default format for iPhone photos), JPEGS with HDR gain maps (used by UltraHDR and Adaptive HDR), AVIF and WebP support built in. A great performance improvement is the GIF-to-video conversion feature for lighter, more efficient files that are faster to load on the front-end. This feature is opt-in right now. Uploads are also more resilient, with a progress indicator and automatic retries if your data connectivity drops off (<a href=\"https://github.com/WordPress/gutenberg/pull/76765\">76765</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79307\">79307</a>).</p>\n\n\n\n<p class=\"wp-block-paragraph\">For content creators uploading media, this update means better support for HDR images,  faster, more reliable uploads, broader format support, and better-optimized files without manual intervention.<br /><br />Plugin developers should note that some server-side hooks, including `wp_generate_attachment_metadata`, `image_resize_dimensions`, and `wp_handle_upload` may not fire as before. The team is working on documentation and mitigation strategies. (<a href=\"https://github.com/WordPress/gutenberg/issues/74333\">74333</a>)<br /><br />More in-depth information is available in the Dev Note <a href=\"https://make.wordpress.org/core/2026/07/22/client-side-media-processing-in-wordpress-7-1/\">Client-Side Media Processing in WordPress 7.1</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"icons-now-inherit-color-and-the-icons-api-takes-shape\">Icons now inherit color, and the Icons API takes shape </h3>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"icons-now-inherit-color-and-the-icons-api-takes-shape-theme-builder-plugin-author-developer-enterprise\"><strong>[theme builder][plugin author][developer][enterprise]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 shipped a built-in set of SVG icons for the block editor and the Icon block. With WordPress 7.1, this grows into a proper, public API: plugins and themes can register their own icons, group them into collections, render them on the server, and read them over the REST API.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For content creators, the most visible change is the Icon block&#8217;s picker: it now <a href=\"https://github.com/WordPress/gutenberg/pull/79681\">groups icons by collection</a>, with a tab per collection plus an &#8220;All&#8221; tab, and your search query carries over as you switch tabs. Custom icons from plugins and themes appear right alongside the core set. The block itself picked up several refinements: it <a href=\"https://github.com/WordPress/gutenberg/pull/79111\">inserts a default icon</a> so you&#8217;re never staring at an empty placeholder, offers <a href=\"https://github.com/WordPress/gutenberg/pull/77017\">flip and rotate controls</a> <a href=\"https://github.com/WordPress/gutenberg/pull/79192\">in the toolbar</a>, and shows <a href=\"https://github.com/WordPress/gutenberg/pull/80251\">text and background color controls by default</a>.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"for-developers-registering-more-collections\">For developers: Registering more collections</h4>\n\n\n\n<p class=\"wp-block-paragraph\">For developers, the pieces come together on the PHP side: register a collection with wp_register_icon_collection(), add icons with <code>wp_register_icon()</code> — from an inline SVG string or an .svg file — and <a href=\"https://github.com/WordPress/gutenberg/pull/78332\">print any registered icon</a> with wp_get_icon(), including size, CSS class, and an accessible label. Icon names get <a href=\"https://github.com/WordPress/gutenberg/pull/76079\">strict validation</a>, the <a href=\"https://github.com/WordPress/gutenberg/pull/80139\">registry&#8217;s register method is now public</a>, and REST API endpoints expose collections and icons to your own code. A dev note with full code examples is on its way to the Make Core blog.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One breaking change to flag: all 330 icons in @wordpress/icons v15 now declare <a href=\"https://github.com/WordPress/gutenberg/pull/79320\"><code>fill=\"currentColor\"</code></a>, so icons inherit the surrounding text color by default. If you&#8217;ve been tinting icons with the CSS fill property, switch to color — it&#8217;s more reliable, since an icon may use fill, stroke, or both internally. If you register your own icons, add fill=&#8221;currentColor&#8221; to their &lt;svg&gt; element to get the same behavior.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Dev Note <a href=\"https://make.wordpress.org/core/2026/07/24/registering-and-rendering-svg-icons-in-wordpress-7-1/\">Registering and rendering SVG icons in WordPress 7.1</a> holds all the details. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/75715\">SVG Icon API: Iteration for WordPress 7.1</a> (#75715)</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46329\" height=\"392\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/icons-block.png?resize=652%2C392&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"admin-bar-everywhere\">Admin Bar everywhere  </h3>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"admin-bar-everywhere-all\"><strong>[</strong>all<strong>]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">With WordPress 7.1, the WordPress admin bar which sits at the top of your site&#8217;s front end and other admin pages is now displayed when using block editor by default. It stays hidden when Fullscreen mode and Distraction-free mode are both turned on. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Until now, entering the editor in its default fullscreen mode meant the admin bar disappeared, cutting you off from the rest of wp-admin. Since the admin bar now provides site context, the update also replaces the top-left W/site icon in the site editor with an explicit back button, making the navigation control more obvious (<a href=\"https://github.com/WordPress/gutenberg/pull/79197\">79197</a>).  </p>\n\n\n\n<p class=\"wp-block-paragraph\">With this update also comes a design refresh: </p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>your site icon replaces the home icon, </li>\n\n\n\n<li>the profile avatar becomes circular, and </li>\n\n\n\n<li>the command palette keyboard shortcut moves into the Admin bar to remove visual clutter and resolve shortcut conflicts. (<a href=\"https://github.com/WordPress/gutenberg/pull/79060\">79060</a>) </li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">This keeps the familiar navigation with you on all screens again. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Dev Notes with all the details for users and developer can be found here: <a href=\"https://make.wordpress.org/core/2026/07/13/consistent-navigation-in-wordpress-7-1-with-persistent-toolbar/\">Consistent navigation in WordPress 7.1 with persistent toolbar</a>. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46296\" height=\"232\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/AdminBar-everywhere-site-icon.png?resize=652%2C232&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"new-blocks\">New Blocks </h2>\n\n\n\n<p class=\"has-text-align-right has-normal-font-size wp-block-paragraph\" id=\"new-blocks-all\"><strong>[all]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release expands the block library with versatile new tools. These additions provide content creators with improved ways to display interactive media and organize information.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"playlist-block\">Playlist block</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The new Playlist block lets you create audio playlists with waveform visualization, making it easy to showcase multiple tracks or podcast episodes in a single interactive player. Visitors can browse and play through your audio content without leaving the page. For content creators this provides a rich, modern listening experience built right into WordPress to highlight podcast episodes, track of music or talks. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Each track comes with its metadata: artwork, artist name, track number, and track length. The tracklist itself is configurable — you can set the play order and toggle artwork, artist names, track numbers, and <a href=\"https://github.com/WordPress/gutenberg/pull/78954\">track length</a> individually to suit the design of your page.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://github.com/WordPress/gutenberg/pull/75203\">WaveformPlayer visualization</a> comes with a <a href=\"https://github.com/WordPress/gutenberg/pull/76147\">visualization style selector</a>. You can set <a href=\"https://github.com/WordPress/gutenberg/pull/80065\">waveform and waveform background colors</a> for more granular theming and show the <a href=\"https://github.com/WordPress/gutenberg/pull/79938\">track artwork on the play button</a>, accessible for all visitors. The Playlist and Playlist Track blocks are available in the default block library.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This is the first version and contributors are working on improvements for the next WordPress version, too looking to add more waveform styles, shuffle and skip buttons, a hover overlay for more intuitive track scrubbing, as well as performance improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/77421\">Playlist Block: Iteration issue for 7.1</a> (#77421)</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46330\" height=\"371\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/playlist-block.png?resize=652%2C371&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"tabs-block\">Tabs block</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The new Tabs block organizes content into separate tabbed panels that visitors click through to navigate. It&#8217;s a design pattern that presents information compactly without overwhelming readers with a wall of text. It&#8217;s a common layout for FAQs, product features, or any content where you want to show options side-by-side. For editors, it&#8217;s a familiar, flexible layout pattern now available natively in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The block family consists of a Tab List for the navigation and Tab Panels for the content. Each panel accepts any blocks you like, and the tab buttons come with their own color, typography, border, and spacing controls, so the navigation can be styled to match your theme. Using the toolbar buttons you can reorder the tabs quickly. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Under the hood, the markup and keyboard behavior follow the best practices set out in <a href=\"https://www.w3.org/WAI/ARIA/apg/patterns/tabs/\">the tabs pattern from the W3C ARIA Authoring Practices Guide</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/WordPress/gutenberg/issues/73230\">Tracking: Stabilize Tabs Blocks</a> (#73230)</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h2 class=\"wp-block-heading\" id=\"improved-blocks-and-block-handling\">Improved Blocks and Block handling</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Core blocks receive numerous quality-of-life improvements in 7.1. These updates refine existing editing workflows, simplify media handling, and provide deeper customization for layouts and design.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"block-transforms-preview-first-convert-faster\">Block transforms: preview first, convert faster<sup> </sup></h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"block-transforms-preview-first-convert-faster-end-user-site-admin\"><strong>[end user][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Switching a block&#8217;s look or type is now much easier to evaluate before you commit. When you open the block switcher in the toolbar, the style options a theme provides — say, a Button&#8217;s &#8220;Outline&#8221; style — show live previews on hover, so you see exactly how your block will look with the style applied. (<a href=\"https://github.com/WordPress/gutenberg/pull/75889\">75889</a>) The same previews in the inspector&#8217;s Styles panel now match the toolbar presentation, so it no longer matters where you make the switch. (<a href=\"https://github.com/WordPress/gutenberg/pull/75989\">75989</a>) A small polish fix also centers the Navigation block&#8217;s preview in its preview pane. (<a href=\"https://github.com/WordPress/gutenberg/pull/75741\">75741</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Transforms got more capable, too: a block can now transform directly into a variation of another block. Instead of converting to a Group and then picking Row afterwards, the transform menu offers Row or Stack as direct targets — one step instead of two. (<a href=\"https://github.com/WordPress/gutenberg/pull/78713\">78713</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">The same &#8220;one step instead of two&#8221; thinking extends to legacy content. Pasting or converting an <code></code> shortcode now creates a proper Embed block instead of leaving raw shortcode text behind, so embeds from YouTube and other services display correctly right away (<a href=\"https://github.com/WordPress/gutenberg/pull/77937\">77937</a>)— and if you change your mind, undo restores a paragraph with the URL rather than deleting it. (<a href=\"https://github.com/WordPress/gutenberg/pull/77551\">77551). </a></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Shortcode block joins in as well: when its content matches a registered shortcode, it now offers block-specific transforms to convert it into the equivalent block. <a href=\"https://github.com/WordPress/gutenberg/pull/77944\">(77944</a>) </p>\n\n\n\n<p class=\"wp-block-paragraph\">For anyone maintaining a site with years of shortcode-based posts, that removes a tedious cleanup step on the way to block-based editing.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"combine-gradient-and-image-backgrounds\">Combine gradient and image backgrounds </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"combine-gradient-and-image-backgrounds-end-user-theme-builder-site-admin\"><strong>[end user]</strong> <strong>[theme builder][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">More blocks now support background gradients through the new background.gradient block support, which<a href=\"https://github.com/WordPress/gutenberg/pull/75859\"> layers a gradient on top of a background image</a> instead of one overwriting the other — a translucent color wash over a photo, for instance, without custom CSS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Previously, gradients lived only in the Color panel, stored as a CSS background shorthand that clashed with any image on the block. The new support adds a Gradient control to the Background panel next to the existing Image control, and the style engine combines both into a single layered background-image value on individual blocks, in Global Styles, and via theme.json. A follow-up allows<a href=\"https://github.com/WordPress/gutenberg/pull/79791\"> modern color functions in standalone gradients</a>, and the<a href=\"https://github.com/WordPress/gutenberg/pull/77279\"> text and background color controls moved</a> to the Typography and Background panels to match.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 ships with six blocks supporting the new gradients:<a href=\"https://github.com/WordPress/gutenberg/pull/75859\"> Group</a>,<a href=\"https://github.com/WordPress/gutenberg/pull/79391\"> Verse</a>,<a href=\"https://github.com/WordPress/gutenberg/pull/79840\"> Accordion</a>,<a href=\"https://github.com/WordPress/gutenberg/pull/79841\"> Pullquote</a>,<a href=\"https://github.com/WordPress/gutenberg/pull/79842\"> Post Content</a>, and<a href=\"https://github.com/WordPress/gutenberg/pull/79843\"> Quote</a>. More will follow, with a long-term plan to migrate the older color.gradient to the new system across all blocks. There&#8217;s no built-in migration path in 7.1 yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For extenders, opting in follows the familiar block supports pattern. Custom blocks declare it in their block.json:</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">\"supports\": {\n	\"background\": {\n		\"gradient\": true\n	}\n}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #2AA198;\">&quot;supports&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	</span><span style=\"color: #859900;\">&quot;background&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;gradient&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #B58900;\">true</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">}</span></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">Themes control the setting via theme.json under settings.background.gradient (it&#8217;s also included in appearanceTools), and can define gradient values in styles — at the root, per block, or in style variations:</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">{\n	\"styles\": {\n		\"background\": {\n			\"gradient\": \"linear-gradient( 135deg, #000 0%, #fff 100% )\"\n		},\n		\"blocks\": {\n			\"core/group\": {\n				\"background\": {\n					\"gradient\": \"var:preset|gradient|vivid-cyan-blue\"\n				}\n			}\n		}\n	}\n}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #657B83;\">{</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	</span><span style=\"color: #859900;\">&quot;styles&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;background&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;gradient&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;linear-gradient( 135deg, #000 0%, #fff 100% )&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		},</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;blocks&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;core/group&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				</span><span style=\"color: #859900;\">&quot;background&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">					</span><span style=\"color: #859900;\">&quot;gradient&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;var:preset|gradient|vivid-cyan-blue&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">}</span></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">All the salient details in this Dev Note <a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-background-gradient-background-gradient/\">New Block Support in WordPress 7.1: Background Gradient (background.gradient)</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"cover-block-control-video-embed-providers\">Cover Block: control video embed providers </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"cover-block-control-video-embed-providers-theme-builder-plugin-author-enterprise-developer\"><strong>[theme builder][plugin author][enterprise][developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Besides gaining the new media editor modal for background images, the Cover block addresses a request from community feedback. When the block&#8217;s &#8220;Embed video from URL&#8221; feature shipped in WordPress 7.0, site builders<a href=\"https://github.com/WordPress/gutenberg/issues/75069\"> asked for a way to curate or disable it</a>. WordPress 7.1 adds a new allowedVideoProviders attribute to restrict which video providers are offered, or to remove the URL-embed option entirely by allowing none (<a href=\"https://github.com/WordPress/gutenberg/pull/80092\">#80092</a>). Existing embeds keep working; only new URL input in the editor is restricted. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The details are already reflected in the<a href=\"https://developer.wordpress.org/block-editor/reference-guides/core-blocks/core-blocks-media/core-block-cover/\"> Cover block&#8217;s documentation</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"gallery-attached\">Gallery and the attached images workflow in the Media Library </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"gallery-and-the-attached-images-workflow-in-the-media-library-end-user-site-admin\"><strong>[end user][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Images you upload while writing a post have always been &#8220;attached&#8221; to that post. This specifically true for older sites, pre-Block editor. Attached images where no accessible as an cluster and need to be added the block editor canvas one at a time. WordPress 7.1 finally puts that relationship to work in the editor, via an additional filter drop-down item <strong>Uploaded to this post </strong>in the Media Library Inserter modal. Photos and other media you&#8217;ve uploaded stay within reach for reuse instead of disappearing into the media library. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The Gallery block is the showcase: instead of hand-picking every image, a single <strong>Use attached images</strong> button populates a dynamic gallery from all media attached to the current post (<a href=\"https://github.com/WordPress/gutenberg/pull/78796\">#78796</a>). For content creators, this makes assembling image galleries faster and more flexible. It also helps reorganize image on older posts. The Source panel provides options for sorting the images. This brings the block editor handling of Galleries up to par with some features of the [ gallery ] shortcode.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46339\" height=\"169\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Use-attached-images-wp71.png?resize=652%2C169&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">To have entire freedom to control the Gallery block, the Detach feature comes in handy. A <strong>Detach</strong> button in the toolbar and in the sidebar’s <strong>Source</strong> panel, makes out a stand-alone Gallery without the dynamic connetion to the post’s image. Using it help user to edit/upate the gallery block. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Below video visualizes the connection between a list of image attached to a post from the Media Library and the gallery block with the new feature. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking:<a href=\"https://github.com/WordPress/gutenberg/issues/77117\"> WordPress 7.1: dynamic galleries and post-attached media iteration issue</a> (#77117)</p>\n\n\n\n<p class=\"wp-block-paragraph\">It’s a step back toward the simplicity of dropping photos into a post and having WordPress do the arranging. It&#8217;s the first visible piece of a larger effort around<a href=\"https://github.com/WordPress/gutenberg/issues/76955\"> dynamic galleries and post-attached media</a>, with dynamic queries by date and eventually categories or tags ahead.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h3 class=\"wp-block-heading\" id=\"image-block\">Image Block: Mark as decorative toggle </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"image-block\"><strong>[end user][site admin]</strong></p>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"alignright size-full\"><img alt=\"\" class=\"wp-image-46343\" height=\"487\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/mark-as-decorative-edited.png?resize=263%2C487&#038;ssl=1\" width=\"263\" /></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">Screen readers announce every image to their users — but some images, like dividers and design flourishes, carry no information worth announcing. The Image block&#8217;s new &#8220;Mark as decorative&#8221; checkbox tells assistive technologies to skip such an image entirely on the front end, by rendering it with role=&#8221;none&#8221; in the published post. It now eliminates the question, did we forget an alt=text or was it a deliberate decision to leave the alt-text empty?</p>\n\n\n\n<p class=\"wp-block-paragraph\">There is further processing to come with the checked box. Marking an image decorative clears its alt text and disables captions and links, since an image that links somewhere or explains something isn&#8217;t decorative by definition. Until now, the accessible route was knowing the empty-alt-text convention; the checkbox makes the intent explicit, machine-readable, and available to every content creator. (<a href=\"https://github.com/WordPress/gutenberg/pull/78064\">78064</a>)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"login-out-block-improvements\">Login/out Block Improvements </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"login-out-block-improvements-theme-builder-site-admin-developer\"><strong>[theme builder][site admin][developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Login/Logout block has an option to display a full login form instead of a simple link — but until now, that form&#8217;s submit button ignored your theme entirely, rendering with plain browser-default styles that stuck out next to every other button on the site. With a block theme active, the submit button now carries the standard button classes (wp-block-button__link and wp-element-button), so it automatically picks up the button styling your theme defines in theme.json — colors, border radius, and all — with no custom CSS required. The block follows the same approach the Comments form already uses, resolving a mismatch first reported back in 2023. (<a href=\"https://github.com/WordPress/gutenberg/pull/76746\">76746</a>)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"navigation-block-and-link-creation\">Navigation Block and Link Creation </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"navigation-block-and-link-creation-theme-builder-site-admin-end-user\"><strong>[theme builder]</strong> <strong>[site admin][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Navigation block picks up several improvements that give site builders more freedom in what a menu can contain and where it can be edited. The Login/Logout block can now be<a href=\"https://github.com/WordPress/gutenberg/pull/75497\"> nested inside submenus</a> (#75497), handy for tucking account actions into a &#8220;My Account&#8221; dropdown instead of spending a top-level slot on them. New links can be<a href=\"https://github.com/WordPress/gutenberg/pull/75918\"> created directly from the sidebar List View</a> in the Site Editor (#75918), so building out a menu no longer requires clicking into each item on the canvas. And the Home Link block<a href=\"https://github.com/WordPress/gutenberg/pull/76672\"> gains previously missing controls</a> (#76672), bringing it up to par with its navigation siblings. </p>\n\n\n\n<p class=\"wp-block-paragraph\">One behavior change to note for theme builders: the Navigation block no longer force-propagates its font size down to individual menu items (<a href=\"https://github.com/WordPress/gutenberg/pull/77419\">#77419</a>). Until now, every navigation link, submenu, and page list item received the parent&#8217;s font-size markup — and because relative units multiply, nested dropdowns compounded dramatically (1.5em became 2.25em, then 3.375em). </p>\n\n\n\n<p class=\"wp-block-paragraph\">The block now relies on standard CSS inheritance instead, which also fixes mismatched typography between the editor canvas and the front end. Most themes need no changes, but themes that target <code>has-{slug}-font-size</code> classes directly on nav items should check their menus — the <a href=\"https://make.wordpress.org/core/2026/08/04/miscellaneous-block-editor-changes-in-wordpress-7-1/\">Miscellaneous Editor Changes dev note</a> includes a filter to restore the old markup if needed.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"search-block-styling-theme-builder-site-admin-end-user\">Search block Styling</h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"search-block-styling-theme-builder-site-admin-end-user\"><strong>[theme builder]</strong> <strong>[site admin][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A styling gap is closed in the release for the Search block: color settings now apply to the search input field even when the search button is disabled (<a href=\"https://github.com/WordPress/gutenberg/pull/77219\">77219</a>), so your search boxes match your design system regardless of which display options you choose.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The block also embraces modern HTML: it can now render inside the native &lt;search&gt; landmark element, which carries search semantics for browsers and assistive technologies without the manual role=&#8221;search&#8221; attribute. Because dropping that attribute could break existing theme CSS, the feature is opt-in — per block via a new HTML element selector in the Advanced panel, or site-wide with add_theme_support( &#8216;search-element&#8217; ) (#78485). Default output is unchanged, with a path to making the modern markup the default in a future release.(<a href=\"https://github.com/WordPress/gutenberg/pull/78485\">78485</a>)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"query-block\">Query block </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"query-block-theme-builder-site-admin-end-user\"><strong>[theme builder]</strong> <strong>[site admin][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Query block received an additional filter to control the list of blocks: You can now exclude the current post from a list of posts. This is useful when you want to add a list of posts with related posts. (<a href=\"https://github.com/WordPress/gutenberg/pull/64916\">64916</a>).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46345\" height=\"326\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Query-block-exclude-current-post-wp7-1.png?resize=652%2C326&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"general-quality-of-life-improvements\">General quality of life improvements. </h3>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"pattern-editing-experience-improvements\">Pattern editing experience improvements </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"pattern-editing-experience-improvements-theme-builder-site-admin-developer\"><strong>[theme builder]</strong> <strong>[site admin]</strong> <strong>[developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 shifted pattern editing to focus on content changes rather than exposing every tool, treating patterns more like single blocks. In 7.1, work focuses on UX refinements based on feedback, bug fixes, and general maintenance. For users inserting and customizing patterns, this means a more polished, predictable experience with fewer rough edges.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/75717\">WordPress 7.1: Pattern Editing Iteration</a> (#75717)</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Pattern Editing and Block Fields: Highlight selected block (<a href=\"https://github.com/WordPress/gutenberg/pull/74841\">74841</a><em>)</em></li>\n\n\n\n<li>Pattern editing: show root block identity when editing pattern sections <a href=\"https://github.com/WordPress/gutenberg/pull/79417\">#79417</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"block-width-and-layout-controls\"> Block Width and Layout Controls </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"block-width-and-layout-controls-theme-builder-site-admin-developer\"><strong>[theme builder]</strong> <strong>[site admin]</strong> <strong>[developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Refines spacing and layout tools to be more intuitive. The Columns block no longer shows a confusing &#8216;Skip&#8217; option in its layout picker, the Button block now uses the standard width control system, and spacing controls display in a more logical order when unlinked. These changes remove friction points that tripped up editors when building complex layouts.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Button: Migrate to width block support <a href=\"https://github.com/WordPress/gutenberg/pull/74242\">#74242</a> </li>\n\n\n\n<li>Columns: Remove redundant Skip option from layout picker <a href=\"https://github.com/WordPress/gutenberg/pull/78405\">#78405</a> </li>\n\n\n\n<li>Re-order spacing side controls when unlinked <a href=\"https://github.com/WordPress/gutenberg/pull/66317\">#66317</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"link-control-and-preview-enhancements\">Link Control and Preview Enhancements </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"link-control-and-preview-enhancements-theme-builder-site-admin-developer\"><strong>[theme builder]</strong> <strong>[site admin]</strong> <strong>[developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">When linking to pages or posts, the link picker now shows &#8216;Homepage&#8217; instead of just &#8216;Page&#8217; for your site&#8217;s front page, and uses the actual entity link title for previews. These small improvements make link creation feel smarter and help editors understand exactly what they&#8217;re linking to before publishing.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Use entity link title for link control preview <a href=\"https://github.com/WordPress/gutenberg/pull/77155\">#77155</a> </li>\n\n\n\n<li>Link Picker: Use Homepage badge instead of Page if Homepage <a href=\"https://github.com/WordPress/gutenberg/pull/75929\">#75929</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"additional-css-validation\">Additional CSS Validation </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"additional-css-validation-theme-builder-site-admin-developer-end-user\"><strong>[theme builder]</strong> <strong>[site admin]</strong> <strong>[developer]</strong><strong>[end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Additional CSS is now validated both on mount and via a new dimension validation endpoint for sideloaded styles. These checks prevent malformed or insecure CSS from breaking your site&#8217;s appearance or introducing security risks, giving you more confidence when adding custom styles.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Validate additional CSS on mount <a href=\"https://github.com/WordPress/gutenberg/pull/78682\">#78682</a> </li>\n\n\n\n<li>Add dimension validation to sideload endpoint <a href=\"https://github.com/WordPress/gutenberg/pull/74903\">#74903</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"block-editor-attribute-handling\">Block Editor Attribute Handling </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"block-editor-attribute-handling-theme-builder-developer\"><strong>[theme builder][developer]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The block editor now correctly targets the right block when copying direct insert block attributes, fixing edge cases where attributes would apply to the wrong block. This fix ensures that copy-paste and duplication workflows behave as expected.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Block Editor: Fix target block for copying direct insert block attributes <a href=\"https://github.com/WordPress/gutenberg/pull/77877\">#77877</a> </li>\n\n\n\n<li>Block Editor: Allow overriding `disableContentOnlyForTemplateParts` setting <a href=\"https://github.com/WordPress/gutenberg/pull/79191\">#79191</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"image-handling-improved\">Image handling improved </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"image-handling-improved-end-user-site-admin\"><strong>[end user][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A set of small fixes makes working with images more predictable. If an image points to a media library item that has since been deleted, the editor no longer treats it as a local attachment, preventing confusing errors. The crop button only appears when cropping is actually available for your user role and image type, so you&#8217;re never offered a tool that can&#8217;t work. </p>\n\n\n\n<p class=\"wp-block-paragraph\">And the featured image field now shows placeholder text making clear at a glance what goes there<em>.</em></p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Image block: Validate attachment ID exists before treating image as local <a href=\"https://github.com/WordPress/gutenberg/pull/77178\">#77178</a></li>\n\n\n\n<li>Image/Site Logo: hide crop toolbar when editMediaEntity is unavailable <a href=\"https://github.com/WordPress/gutenberg/pull/76626\">#76626</a></li>\n\n\n\n<li>Set placeholder to featured image field <a href=\"https://github.com/WordPress/gutenberg/pull/76342\">#76342</a></li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"post-template-layout-improvements\">Post Template Layout Improvements </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"post-template-layout-improvements-theme-builder-site-admin\"><strong>[theme builder][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Ensures the Post Template block&#8217;s fallback styles only apply when appropriate, preventing layout conflicts when custom minimum column widths are defined. This fix gives editors more predictable control over query loop layouts without unexpected style overrides.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Ensure Post Template fallback styles don&#8217;t apply when minimumColumnWidth is defined <a href=\"https://github.com/WordPress/gutenberg/pull/77411\">#77411</a> </li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"post-title-block-enhancements\">Post Title Block Enhancements</h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"post-title-block-enhancements-site-admin-end-user\"><strong>[site admin][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Title block gains a placeholder attribute, letting you show helpful text when no title has been entered yet. This small addition improves the editing experience for custom post types and guides content creators to fill in required fields.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Post Title: Add placeholder attribute <a href=\"https://github.com/WordPress/gutenberg/pull/76016\">#7601</a> <em>v22.7.0</em></li>\n</ul>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"block-inserter-enhancements\">Block Inserter Enhancements </h4>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"block-inserter-enhancements-site-admin-end-user\"><strong>[site admin][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Makes discovering and adding blocks easier with visual polish to the inserter interface. The search input now stays visible while scrolling through block options, and the inserter button animates to clearly signal when the panel is open. These small touches reduce friction when building pages and help editors stay oriented while exploring block options.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Block Inserter: Animate inserter button icon to signal open state. <a href=\"https://github.com/WordPress/gutenberg/pull/78306\">#78306</a> </li>\n\n\n\n<li>Make Block Inserter search input sticky while scrolling <a href=\"https://github.com/WordPress/gutenberg/pull/77698\">#77698</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"editor-enhancements\">Editor enhancements </h2>\n\n\n\n<p class=\"wp-block-paragraph\">Beyond the block improvements, the editing experience itself picks up refinements across the board. Notes mature into a fuller commenting workflow. Visual revisions gain a more detailed timeline. And your site&#8217;s brand identity gets a dedicated home in the Site Editor. </p>\n\n\n\n<p class=\"wp-block-paragraph\">A Dev Note provides a list of <a href=\"https://make.wordpress.org/core/2026/08/04/miscellaneous-block-editor-changes-in-wordpress-7-1/\">miscellaneous Editor changes</a>. </p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"notes-move-toward-a-full-commenting-workflow\">Notes move toward a full commenting workflow </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"notes-move-toward-a-full-commenting-workflow-end-user-site-admin-developer-enterprise\"><strong>[end user][site admin][developer][enterprise]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Notes, the inline editorial comments right in the editor, continue to mature, with several additions in this release that make asynchronous collaboration richer and easier to act on without leaving WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The headline feature:<a href=\"https://github.com/WordPress/gutenberg/pull/78218\"> inline notes</a>. You can now attach a note to a specific text selection rather than to a whole block. Select part of a paragraph, add a note, and the highlight stays anchored to that text as you keep editing around it. A single block can carry multiple inline notes, sorted by the order they appear, and none of the highlighting shows up in the published post. Also, blocks are no longer limited to a single conversation, either — you can start<a href=\"https://github.com/WordPress/gutenberg/pull/75147\"> multiple note threads on the same block</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversations themselves got more expressive, too. Notes now support<a href=\"https://github.com/WordPress/gutenberg/pull/78242\"> rich text formatting</a> — bold, italic, links, and code. <a href=\"https://github.com/WordPress/gutenberg/pull/79604\">@mention autocomplete</a> makes it quick to pull a colleague into a thread. Longer notes collapse behind a<a href=\"https://github.com/WordPress/gutenberg/pull/77446\"> &#8220;Show more&#8221; toggle</a>, and a<a href=\"https://github.com/WordPress/gutenberg/pull/80019\"> &#8220;Resolved&#8221; divider</a> in the sidebar separates finished discussions from open ones, so it&#8217;s easy to see what still needs attention.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking:<a href=\"https://github.com/WordPress/gutenberg/issues/76316\"> Notes iteration for WordPress 7.1</a> (#76316)</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h3 class=\"wp-block-heading\" id=\"dedicated-identity-section\">Dedicated Identity section </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"dedicated-identity-section-site-admin-theme-builder-end-user\"><strong>[site admin][theme builder][end user]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">A new <strong>Appearance &gt; Editor &gt; Identity</strong> screen consolidates your site&#8217;s logo, favicon, title, and tagline into one easy-to-find location, with inline editing so you can crop and adjust images right there. This eliminates hunting through <strong>Settings</strong> or digging into templates just to update foundational branding. For new site builders especially, it makes setting up your site&#8217;s identity quick and straightforward. Existing site owners have an intuitive place to update the data.  (<a href=\"https://github.com/WordPress/gutenberg/pull/76264\">76264</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/76116\">76116</a>)</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46349\" height=\"561\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Identity-section-in-site-editor-wp-7-1.png?resize=652%2C561&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"visual-revisions-improvement\">Visual revisions improvements </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"visual-revisions-improvements-site-admin-end-user-theme-builder\"><strong>[site admin][end user][theme builder]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Building on the visual revisions introduced in 7.0, the revisions screen gains a paginated timeline in the inspector with more detailed information about each revision, making it easier to understand what changed as you scrub through versions. (<a href=\"https://github.com/WordPress/gutenberg/pull/77333\">77333</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Changes  made via autosave are now labeled in the revisions timeline and make the autosave notice work with the visual revisions UI.(<a href=\"https://github.com/WordPress/gutenberg/pull/79950\">79950</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79947\">79947</a>)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"apply-globally-now-with-review-panel\">Apply Globally now with review panel</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The block inspector&#8217;s <strong>Apply globally</strong> action which has been a one button push of the block&#8217;s local style changes to Global Styles, has received an upgrade in WordPress 7.1 so designer can have a more granular control, on which part of the styles will make it into the global styles. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The button now opens a review modal instead, listing each modified style with its current and new value. All changes come pre-selected; deselect any you want to keep as local overrides, and only the checked styles are applied. Undo still restores the previous state in one step. What was a somewhat risky action is now a deliberate choice. You see exactly what will change across your site before committing. (<a href=\"https://github.com/WordPress/gutenberg/pull/79839\">#79839</a>)</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h2 class=\"wp-block-heading\" id=\"admin-workflow-updates\">Admin / Workflow updates</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Updates to admin and workflow tools in 7.1 improve navigation, content management, and site administration. These changes are designed to reduce friction and help you work more efficiently within the WordPress dashboard.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"organized-command-palette\">Organized command palette </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"organized-command-palette-all\"><strong>[all]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The command palette, the quick-access menu you open with keyboard shortcuts,  now groups results into recent, suggested, and matching sections, and remembers your recently-used commands across sessions. The visual design has also been refreshed to make scanning results easier. This helps you navigate WordPress faster by surfacing the tools you use most often right at the top. (<a href=\"https://github.com/WordPress/gutenberg/pull/75691\">75691</a>)</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<h3 class=\"wp-block-heading\" id=\"change-a-comment-s-parent-from-the-edit-comment-screen\">Change a comment&#8217;s parent from the Edit Comment screen </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"change-a-comment-s-parent-from-the-edit-comment-screen-end-user-site-admin-enterprise\"><strong>[end user][site admin][enterprise]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Ever needed to fix a comment that landed in the wrong thread? The Edit Comment screen now has an &#8220;In reply to&#8221; control in the Save box — hit Edit and you get a dropdown of the post&#8217;s other comments, listed by the author with a short excerpt. Top-level comments just show &#8220;None.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can&#8217;t create broken threads with it: the dropdown hides the comment itself and anything nested under it, and the server double-checks on save — the new parent has to be on the same post and can&#8217;t be the comment or one of its own replies (anything invalid gets bounced with a WP_Error). If the current parent wouldn&#8217;t normally show up in the list (a pingback, say), it&#8217;s kept in there as the selected option, so saving without touching the field changes nothing. Works without JavaScript too, and there are tests covering the validation. (<a href=\"https://core.trac.wordpress.org/ticket/65570\">65570</a>)</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-46353\" height=\"485\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Change-comments-parent.png?resize=652%2C485&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"see-an-excerpt-of-posts-without-titles\">See an excerpt of posts without titles </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"see-an-excerpt-of-posts-without-titles-end-user-site-admin\"><strong>[end user][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">If you publish posts without titles for instance for quick status-style updates, the Posts list has been pretty useless for telling them apart: just a column of identical &#8220;(no title)&#8221; links. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, in Compact view, untitled posts show the first 15 words of the excerpt right after &#8220;(no title)&#8221;, so you can actually see what each post is at a glance. </p>\n\n\n\n<p class=\"wp-block-paragraph\">The checkbox&#8217;s screen-reader label gets the same text, password-protected posts keep their content hidden, and the Extended view is unchanged since it already shows excerpts.(<a href=\"https://core.trac.wordpress.org/ticket/65022\">65022</a>).</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46355\" height=\"348\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/no-title-posts-in-list.png?resize=652%2C348&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"media-library-infinite-scrolling-is-back-on-by-default-with-a-per-user-opt-out\">Media Library: infinite scrolling is back on by default, with a per-user opt-out </h3>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"media-library-infinite-scrolling-is-back-on-by-default-with-a-per-user-opt-out-end-user-site-admin\"><strong>[end user][site admin]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">The Media Library grid now uses infinite scrolling by default, so attachments load continuously as you scroll instead of behind a &#8220;Load more&#8221; button. For anyone who prefers the previous behavior, there&#8217;s a new personal option: a &#8220;Disable infinite scrolling in the Media Library grid view&#8221; checkbox on the profile screen. The setting only appears for users who can actually upload files, since others never see the attachment grid.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For developers, the existing media_library_infinite_scrolling filter still works and now takes top precedence: a hooked filter always wins, followed by the user&#8217;s profile preference, with infinite scrolling enabled when neither is set. Note the filter&#8217;s default value has flipped from false to true as of 7.1.0, so any code relying on the old default should be reviewed. The change ships with unit tests covering the new user option and the full precedence chain (<a href=\"https://core.trac.wordpress.org/ticket/65564\">65564</a>).</p>\n\n\n\n<p class=\"wp-block-paragraph\">Read the Dev note: <a href=\"https://make.wordpress.org/core/2026/07/23/media-library-infinite-scrolling-is-now-enabled-by-default-with-a-per-user-opt-out/\">Media Library infinite scrolling is now enabled by default, with a per-user opt-out</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"hosts-can-now-tune-speculative-loading-defaults\">Hosts can now tune speculative loading defaults</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Since WordPress 6.8, <a href=\"https://make.wordpress.org/core/2025/03/06/speculative-loading-in-6-8/\">speculative loading</a> lets browsers prefetch or prerender pages a visitor is likely to open next, making navigation feel near-instant. WordPress ships with deliberately cautious defaults — and until now, changing them required an mu-plugin. With WordPress 7.1, hosting providers and site owners can adjust the default mode and eagerness through environment variables or wp-config.php constants. A well-configured host with page and object caching in place can opt its sites into more aggressive speculation and pass the speed gains on to visitors. The real-world data hosts gather this way will also help inform whether core changes the defaults for everyone in a future release. The technical details are available in the core ticket (<a href=\"https://core.trac.wordpress.org/ticket/65624\">#65624</a>).</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"developer-goodies\">Developer Goodies </h2>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\" id=\"developer-goodies-developer-theme-builder-plugin-author-enterprise\"><strong>[developer][theme builder][plugin author][enterprise]</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 provides developers with expanded APIs, theme.json capabilities, and system improvements. These tools offer greater control over site design, block behavior, and system integrations.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"post-editor-iframe-now-always-on\">Post editor iframe now always on</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Other editors in WordPress—the site editor, the template editor, and block, template, and device previews—have been unconditionally iframed for a long time, going back to the template editor&#8217;s introduction in 5.8. The post editor was the holdout: starting in 7.0, whether it ran isolated depended on the blocks actually present in a given post, so a post using only Block API v3+ blocks got the isolated canvas, while a post containing even one older block (API v1 or v2) dropped out of it entirely. That meant the same site, even the same author, could see the editor behave differently from post to post. <a href=\"https://github.com/WordPress/gutenberg/pull/75187\">In 7.1, that condition is removed</a>: every post editor is always iframed, regardless of theme type or block API version.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For most people writing and editing content, this is good news—no more switching behavior depending on which blocks happen to be inserted. Block developers have a bit of homework, though: the iframe has its own document and window, separate from the admin page where editor scripts run, so any code that reaches for the global document or window to touch the canvas will now be looking at the wrong place. The usual fix is to get the canvas&#8217;s document from an element inside it (via ownerDocument and its defaultView) rather than the global object, and to use useRefEffect for attaching and cleaning up canvas event listeners.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Read the <a href=\"https://make.wordpress.org/core/2026/08/03/iframed-editor-changes-in-wordpress-7-1/\">dev note on the 7.1 changes</a> and the <a href=\"https://developer.wordpress.org/block-editor/reference-guides/block-api/block-api-versions/block-migration-for-iframe-editor-compatibility/\">block migration guide</a> for more details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ryan Welcher published a guide and a demo plugin. <a href=\"https://gutenbergtimes.com/the-post-editor-is-going-full-iframe-what-block-developers-need-to-know-before-wordpress-7-1/\">The post editor is going full iframe: what block developers need to know before WordPress 7.1</a> with code examples and instructions how to fix things if necessary. </p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"abilities-api-opens-up-its-execution-pipeline\">Abilities API opens up its execution pipeline</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Abilities API arrived in WordPress 6.9, and 7.1 gives extenders real control over it. Four new lifecycle filters let plugins step into ability execution — short-circuit it entirely (think caching, rate limiting, or maintenance mode), transform input, layer on extra authorization rules, or reshape and even recover results. Two more filters add custom input and output validation on top of JSON Schema, and a new <code>wp_ability_invoked</code> action fires on every invocation — even failed ones — handy for logging and auditing. The core info abilities return more user details, input over the REST API now arrives properly typed, and <code>wp_prepare_json_schema_for_client()</code> strips PHP callbacks and WordPress-only conventions before a schema goes out to REST clients, MCP integrations, or AI tools. </p>\n\n\n\n<p class=\"wp-block-paragraph\">A new <code>public</code> metadata flag rounds it out: declare once that an ability is meant for external clients, and REST, MCP adapters, and future integrations use it as their default — with channel-specific flags still able to override, and permission callbacks still guarding actual execution.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Finding the right abilities gets easier too: <code>wp_get_abilities()</code> now accepts arguments to filter registered abilities by category, namespace, or meta — with the same filtering available on the REST endpoint.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Details and code examples in these dev notes:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://make.wordpress.org/core/2026/07/29/new-execution-lifecycle-filters-for-the-abilities-api-in-wordpress-7-1/\">New execution lifecycle filters for the Abilities API</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/31/abilities-api-improvements-in-wordpress-7-1/\">Abilities API improvements</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/07/31/json-schema-preparation-for-client-compatibility-in-wordpress-7-1/\">JSON Schema preparation for client compatibility</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/04/a-unified-public-exposure-flag-for-abilities-in-wordpress-7-1/\">A unified public exposure flag for Abilities </a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/2026/08/05/filtering-registered-abilities-with-wp_get_abilities-in-wordpress-7-1/\">Filtering registered abilities with wp_get_abilities() in WordPress 7.1</a></li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"global-styles-and-theme-json\">Global Styles and theme.json </h3>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"text-shadow-support-for-theme-json\">Text Shadow support for theme.json</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Theme authors can now define <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">text shadows directly in theme.json</a> via a new textShadow property under styles.typography. It works everywhere you&#8217;d expect: at the root level, per-block (say, a shadow on paragraphs only), via style variations, and on elements — including pseudo-selectors like a link&#8217;s :hover state. Any valid CSS text-shadow value is accepted, including stacked multi-shadow definitions. Block placeholder text in the editor resets the shadow so it stays readable regardless of what the theme sets.</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">\"styles\": {\n		\"typography\": {\n			\"textShadow\": \"1px 1px 2px red, 0 0 1em blue, 0 0 0.2em blue;\"\n		},\n		\"blocks\": {\n			\"core/paragraph\": {\n				\"typography\": {\n					\"textShadow\": \"1px 1px 2px red, 0 0 1em red, 0 0 0.2em red;\"\n				}\n			}\n		},\n		\"elements\": {\n			\"link\": {\n				\":hover\": {\n					\"typography\": {\n						\"textShadow\": \"none\"\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #2AA198;\">&quot;styles&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;typography&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;textShadow&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;1px 1px 2px red, 0 0 1em blue, 0 0 0.2em blue;&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		},</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;blocks&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;core/paragraph&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				</span><span style=\"color: #859900;\">&quot;typography&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">					</span><span style=\"color: #859900;\">&quot;textShadow&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;1px 1px 2px red, 0 0 1em red, 0 0 0.2em red;&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		},</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;elements&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;link&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				</span><span style=\"color: #859900;\">&quot;:hover&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">					</span><span style=\"color: #859900;\">&quot;typography&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">						</span><span style=\"color: #859900;\">&quot;textShadow&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;none&quot;</span></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">More details in the Dev Note: <a href=\"https://make.wordpress.org/core/2026/07/23/text-shadow-support-in-global-styles/\">Text Shadow Support in Global Styles</a></p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"text-align-block-support-migration\">Text-Align Block Support Migration</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Nine more core blocks (Post Date, Post Excerpt, Post Navigation Link, Post Title, Query Title, Site Tagline, Site Title, Pullquote and Term Name) now use WordPress&#8217;s standardized <a href=\"https://developer.wordpress.org/block-editor/reference-guides/block-api/block-supports/#align\">text-align system</a>. As part of a larger <a href=\"https://github.com/WordPress/gutenberg/issues/60763\">migration effort</a> this update ensures consistent alignment controls across the editor and makes these blocks behave predictably alongside newer blocks. </p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress EndUser are not supposed to see any changes and existing blocks continue to work. Theme designers are now able to style any of these blocks text align via theme.json property. The code example shows how to set the center as the site-wide TextAlign default. And `&#8221;textAlign&#8221;: false` disables the feature for this block </p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">{\n	\"version\": 3,\n	\"styles\": {\n		\"blocks\": {\n			\"core/pullquote\": {\n				\"typography\": {\n					\"textAlign\": \"center\"\n				}\n			}\n		}\n	}\n}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #657B83;\">{</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	</span><span style=\"color: #859900;\">&quot;version&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #D33682;\">3</span><span style=\"color: #657B83;\">,</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	</span><span style=\"color: #859900;\">&quot;styles&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		</span><span style=\"color: #859900;\">&quot;blocks&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			</span><span style=\"color: #859900;\">&quot;core/pullquote&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				</span><span style=\"color: #859900;\">&quot;typography&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">					</span><span style=\"color: #859900;\">&quot;textAlign&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #2AA198;\">&quot;center&quot;</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">				}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">			}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">		}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">	}</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">}</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"block-visibility\">Block Visibility</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Adds <code>settings.blockVisibility.allowEditing</code> to theme.json, allowing themes to disable the block visibility feature entirely.</p>\n\n\n\n<div class=\"wp-block-kevinbatdorf-code-block-pro\"><span style=\"display: flex; padding: 10px 0px 0 16px; font-size: 0.8em; width: 100%; text-align: left; background-color: #FDF6E3; font-style: italic; color: #657B83;\"><span>JSON</span></span><span class=\"code-block-pro-copy-button\" style=\"color: #657B83; display: none;\" tabindex=\"0\"><pre class=\"code-block-pro-copy-button-pre\"><textarea class=\"code-block-pro-copy-button-textarea\" readonly=\"readonly\" tabindex=\"-1\">{\n  \"settings\": {\n    \"blockVisibility\": {\n      \"allowEditing\": false\n    }\n  }\n}\n</textarea></pre><svg fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path class=\"with-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><path class=\"without-check\" d=\"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path></svg></span><pre class=\"shiki solarized-light\" style=\"background-color: #FDF6E3;\" tabindex=\"0\"><code><span class=\"line\"><span style=\"color: #657B83;\">{</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">  </span><span style=\"color: #859900;\">&quot;settings&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    </span><span style=\"color: #859900;\">&quot;blockVisibility&quot;</span><span style=\"color: #657B83;\">: {</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">      </span><span style=\"color: #859900;\">&quot;allowEditing&quot;</span><span style=\"color: #657B83;\">: </span><span style=\"color: #B58900;\">false</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">    }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">  }</span></span>\n<span class=\"line\"><span style=\"color: #657B83;\">}</span></span>\n<span class=\"line\"></span></code></pre></div>\n\n\n\n<p class=\"wp-block-paragraph\">When set to false, the toolbar button and block options menu item are hidden. In this regard, it makes this block support consistent with color, typography etc.</p>\n\n\n\n<p class=\"wp-block-paragraph\">blockVisibility.allowEditing follows the layout flag. The reason is the two-fold nature of blockVisibility at the block supports level: a bool means don&#8217;t render the block at all, but viewport settings allow users to control visibility per viewport.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The object shape also leaves the door open to extending block visibility to triggers, not only blockVisibility.viewports but others like post type or whatever. (<a href=\"https://github.com/WordPress/gutenberg/pull/76559\">76559</a>).</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"block-supports-css-variables-by-feature-selector\">Block Supports: CSS variables by feature selector</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Block Supports<a href=\"https://github.com/WordPress/gutenberg/pull/75226\"> now generates CSS custom properties</a> based on a block&#8217;s feature-specific selectors, not just its root selector. Some blocks—the Button block is the example given—define their outer wrapper and an inner styling target as different elements, and previously there was no way to output a preset variable (like a dimension size) onto that inner element specifically. Theme and plugin authors building design systems now have a way to target the right element per feature, without needing custom CSS to work around the mismatch.</p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"a-minimum-width-option-for-block-dimensions\">A minimum-width option for block dimensions</h4>\n\n\n\n<p class=\"wp-block-paragraph\">Blocks already supported height, minHeight, and width. What was missing was a way to stop something from shrinking too far—so a layout element wouldn&#8217;t collapse into an unusable sliver on a narrow screen. <a href=\"https://github.com/WordPress/gutenberg/pull/76949\">Minimum-width closes that gap</a>, mirroring how minimum-height already works.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s opt-in at the block level: the control stays hidden in the inspector until a block explicitly enables it, though it shows by default in the global styles panel. Theme-defined dimension presets carry over automatically, so existing spacing scales just work. The Group block is the first to adopt it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You’ll find more details in the Dev Note <a href=\"https://make.wordpress.org/core/2026/07/26/new-block-support-in-wordpress-7-1-minimum-width/\">New Block Support in WordPress 7.1: Minimum Width</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"design-system-theme-provider\">Design System Theme Provider </h3>\n\n\n\n<p class=\"wp-block-paragraph\">The first version of the design system’s theme component arrives in WordPress 7.1. It consists of standardized CSS custom properties that follow the W3C Design Tokens specification. You probably won&#8217;t spot the difference right away — the default theme was deliberately built to match existing styles — but this is the machinery that will power the admin color scheme in the Site Editor. You can read more details on the future direction in the <a href=\"https://make.wordpress.org/core/2026/07/07/merge-proposal-design-system-theming/\">Merge Proposal: Design System Theming</a> </p>\n\n\n\n<p class=\"wp-block-paragraph\">The Dev Note has more: <a href=\"https://make.wordpress.org/core/2026/07/31/design-system-theming-in-wordpress-7-1/\">Design System Theming in WordPress 7.1</a></p>\n\n\n\n<h4 class=\"wp-block-heading\" id=\"admin-color-schemes-in-site-editor\">Admin color schemes in Site Editor</h4>\n\n\n\n<p class=\"wp-block-paragraph\">The Site Editor&#8217;s sidebar and interface now respect your chosen WordPress admin color scheme instead of always showing a dark background. This brings visual consistency across the post editor, Site Editor, and admin dashboard. If you&#8217;ve personalized WordPress with a color scheme you prefer, that choice now carries through everywhere you work. <a href=\"https://github.com/WordPress/gutenberg/pull/78397\">78397</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"mix-static-html-with-editable-blocks\">Mix static HTML with editable blocks</h3>\n\n\n\n<p class=\"wp-block-paragraph\">A new innerContent block support lets a block keep static HTML fragments interleaved with editable inner blocks as the canonical source of its own markup. In practice, this means a hand-written HTML structure can have just a piece of it—a paragraph, an image—editable in place, while the rest stays fixed and can&#8217;t be moved, removed, or rearranged.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The Custom HTML block is the first adopter: pasting HTML with a block comment delimiter embedded in it (for example, a &lt;!&#8211; wp:paragraph &#8211;&gt; block inside a larger static &lt;div&gt;) makes that inner piece editable directly in the canvas, while the surrounding markup remains locked in place. It&#8217;s a narrow, developer-facing capability for now—the HTML block is the only place it&#8217;s wired up—but it opens the door for custom blocks to offer the same kind of &#8220;mostly static, partly editable&#8221; experience going forward. (<a href=\"https://github.com/WordPress/gutenberg/pull/79115\">79115</a>)</p>\n\n\n\n<p class=\"wp-block-paragraph\">The dev note can be found on the Make Core Blog: <a href=\"https://make.wordpress.org/core/2026/07/23/editable-blocks-inside-the-custom-html-block/\">Editable blocks inside the Custom HTML block</a> </p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"block-bindings-for-list-items-and-inner-blocks\">Block Bindings for list-items and inner blocks</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The List Item block has gained Block Bindings support. A List Item&#8217;s content can now be connected to a data source—a custom field, a pattern override, or another registered source—so individual entries in a list can be populated dynamically rather than typed in by hand. The change <a href=\"https://github.com/WordPress/gutenberg/pull/78947\">registers content as a bindable attribute</a> for core/list-item.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://github.com/WordPress/gutenberg/pull/79346\">A related fix rounds out the feature</a>: previously, if a bound List Item also contained a nested sub-list, that nested list was dropped when the binding was rendered. Now a List Item can carry a bound value and a nested list beneath it at the same time. In practice, this means multi-level lists—say, a team member&#8217;s name pulled from a custom field, with a nested list of their current projects underneath—can now be fully dynamic without losing structure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/77199\">Block Bindings in WordPress 7.1</a> (#77199)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"connectors-authentication-improvements\">Connectors authentication improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The Connectors framework, which manages WordPress&#8217;s connections to external services like AI providers, now supports username and application password authentication as an alternative to API keys. A <a href=\"https://github.com/WordPress/gutenberg/pull/79403\">merged pull request</a> adds a default connector form for this method, along with the underlying authentication type, mirroring the equivalent API already available in WordPress Core.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The change also handles the practical details: saved passwords are masked in the UI and over REST, credentials can be set via constants or environment variables instead of the database, and a <a href=\"https://github.com/WordPress/wordpress-develop/pull/12264\">companion Core patch</a> keeps the two in sync. For connectors that require an account login rather than a bare API key, this removes the need for a custom settings screen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This lands alongside a broader <a href=\"https://github.com/WordPress/gutenberg/issues/78647\">open proposal for a PHP-side field registry</a> that would let connector authors declare arbitrary settings—model choice, temperature, custom URLs, and more—the way register_setting() works elsewhere in WordPress. That registry isn&#8217;t built yet; the application password work is a first, concrete step (new auth method, not new field types), addressing one of the two gaps the proposal identified rather than the full vision.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tracking: <a href=\"https://github.com/WordPress/gutenberg/issues/78647\">Connectors: proposal for a PHP-side field registry for connector configuration</a> (#78647)</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"blocks-package-stabilizes-two-experimental-functions\">Blocks package stabilizes two experimental functions</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The <a href=\"https://github.com/WordPress/gutenberg/pull/79928\">Blocks package stabilizes</a> cloneSanitizedBlock and sanitizeBlockAttributes, dropping their __experimental prefixes now that the functions have been stable in practice for some time. The old __experimental-prefixed names still work but will log a deprecation notice, so plugins or themes importing them directly should switch to the new names.</p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"post-author-notifications-the-filter-decides\">Post author notifications: the filter decides</h3>\n\n\n\n<p class=\"wp-block-paragraph\">The <code>notify_post_author</code> filter <a href=\"https://make.wordpress.org/core/2026/08/05/the-notify_post_author-filter-now-has-the-final-say-on-post-author-notifications/\">now has the final say</a>: approval status is checked before the filter runs, so it receives an accurate default and returning <code>true</code> reliably sends a notification — even for unapproved comments. Sites forcing notifications with <code>__return_true</code> should switch to a callback that checks approval, or they&#8217;ll start receiving emails for spam and moderated comments. (<a href=\"https://core.trac.wordpress.org/ticket/64217\">#64217</a>). More Details can be found in the Dev note <a href=\"https://make.wordpress.org/core/2026/08/05/the-notify_post_author-filter-now-has-the-final-say-on-post-author-notifications/\">The notify_post_author filter now has the final say on post author notifications</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"accessible-tooltips-and-toggle-tips-api\">Accessible tooltips and toggle tips API</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress adds a core mechanism for accessible tooltips (<a href=\"https://core.trac.wordpress.org/ticket/51006\">51006</a>), offering an alternative to the title attribute, which is not available to keyboard and touch users. Two new functions cover different use cases: wp_get_tooltip() exposes an accessible name when a control has focus or hover, such as for icon-only buttons, and wp_get_toggletip() implements a popover disclosure with extended help information that stays open until dismissed. Both generate accessible markup that avoids excess verbosity for screen readers and follows best practices for voice command users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The first toggle tip in core explains the &#8220;Remember Me&#8221; option on the login screen (<a href=\"https://core.trac.wordpress.org/ticket/55343\">55343</a>). Plugin developers can use the functions for their own settings screens and metaboxes. (<a href=\"https://core.trac.wordpress.org/changeset/62741\">62741</a>). </p>\n\n\n\n<p class=\"wp-block-paragraph\">Dev Note is now available with the details: <a href=\"https://make.wordpress.org/core/2026/08/03/introducing-name-and-informational-tool-tips-in-wordpress-7-1/\">Introducing name and informational tool tips in WordPress 7.1</a></p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-46367\" height=\"434\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/07/Tooltip-API-wp-7-1-edited.png?resize=652%2C434&#038;ssl=1\" width=\"652\" /></figure>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"filtering-site-editor-screens\">Filtering Site Editor screens</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Plugin developers can now configure the Site Editor&#8217;s Pages, Templates, Template Parts, and Patterns screens through four new PHP filters — one per screen. Each filter adjusts the DataViews and DataForm components powering these screens: the default view (layout, sort order, visible fields), the layouts available to users, the preconfigured views in the sidebar such as &#8220;All&#8221; or &#8220;Drafts,&#8221; and the fields shown in the Quick Edit form. </p>\n\n\n\n<p class=\"wp-block-paragraph\">This creates a single place of configuration per entity, with more screens — including the editor inspector — planned to draw from the same source in future releases (<a href=\"https://github.com/WordPress/gutenberg/issues/76544\">#76544</a>). Code examples are in the Dev Note: <a href=\"https://make.wordpress.org/core/2026/07/31/filtering-site-editor-screens-in-wordpress-7-1/\">Filtering Site Editor Screens in WordPress 7.1.</a></p>\n\n\n\n<h3 class=\"wp-block-heading\" id=\"post-list-table-markup-changed-for-accessibility\">Post list table markup changed for accessibility</h3>\n\n\n\n<p class=\"wp-block-paragraph\">An eleven-year-old accessibility ticket is resolved: in post list tables, the row header (<code>th scope=\"row\"</code>) moves from the checkbox column to the title column, so screen readers identify each row by the post&#8217;s name rather than by a checkbox that may not even be present. (<a href=\"https://core.trac.wordpress.org/ticket/32892\">#32892</a>). </p>\n\n\n\n<p class=\"wp-block-paragraph\">Extenders should check their CSS and JavaScript: selectors like <code>th.check-column</code> or ones expecting the title and row actions inside a <code>td</code> need updating. The dev note <a href=\"https://make.wordpress.org/core/2026/08/03/post-list-tables-row-headers-changed/\">Post list tables row headers changed</a> lists the affected patterns, and keeping both <code>td</code> and <code>th</code> selectors preserves compatibility with older WordPress versions. </p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">A list of <a href=\"https://make.wordpress.org/core/tag/dev-notes+7-1/\">all the dev notes can be reviewed from the Make Core blog</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 30 Jul 2026 13:51:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:79:\"Open Channels FM: Why Open Source Projects Need a License Before They Need Code\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2556844\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"https://openchannels.fm/why-open-source-projects-need-a-license-before-they-need-code/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:212:\"Open source fosters creativity but involves complex issues like licensing and ownership, especially in hackathons. Proper planning with appropriate licenses upfront is crucial for project success and flexibility.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 30 Jul 2026 13:35:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:28;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"Open Channels FM: Signal – Issue 18\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2557496\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://openchannels.fm/signal-issue-18/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:188:\"Talk about personal journeys in web development, the complexities of fame, and the benefits of open source, emphasizing enriching content options for listeners beyond traditional podcasts.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 29 Jul 2026 17:54:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:29;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"WordPress.org blog: WordPress 7.1 Beta 4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=21243\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/07/wordpress-7-1-beta-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:6493:\"<p class=\"wp-block-paragraph\">WordPress 7.1 Beta 4 is ready for download and testing! </p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta release is intended for testing and development</strong> only. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, use a test environment or local site to explore the new features.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to Test WordPress 7.1 Beta 4</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can test WordPress 7.1 Beta 4 in any of the following ways:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>WordPress Beta Tester Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noreferrer noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. Select the “Bleeding edge” channel and “Beta/RC Only” stream.</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.1-beta4.zip\">Beta 4 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line (WP-CLI)</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\" rel=\"noreferrer noopener\" target=\"_blank\">WP-CLI</a> command: <br /><code>wp core update --version=7.1-beta4</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">7.1 Beta 4 WordPress Playground instance</a> to test the software directly in your browser. No setup required-just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.1 is <strong>August 19, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/07/03/wordpress-7-1-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Find out what’s new in WordPress 7.1</strong>: Read the <a href=\"https://wordpress.org/news/2026/07/wordpress-7-1-beta-1/\">Beta 1 announcement</a> for details and highlights.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How important is your testing?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is a critical part of developing any software, and it’s a meaningful way for anyone to contribute – whether or not you have experience. <a href=\"https://make.wordpress.org/test/2026/07/15/help-test-wordpress-7-1/\">Details on what to test in WordPress 7.1 are available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please share it in the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">Alpha/Beta area</a> of the support forums. If you are comfortable submitting a reproducible bug report, you can do so <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. You can also check your issue against this list of <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">known bugs</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general and how to get started? Follow along with the<a href=\"https://make.wordpress.org/test/\"> testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What’s in WordPress 7.1 Beta 4?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 Beta 4 contains more than <strong>114</strong> updates and fixes since the Beta 3 release, including <strong>51</strong> in the Editor and <strong>63</strong> in Core. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Each beta cycle focuses on bug fixes, and more are on the way with your help through testing. You can browse the technical details for all issues addressed since Beta 3 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.1?since=2026-07-22&amp;until=2026-07-29\" rel=\"noopener\" target=\"_blank\">GitHub commits for 7.1</a>  since July 22, 2026</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=07%2F22%2F2026..07%2F29%2F2026&amp;milestone=7.1&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\" rel=\"noopener\" target=\"_blank\">Closed Trac tickets for 7.1</a> since July 22, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Beta 4 brings a round of fixes that make the editor smoother to work with. Notes now stay reliably tied to the passage they refer to, and tagged people are displayed cleanly and clearly.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 4 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testers lend their eyes,<br />edge cases hide in plain sight—<br />Patch, rebuild, refine.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/krupajnanda/\"><span class=\"mentions-prefix\">@</span>krupajnanda</a> for preparing this post and <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/wildworks/\"><span class=\"mentions-prefix\">@</span>wildworks</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/amykamala/\"><span class=\"mentions-prefix\">@</span>amykamala</a> for proofreading and review.</em></p>\n\n\n\n<div class=\"wp-block-group is-layout-constrained wp-block-group-is-layout-constrained\">\n<figure class=\"wp-block-image size-large has-custom-border\"><a href=\"https://us.wordcamp.org/2026/\" rel=\" noopener\" target=\"_blank\"><img alt=\"WordCamp US: Powered by WordPress, Driven by Community, August 16-19, 2026\" class=\"wp-image-20859\" height=\"321\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/06/wcus-2026-teaser.png?resize=1024%2C321&#038;ssl=1\" width=\"1024\" /></a><figcaption class=\"wp-element-caption\">Join us for the launch of WordPress 7.1 at <a href=\"https://us.wordcamp.org/2026/\">WordCamp US 2026</a>, August 16–19.</figcaption></figure>\n</div>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 29 Jul 2026 15:30:58 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"Benjamin Zekavica\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:30;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"WPTavern: #227 – Maciek Palmowski on Testing Secure WordPress Hosting: Does the Marketing Match Reality?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=206791\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:118:\"https://wptavern.com/podcast/227-maciek-palmowski-on-testing-secure-wordpress-hosting-does-the-marketing-match-reality\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:50326:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, testing secure WordPress hosting, does the marketing match the reality?</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Maciek Palmowski. Maciek is based in Poland and works at Patchstack, one of the companies in the WordPress ecosystem dedicated specifically to security. At Patchstack, Maciek collaborates with other security professionals on industry reports, bug bounty programmes, and solutions for agencies, product owners, and hosting companies aiming to secure their client sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I met up with Maciek at WordCamp Europe, and we discussed his presentation there. It examined the claims of secure hosting made by many WordPress hosting providers. He describes how Patchstack set out to test these claims with real world penetration testing, using 30 known plugin vulnerabilities across multiple hosts. Employing standardised methodologies and validating their results independently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The findings are sobering. The majority of WordPress specific attacks still get through, and there&#8217;s a significant gap between the marketing hype and real protection.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation starts with Maciek&#8217;s background, and how his journey in the WordPress security space led to a focus on the promises made by hosts.</p>\n\n\n\n<p class=\"wp-block-paragraph\">From there, the discussion gets into the research approach, the selection of well-known vulnerabilities, consistent testing across different hosting environments, and the surprising result that even hosts with identical security tooling produce drastically different outcomes, showing it&#8217;s not just about the tools you use, but how you use them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the Swiss cheese model of security, every layer will have holes, so you need multiple overlapping defences, and honest communication from hosts about their limitations.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also explored whether an industry-wide standard, or badge, for secure hosting is feasible or even desirable, given how easy it is for strong marketing claims to outpace reality.</p>\n\n\n\n<p class=\"wp-block-paragraph\">AI also enters the conversation, increasing both the speed and sophistication of attacks, and making patching, and processes, even more important, especially as the volume of vulnerabilities continues to rise and the time to exploitation drops.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in understanding what secure hosting really means, how to ask intelligent questions of providers, and the realities of WordPress security in 2026, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to find out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Maciek Palmowski.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:56] <strong>Maciek Palmowski:</strong> I am joined on the podcast by Maciek Palmowski. Hello Maciek.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Perfect. You did great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:01] <strong>Nathan Wrigley:</strong> For some reason, your name has got into my head. A lot of the people that I interview, I struggle with their name, and I continue to struggle, but for some reason, I established many years ago that was how to say your name. And I think I&#8217;ve done it correctly ever since then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:16] <strong>Maciek Palmowski:</strong> Yes you did. You&#8217;re almost having the typical Polish accent, so you&#8217;re doing great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:21] <strong>Nathan Wrigley:</strong> So we are at WordCamp Europe, which is in Krakow, or Krakow, I don&#8217;t know how.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:26] <strong>Maciek Palmowski:</strong> Krakow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:27] <strong>Nathan Wrigley:</strong> Thank you, that was good. And the reason Maciek is correcting my pronunciation is because Maciek is actually from Poland, which I suppose means that this is a bit of a, well, it&#8217;s like a home game to you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:37] <strong>Maciek Palmowski:</strong> In a way so, but it&#8217;s also like a bit of a shame because I do like travelling when WordCamp Europe&#8217;s are happening. And, you know, just hopping on the train and going to Krakow, it was like a, I mean it&#8217;s cool because, yeah, the venue&#8217;s amazing, everything is great, but still I&#8217;m staying home, so yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:53] <strong>Nathan Wrigley:</strong> Yeah, mixed feelings. So Maciek has done, or is going to do a presentation at WordCamp EU. Have you done it yet?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:02] <strong>Maciek Palmowski:</strong> I will do it tomorrow.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:04] <strong>Nathan Wrigley:</strong> Okay. And are you all set, are you one of these like really prepared people that has all the slides done, or are you last minute?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:11] <strong>Maciek Palmowski:</strong> Everything is ready. I already did one version of it at the Checkout Summit in Palermo, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:17] <strong>Nathan Wrigley:</strong> Oh I see. So you&#8217;ve had a sort of dry run of elsewhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:19] <strong>Maciek Palmowski:</strong> Of course.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:20] <strong>Nathan Wrigley:</strong> Excellent. So the presentation, which is going to be the focus of today&#8217;s conversation, is called Testing the promise, does secure hosting deliver? And I may as well read the blurb because it was a reasonably short one.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it says, secure hosting, in quotes, is everywhere in WordPress. What does it actually protect against? We put this claim to the test with real penetration testing. 30 known vulnerabilities, multiple hosting providers, standardised methodology, validated by independent observers. The findings reveal a critical gap between marketing and reality. WordPress specific attacks succeed most of the time. That&#8217;s quite an alarming sentence. This talk shares the complete results and explains why generic security fails.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, we&#8217;ll get into that in a moment. But as with all people, when I&#8217;m talking to them about security, I guess it&#8217;s good to establish who you are, and what your credentials are and what you&#8217;ve done, and how is it that you get to talk about security with authority. So over to you really, a little moment to give us your bio and tell us about you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:20] <strong>Maciek Palmowski:</strong> Okay. So I work at Patchstack, and Patchstack is one of those few companies in WordPress space that are doing a lot in terms of security. We are constantly running this bug bounty for the whole ecosystem. We have quite a few solutions for both clients and hosting companies, and I work there right now. My role is, if I remember, the Growth Team Engineer, something like this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But yeah, I do spend a lot of time working with other security people. So when we are working on all the reports, when we are checking the data, I&#8217;m also part of those teams that are working on it. So yeah, I think I know a thing or two about what is happening behind the scenes when it comes to WordPress security.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:02] <strong>Nathan Wrigley:</strong> Yeah, thank you. Always good to get that established though, right at the outset.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Patchstack is a company which is not a host though, I suppose that&#8217;s important to mention at the beginning. It&#8217;s a company which is in the security space, very much in the WordPress space, but perhaps more broad than WordPress, I&#8217;m not sure. But not a hosting company.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But obviously your presentation focuses its aim on hosting, I guess because that&#8217;s one of the places where the claim about security is most often made. You know, you&#8217;ll go to a, the landing page of hosting Company X, and you&#8217;ll see somewhere fairly near the top, secure hosting, or something along those lines. And you&#8217;ve decided to examine that in fine detail and look at these 30 vulnerabilities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I guess really just tell us about this test and what it is that you decided to do and some of the items that came out of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:50] <strong>Maciek Palmowski:</strong> Okay, so maybe let&#8217;s start with how it even started, right? Because there was a trigger. At some point we published one report about the state of WordPress security. We tweeted about this. We got the response from none other than Matt Mullenweg, who kind of asked a very interesting question, but isn&#8217;t hosting companies taking care of this already?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And this was, kind of at this moment when we were, we thought that we know the answer that, no they aren&#8217;t. But to be honest, we didn&#8217;t have any broader proof about this.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We knew how it&#8217;s working at some hosting companies, but we could say that it was more of an anecdotal evidence that we had. So this was kind of the trigger that made us, okay, let&#8217;s check this. But not with one partner or two partners, but with more hosting companies.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we did this research twice. First we just did kind of a beta run because we weren&#8217;t sure about the result and, is it even a good idea to go deeper inside of it? And during our first run, we were already very surprised because like the methodology was very simple. We just installed vulnerable plugins and we checked if we would be able to use the vulnerability. Because if the hosting is claiming that, we got your back, we are making your website secure, we have this and that, this means that they should protect against it. So it was as simple as that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And when we were doing our first test, we were quite surprised because we saw, if I remember, that 80% of the attacks went through. 80% of the attacks. So our first reaction was, okay, we are doing something wrong. Okay, this was only few hosting companies, less plugins, but still the result were so surprising for us because we thought that, okay, that the problem exists, but it&#8217;s not that big of a problem. But it was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that&#8217;s why we did the second test. And this is about which the, my talk will be mostly when we tested more hosting companies, more plugins. And we saw that the problem still exists.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Of course it was, in some cases 70 few percent. So still, it&#8217;s a huge problem, especially if we are talking about some companies that are literally saying, you don&#8217;t have to install anything additional when it comes to security on your website. We got your back. They don&#8217;t. We found a lot of interesting things, but still the problem exists.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:21] <strong>Nathan Wrigley:</strong> So just deep diving into that a little bit, when tests like this are done, there&#8217;s obviously, the claim might be levelled, you know, obviously Patchstack would, this kind of maybe benefits Patchstack, if you know what I mean.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So let&#8217;s just sort of clear up what the test involved. So presumably the plugins that you chose are ones where it&#8217;s publicly known that there&#8217;s a vulnerability in this component or this particular file or what have you. So is that the case? This is stuff that, longstanding understanding that there&#8217;s a problem here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:51] <strong>Maciek Palmowski:</strong> Yes. We only use the plugins that we had all the proof of concepts. So we know how have the vulnerability happened, what was the attack vector? They were all reported through our bug bounty programme, because that&#8217;s why we had the proof of concept. Yeah, and that&#8217;s it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It was, like I said, it was as simple as that. We had a really broad mix of all the plugins. How many? It was 30 something of those plugins, if I remember. Different ones. Some were connected with WooCommerce. So, like a very broad selection of them. Different vulnerability types. So we try to mix it up as much as possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:27] <strong>Nathan Wrigley:</strong> Was the situation for each hosting company the same though? In other words, was the things that you did in one hosting environment the exact same as you did in another hosting environment? No. You mixed that up a bit as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:38] <strong>Maciek Palmowski:</strong> I mean we used all the same plugins, like the methodology was always the same. But we got totally different results. Even if, and this was one of the most interesting findings, because very often hostings will put a logo of some company that takes care of security. For example, say, Cloudflare. And despite using the same stack for security, they got different results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:02] <strong>Nathan Wrigley:</strong> Interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:03] <strong>Maciek Palmowski:</strong> So it turns out, in many cases, it&#8217;s not about the tools that you are using, it&#8217;s how you are using them, which was very interesting. And we did everything. We tried to enable every feature, every security features on those hosting, to kind of give them a chance to kind of make sure that they are defending the most as they can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And the result in most cases was very simple. They were doing quite well with the generic ones like uploads, patch reversal, things like this, which are very generic in PHP. But with those WordPress specific attacks, they just failed miserably.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:44] <strong>Nathan Wrigley:</strong> That&#8217;s so interesting. The word secure hosting, which you&#8217;ll see all over the place, it feels a bit like using the word healthy on food. There&#8217;s no real definition of what healthy is. You know, a company selling chocolate could probably pretend that it&#8217;s healthy compared to something else.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:04] <strong>Maciek Palmowski:</strong> Like here, healthy chocolate is exactly, like in some cases secure hosting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:07] <strong>Nathan Wrigley:</strong> Right. So what do you take from this then? I mean basically, is your survey saying that whenever you see the word secure hosting, be sceptical?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:16] <strong>Maciek Palmowski:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:16] <strong>Nathan Wrigley:</strong> Okay. As simple as that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:18] <strong>Maciek Palmowski:</strong> It&#8217;s as simple as that. Because one of the things that we were always promoting, security is not a plugin, it&#8217;s not a one button thing. Security is a process. It&#8217;s layers.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s kind of why we, especially after this report starting kind of using the term, Swiss cheese layer model. Because every layer will fail in some way. That&#8217;s also why you still need all the security solutions that hosting provides, because they do have a lot of interesting solutions against those generic attacks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because they&#8217;re doing really great when it comes to those generic ones. And that&#8217;s great because some of the attacks will be already dealt with. So whatever passes to the second layer, it has less work to do because a lot of it was already stopped at the first layer. The second layer should be something more WordPress specific that understand what is installed. And with this it can catch also a lot of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But still, you have to be prepared that, because again, this layer also isn&#8217;t perfect. Because there are zero days vulnerabilities, there are custom code, there are a lot of things that can happen, that your website will be hacked. I mean, weak password. Simple as that. That&#8217;s why you also need to have a layer, which will be more of what to do if everything else fails. Because you do need to know that you have to inform your clients, all the GDPR related things. How to kind of, I don&#8217;t know, use the backups.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In short you need to have procedures. You have to be prepared before the attack happens. Because let&#8217;s be honest, asking some lawyers about, what should we send to our clients? The moment when, well, the milk is already spilled. It&#8217;s like the worst moment to think about it. Especially that, hey, your website was just hacked. It&#8217;s not just a technical problem, it&#8217;s also a business problem. Again, with those GDPRs and everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, the more layers, the better. You still need to remember, every layer can fail in some place. That&#8217;s why the more, the better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:29] <strong>Nathan Wrigley:</strong> Would you like to see a standard industry-wide definition of something like a badge or, I don&#8217;t know, let&#8217;s say for example, that you put the word secure hosting on your website, that has to actually stand for something.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because obviously coming from the background that you do with a broad oversight on what that is, you have a vast amount of data at your disposal. You can see all of this kind of stuff. But every company can make the claim that our food is healthy, our hosting is secure. But I don&#8217;t know, in the model that we&#8217;ve got where any company can put anything they like on a website, I don&#8217;t really know how you do that, but some sort of accreditation or something. I don&#8217;t know.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:08] <strong>Maciek Palmowski:</strong> Honestly, it&#8217;s really difficult because as I said before, a lot of companies using the same tools were failing in different ways. So that&#8217;s a problem. On the other hand, like sometimes the, those stupid things like weak passwords. And it doesn&#8217;t matter that you had a, let&#8217;s call it a certified secure hosting, you still failed because your password was weak, you know? So, also certificates like this can backfire because some people might think I have a secure hosting, I don&#8217;t have to worry about things. And then you have 10 admin accounts for everyone.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:43] <strong>Nathan Wrigley:</strong> Is there is there something, some mark of that description that you, personally, that you go looking for though? Is there some credentialing system which you think actually does carry some weight? So for example, I don&#8217;t know, like the insurance space or the accountancy space or something like that. You have to have that accreditation in order to do business. Is there something like that? Is there a mark which hosting companies can apply for which you could have some confidence in it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:17:13] <strong>Maciek Palmowski:</strong> Okay. So for sure one of those things would be, and I don&#8217;t want to say it as an advertisement, but it is a thing that you see that the hosting is thinking a bit better about security, kind of looking if they are a Patchstack partner. Because this kind of automatically means that they do have this WordPress, the security WordPress layer. So that&#8217;s already a good sign.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, I would start with this. I think that&#8217;s kind of one of the simplest ways, but again, Patchstack isn&#8217;t the only solution that does it. So looking for partners of such companies might be the best way to start because having those Patchstack aware security solutions built in, into the hosting is a really good sign.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:05] <strong>Nathan Wrigley:</strong> Yeah, okay. Now, the inevitable conversation in the year 2026 is AI. It doesn&#8217;t matter which area of WordPress you&#8217;re talking about. AI manages to get in somewhere. I am presuming that the landscape in terms of security only got more complicated because of AI. Because I&#8217;m imagining that attacks that needed to be conceived by a human can now be conceived in a fraction of the time by an AI agent. But not just one, maybe a dozen or a thousand or whatever it may be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Let&#8217;s just talk about that for a moment. It feels almost as if AI and security are like, that&#8217;s a real systemic problem for the future of the entire industry. Because these things can happen so fast, a plugin vulnerability is discovered by an AI agent. It then discovers the attack surface, implements the attack all in a matter of seconds, possibly. What&#8217;s the position? Like, how do we stay calm basically in the year 2026?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:09] <strong>Maciek Palmowski:</strong> So the problem already existed around a year ago, because a year ago when we did our State of WordPress Security Report, we already saw that vulnerabilities are being used after around five hours after kind of being published. So five hours. That&#8217;s the first thing, because we still have a lot of people that say, yeah, just update your WordPress weekly and you&#8217;re good to go. No, you&#8217;re not. Looking at this number, you have five hours.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:39] <strong>Nathan Wrigley:</strong> Okay. Let&#8217;s just parse that at the moment. So the vulnerability is published. So there&#8217;s a whole thing there, like the vulnerability may well have been discovered prior to being published, so that&#8217;s a whole other thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:52] <strong>Maciek Palmowski:</strong> So first the vulnerability is discovered. Then at least how it works on, with our bug bounty. We inform the vendor they have, let&#8217;s say around a month to fix it. When they fix it, we publish everything and, yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:09] <strong>Nathan Wrigley:</strong> Okay, so from the moment you publish, you can then detect that that is being leveraged within a space of five hours.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:17] <strong>Maciek Palmowski:</strong> Yes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:17] <strong>Nathan Wrigley:</strong> Okay, that&#8217;s really interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:19] <strong>Maciek Palmowski:</strong> But there is a problem. There is a really big problem. So if the vendor doesn&#8217;t respond, we still publish it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:26] <strong>Nathan Wrigley:</strong> How long do you give them? Is it like.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:27] <strong>Maciek Palmowski:</strong> It is the one month.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:28] <strong>Nathan Wrigley:</strong> Okay, thirty days.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:30] <strong>Maciek Palmowski:</strong> Of course, if they reach out that there is some problem, they need like extra days. But in most cases, we&#8217;re talking about the vendors that just don&#8217;t respond at all. We publish it anyway.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the problem is that, from all the vulnerabilities that were discovered last year, 50% weren&#8217;t patched at the moment of publishing about it. 50%.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:50] <strong>Nathan Wrigley:</strong> So half of the plugins where there was a known vulnerability, the vendor had been informed, they&#8217;d had this 30 day window. Half of them made no amendment to their code.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:01] <strong>Maciek Palmowski:</strong> Exactly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:02] <strong>Nathan Wrigley:</strong> Okay. Wow, okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:03] <strong>Maciek Palmowski:</strong> Again, going back to this classical, yeah, just update your WordPress regularly. No.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:08] <strong>Nathan Wrigley:</strong> No, that&#8217;s a really different surface, isn&#8217;t it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:11] <strong>Maciek Palmowski:</strong> It doesn&#8217;t work on so many levels. Because not only the problem is with the fact that, still the famous five hours, which also, it&#8217;s five hours now. It was much longer a few years ago. On the other hand, yeah, most of those, I mean around half of it aren&#8217;t patched, so the attacks will happen quicker than it get patched. So yeah, there is a lot of problems like this. And also the problem with security is that it&#8217;s really difficult to sell.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:39] <strong>Nathan Wrigley:</strong> It&#8217;s like insurance, isn&#8217;t it?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:40] <strong>Maciek Palmowski:</strong> Yeah. But insurance, okay, you see your car, your house, it&#8217;s real. It&#8217;s real, you kind of see it. The only category of websites that it&#8217;s much easier to kind of explain is e-commerce.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:54] <strong>Nathan Wrigley:</strong> Yes. You can feel the tightening on your wallet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:56] <strong>Maciek Palmowski:</strong> They literally see the money. They can kind of really, okay, one hour of my website not working equals this and this Złotys or Euros or whatever. So that&#8217;s easier to explain. But for most people, yeah, security, meh.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:11] <strong>Nathan Wrigley:</strong> Yeah. That&#8217;s really interesting. So you mentioned, about this survey, you mentioned that fully 80% of your penetration testing resulted in something. What were the sort of, the high level items? Apart from that 80% figure. What were some of the other, because you said there were a few interesting things that dropped out of it. Can you mention anything else?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:31] <strong>Maciek Palmowski:</strong> So like I said, one of the things was that we learned that, despite using the same tools, we got different results. That was also a surprise for us.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:39] <strong>Nathan Wrigley:</strong> So let&#8217;s just figure that out. So at hosting company A, we&#8217;ve got a WordPress website with the same collection of plugins in. Hosting company B, exactly the same as far as you can make it the same, but things are different.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:52] <strong>Maciek Palmowski:</strong> No, no, they are, for example, they&#8217;re using for security the same tools.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:56] <strong>Nathan Wrigley:</strong> Right, okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:57] <strong>Maciek Palmowski:</strong> So in theory, if they&#8217;re using the same tools, we should have exactly the same results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:03] <strong>Nathan Wrigley:</strong> So does that then point to a different set of configurations on the backend, or is it more curious than that? You just don&#8217;t quite know what&#8217;s going on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:12] <strong>Maciek Palmowski:</strong> I mean because it&#8217;s not something that they will tell us. But yeah, in most cases, it&#8217;s all about configuration because the fact that you&#8217;re using a tool, it&#8217;s also important how you use a tool.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Also, with security is very often about, is something easy to use or is something secure? And kind of finding the balance. So some of the companies probably had a bit more aggressive configuration, which is better from the security point of view, but probably more often result in some annoying side effects for the user.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Also what, this was one of the most interesting things, but also what was very interesting because we contacted every company afterwards and we informed them that we did the test. Here are the results, what went through, what was blocked. And some of the companies did an amazing job of fixing whatever they could. On the other hand, we saw that some of the companies, because we did some extra tests later just to check what they did with our report, did nothing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s one of the things about security in general, not about the hosting, about even having vulnerability in your plugin. That&#8217;s normal that we make mistakes. We&#8217;re humans, right? So that&#8217;s normal. What&#8217;s important is how we deal with them. If you have a problem and you fix it as quickly as possible, as good as possible, that&#8217;s great because you learn from your mistakes, you fix it, and you move on. Perfect. Good job. Now you are in a much better position than before. But if you get this, you look at it and you say, ah, this is fine, that&#8217;s the worst behaviour from the security point of view that you can have.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:57] <strong>Nathan Wrigley:</strong> I&#8217;m going to ask you not to name names here, but were some of the companies familiar to us?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:05] <strong>Maciek Palmowski:</strong> For sure, because we did test the biggest ones. But there is a reason why we didn&#8217;t want to name them, and it wasn&#8217;t about that we were afraid that I know someone will get mad or whatever. It was more about this weird side effect that could happen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Some users would think, my hosting isn&#8217;t on this list, so probably I&#8217;m secure. Probably you&#8217;re not, you just weren&#8217;t in the test. Because we also did some site checks and everything. And we saw that a lot of those problems happen at most of the hosting companies. And like I said, the more important part was how did they reacted after getting the report. Like I said, it was a more common problem that we even thought.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:43] <strong>Nathan Wrigley:</strong> Do you, obviously, you know, caveat all of this with the fact that you work for Patchstack and what have you, do you see it even as the role of a hosting company to have any position on security publicly? Or would you prefer them not to make grand claims about things that you believe they can&#8217;t necessarily substantiate?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t really know where I&#8217;m going with that question, but I&#8217;m just wondering if there&#8217;s just a sense that the language that&#8217;s being used is too strong. You know, secure hosting implies we&#8217;ve got all the padlocks, and the padlocks are there and you&#8217;ve got nothing to worry about. You&#8217;ve found a different picture. So I&#8217;m just wondering whether or not you would just prefer that the hosting companies stop talking about this altogether.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:27] <strong>Maciek Palmowski:</strong> I do think that&#8217;s, one of the biggest problem here is about the claims, the bold claims, the whole marketing around it. Sometimes even you can find documentation of some of them that, yeah, you don&#8217;t need to install any third party tool because we got you covered. We checked it, no they didn&#8217;t. So that&#8217;s kind of the problem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s really more about the, how they market it. If they would say, okay, so we have a really performant hosting that does this, this and this. When it comes to security, kind of do it yourself. I mean we are providing this layer, but the rest is up to you. And that&#8217;s okay. That&#8217;s an honest claim. We are not doing everything for you. We are doing this part, but this is up to you. This would be much better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I know that from the marketing point of view, it doesn&#8217;t sound as good as, we got all the security that you can imagine, don&#8217;t have to worry about this. Because that&#8217;s kind of the thing that very often managed hosts trying to sell, that you don&#8217;t have to worry about things. You just have to focus on whatever you have, writing content, selling stuff. If you have a e-commerce, whatever, that&#8217;s it. That&#8217;s kind of the only thing you should think of. Not about performance, because we got your back. Not about security, again, we got your back. And if you are paying for a managed hosting and suddenly they would start having like this different way of messaging to, it&#8217;s not that obvious that we have your back in everything. That would be very difficult for them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now it&#8217;s kind of the problem that, because everyone is kind of using this messaging, everyone else also has to. And also if we think about how a lot of those algorithms, look like that algorithms love bold claims. They want something white or black, not grey. And the truth is, most of the things we are talking about, it doesn&#8217;t matter, security, SEO performance, it&#8217;s everything in the grey zone. That&#8217;s why a lot of developers can end their talk with, yeah, it depends. There is no right or wrong. It depends because there are so many things you have to think about.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I could say that, and this is my kind of thing that, most of the websites that people have should be static. They don&#8217;t need even WordPress at all. This is a horrible claim if you&#8217;re a manager of a WordPress hosting, right? So that&#8217;s the thing. But it all depends on so many things, but yeah, the messaging is important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:08] <strong>Nathan Wrigley:</strong> Yeah, if you were, on a personal level, if you were going out there looking and let&#8217;s say, if you can somehow put your job hat to one side, what would be the kind of things that you would be looking for? What questions would you be asking related to security if you were to be going to these companies?</p>\n\n\n\n<p class=\"wp-block-paragraph\">From everything that you said, obviously it&#8217;s not black, it&#8217;s not white, it&#8217;s definitely grey. So every setup has some way of being vulnerable. But what are the kind of intelligent questions that you would be bringing to hosts to get some reassurance that at least they appear to know what they&#8217;re doing, even if they can&#8217;t make the claim that they&#8217;re a hundred percent cast iron, water tight? What might be some intelligent questions to start asking?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:49] <strong>Maciek Palmowski:</strong> One of the best questions you can ask is just, is there any solution in your security stack that is WordPress aware? Not the general one. Because if they only start talking about some web firewall, things like this, it&#8217;s already kind of a red flag. Because this is, overall, if we&#8217;re talking about firewalls, that&#8217;s not the correct layer about which, this is the generic one.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So this is the main question. How do you take care of WordPress specific attacks? Simple question. And if they will start responding, yeah, that we have this web application firewall that, in most cases this will be a sign that, no, we are not talking about the correct layer. That&#8217;s not it. It&#8217;s probably not aware about what is happening in WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:40] <strong>Nathan Wrigley:</strong> Okay. So given that this is a WordPress podcast, and we are at a WordPress event, that would be the beginning of your questioning is demonstrate that something in your stack is specific to WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:52] <strong>Maciek Palmowski:</strong> Exactly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:53] <strong>Nathan Wrigley:</strong> Okay. And beyond that, is there any questions that, so let&#8217;s imagine that they come back with, yes, we have something specific, it&#8217;s WordPress. What would be sort of sensible follow up questions?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:00] <strong>Maciek Palmowski:</strong> I mean you can kind of start off about, okay, what exactly you are using? Because there is a limited amount of tools that are really WordPress aware. So if they will answer with kind of a product name, that&#8217;s kind of the easy way that then you can check it on your own. But that&#8217;s kind of the thing. Is it WordPress aware?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:19] <strong>Nathan Wrigley:</strong> Does it worry you in some way that there&#8217;s this perception out there that WordPress is insecure? You know, if you ask a thousand people, you&#8217;d maybe get 800 saying, oh WordPress, you know, we&#8217;re not touching that with a barge pole.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do you worry that content like this, that you are putting out, that that might fuel that fire? Does it concern you in any way that it might lean into the argument that, I don&#8217;t know, somebody can link to that blog post from a rival CMS, or a SaaS platform, which does something similar to WordPress? Where do you sit on that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:51] <strong>Maciek Palmowski:</strong> That&#8217;s a really difficult question. And this is one of the questions that when I talk on non WordPress events, I love to ask people. Is WordPress secure? And in most cases, I see that most of the room is, yes, it&#8217;s unsecure for sure. And I&#8217;m like, no, that&#8217;s not true. WordPress is secure. Every year there is just a few minor vulnerabilities in Core. That&#8217;s it. The problem is, of course, that WordPress on its own lacks some functionality. That&#8217;s why we install plugins.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And here we enter another problem because, okay, every year we have like thousands of those vulnerabilities in general in plugins. On the other hand, we have thousands of plugins. So kind of statistics will always look bad. But that&#8217;s why every time when you want to select a new plugin, you need to do some research. Yeah, I know it&#8217;s boring and everything but, hey, now we have AI, you can do it much quicker. It can help you a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But looking at all those databases, for example, we have one database, WPScan has. There are those databases of WordPress vulnerabilities that occur to every plugin. And you can see, is the plugin you&#8217;re interested in had a lot of vulnerabilities? On the other hand, how it kind of looked historically. It&#8217;s not just about the number of them. In general, it requires some research.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And yeah, if we are just like looking at this, and this kind of vibe that right now we have that we are just about really bold opinions stated quickly that will fit one TikTok, yeah, WordPress is in a horrible position because, let&#8217;s be honest, it&#8217;s like, if you have, I&#8217;m not sure how many seconds does a TikTok movie has?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:39] <strong>Nathan Wrigley:</strong> I think 30.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:40] <strong>Maciek Palmowski:</strong> Okay, let&#8217;s say 30. So it will sound much better that you will say, yeah, WordPress is unsecure, which is not entirely true because it depends again. One of the most boring, especially again for those algorithms and everything, it&#8217;s a grey zone.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because we are collaborating with a lot of companies that are making plugins, and we see how their security flow looks like. How they are dealing with vulnerabilies that are discovered. And honestly, I&#8217;m amazed how well some of those companies are doing it. They are very serious about it. They understand how important it is. For them it&#8217;s something very important.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:22] <strong>Nathan Wrigley:</strong> I suppose WordPress is a victim of its own success in that sense. And it would be a bit like, I guess a good analogy might be if you&#8217;ve got a car manufacturer and they produce a thousand cars a year and you compare them to Ford who make, let&#8217;s say, I don&#8217;t know, 20 million a year. And the question is, well, whose cars break down more often?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:41] <strong>Maciek Palmowski:</strong> Yeah. Do we look at the percentage of the number?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:34:44] <strong>Nathan Wrigley:</strong> Right. And if you say, well, 400,000 Fords broke down last year, and one of these other manufacturer, you can immediately see why there&#8217;s a problem there. And that I think is the landscape in which WordPress is often painted. The reason there&#8217;s lots of publications like yours bringing out WordPress information is because it&#8217;s the most popular thing. It makes sense to write about the most popular thing and to try to find the vulnerabilities and disclose them in a sensible way. So I don&#8217;t know what we do with that. It is just the way it is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:15] <strong>Maciek Palmowski:</strong> I would also say there is one more interesting aspect because WordPress is considered unsecure because of the plugins. But what&#8217;s funny, for example, Elementor is also considered unsecure because there are plugins for Elementor. This is a very weird moment when the thing that brought WordPress to its bigger success, security wise, is its biggest problem right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because WordPress did a lot of, I mean it was always great to, being as it&#8217;s kind of, let&#8217;s call it entry level CMS. For many people, it was also the way how they began the adventure with PHP development because it was so easy. Now we kind of have the, all the consequences of being that easy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:06] <strong>Nathan Wrigley:</strong> Yeah, in a sense, this is going to sound ridiculous, we should be glad that there&#8217;s people talking about WordPress vulnerabilities, because it means the project is successful. And it also means that it&#8217;s, there&#8217;s an industry of WordPress security solutions, and there are people who take this very seriously and dedicate their lives to it. And you may not find that in some of these other ones, you know, some of the smaller CMSs and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think we&#8217;ve probably hit about the sweet spot for the amount of time. But Maciek, I don&#8217;t know if there was anything in that report that you have got lined up in your presentation that I never got to. If there was a particular thread that you wanted to pull. If there is, go for it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:46] <strong>Maciek Palmowski:</strong> No, I think we covered all the important things. And as you kind of said, this AI aspect, this will change so many things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:55] <strong>Nathan Wrigley:</strong> Yeah, we&#8217;ll come back in two years and this conversation will be a very different thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:57] <strong>Maciek Palmowski:</strong> Oh, I think even in few months which will be very interesting. Yeah, so this aspect, it&#8217;s really very surprising. And I think that everyone who is right now kind of giving somewhere a talk about AI and security is in a very difficult spot because.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:14] <strong>Nathan Wrigley:</strong> Yeah, your content is going to look stale quickly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:16] <strong>Maciek Palmowski:</strong> Yeah because you know it&#8217;s like, but a week ago everything changed. Yeah, I have to rewrite everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:20] <strong>Nathan Wrigley:</strong> Speaking of which, by the time that this goes out, hopefully you have managed to give out your presentation at WordCamp Europe. I will link to it and anything else that we&#8217;ve mentioned today in the WP Tavern post. So go and check that out. But I will specifically link to the wordpress.tv version of your presentation, which no doubt will have been created by then. So Maciek, thank you for chatting to me today. Good luck. I hope presentation goes well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:43] <strong>Maciek Palmowski:</strong> Thank you. Thank you so much. Yes. I might need a bit because, you know, it&#8217;s WordCamp Europe. It&#8217;s a big conference.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:49] <strong>Nathan Wrigley:</strong> It is, yeah. Good luck. I hope that you manage to stay calm.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:52] <strong>Maciek Palmowski:</strong> Thank you.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/maciekpalmowski/\">Maciek Palmowski</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maciek is based in Poland and works at <a href=\"https://patchstack.com\">Patchstack</a>, one of the companies in the WordPress ecosystem dedicated specifically to security. At Patchstack, Maciek collaborates with other security professionals on industry reports, bug bounty programs, and solutions for agencies, product owners, and hosting companies aiming to secure their client sites.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I met up with Maciek at WordCamp Europe in Kraków, and we discussed his presentation there. It examined the claims of “secure hosting” made by many WordPress hosting providers. He describes how Patchstack set out to test these claims with real-world penetration testing, using 30 known plugin vulnerabilities across multiple hosts, employing standardised methodologies, and validating their results independently. The findings are sobering. The majority of WordPress-specific attacks still get through, and there’s a significant gap between the marketing hype and real protection.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation starts with Maciek’s background and how his journey in the WordPress security space led to a focus on the promises made by hosts. From there, the discussion gets into the research approach: the selection of well-known vulnerabilities, consistent testing across different hosting environments, and the surprising result that even hosts with identical security tooling produced drastically different outcomes, showing it’s not just about what tools you use, but how you use them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We talk about the “Swiss cheese” model of security, every layer will have holes, so you need multiple, overlapping defenses, and honest communication from hosts about their limitations. We also explored whether an industry-wide standard or badge for “secure hosting” is feasible or even desirable, given how easy it is for strong marketing claims to outpace reality.</p>\n\n\n\n<p class=\"wp-block-paragraph\">AI also enters the conversation, increasing both the speed and sophistication of attacks, and making patching and processes even more important, especially as the volume of vulnerabilities continues to rise and the time to exploitation drops.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re interested in understanding what “secure hosting” really means, how to ask intelligent questions of providers, and the realities of WordPress security in 2026, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://patchstack.com\">Patchstack</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://checkoutsummit.com\"> Checkout Summit</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://europe.wordcamp.org/2026/session/testing-the-promise-does-secure-hosting-deliver/\">Testing the promise: does secure hosting deliver?</a> &#8211; Maciek&#8217;s presentation at WordCamp Europe 2026. It includes the video of the presentation.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://patchstack.com/whitepaper/state-of-wordpress-security-in-2026/\"> State of WordPress Security in 2026 Report</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wpscan.com\">WPScan</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 29 Jul 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:31;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"Open Channels FM: Navigating Client Expectations in the Age of AI-Assisted Web Design\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2557092\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://openchannels.fm/navigating-client-expectations-in-the-age-of-ai-assisted-web-design/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:224:\"The growing use of AI tools is reshaping web design, as clients increasingly present AI-generated content. Education and proactive communication are essential for web professionals to navigate these complexities effectively.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}