INSERT INTO `wp_postmeta` VALUES (185,52,'_bp_description','Биринчи гипермаркет 2011-жылы ачылган. 13 жылдан бери \"Asia\" соода түйүнү Кыргызстандын тургундарын жана чет элдик конокторду соода кылуунун жагымдуу тажрыйбасы менен кубандырып келет. Бул убакыт аралыгында ал Бишкек жана башка аймактарда 59 дүкөнгө чейин кеңейди.');
